WordHunterWoW_QuestEN[39372] = { title = "Witch of the Wood", description = "You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you're alive here now. I consider my debt to you paid.\n\nYou must prove yourself to the Bloodtotem chieftain before he will speak with you.\n\nWithin the forest is the Witch of the Wood, a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.", objectives = "" }
WordHunterWoW_QuestEN[39373] = { title = "Hags of a Feather", description = "The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn't stop the Bloodtotem from going on the offensive just in case, capturing some of their number.\n\nThat move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.", objectives = "" }
WordHunterWoW_QuestEN[39374] = { title = "An Audience with Torok", description = "I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard.\n\nWe will seek an audience with him at his tent at the Cliff's Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.", objectives = "" }
WordHunterWoW_QuestEN[39381] = { title = "Rock Troll in a Hard Place", description = "We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people.\n\nLet me know when you are ready to go, and I can take us to a safe place quickly.", objectives = "" }
WordHunterWoW_QuestEN[39383] = { title = "Dishonored", description = "Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius.\n\nDuring the great war, it was he who led the slaughter of many of my dearest friends.\n\nThe last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.", objectives = "" }
WordHunterWoW_QuestEN[39384] = { title = "The Corruptor", description = "Xandris has been slain, but there are others that must be dealt with if my grove is to be saved.\n\nDuring the great war, Kagraxxis took great pleasure in corrupting the lands he once called home.\n\nWere it not for the foolish mercy of my fellow druids, I would have slain him myself.\n\nFind the demon and bring justice upon him.\n\nI must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.", objectives = "" }
WordHunterWoW_QuestEN[39385] = { title = "A Gift for Greymane", description = "It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing.\n\nIf these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.", objectives = "" }
WordHunterWoW_QuestEN[39386] = { title = "Procuring a Prototype", description = "If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size.\n\nMy munitions expert should have some ideas about what kind of weapon would best suit a gnome.\n\nStop by his camp and let him know that I'll be needin' a prototype soon.", objectives = "" }
WordHunterWoW_QuestEN[39387] = { title = "The Skies of Highmountain", description = "When you are ready, join me at the base of Thunder Totem.\n\nI would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla.\n\nTogether, we are Highmountain!", objectives = "" }
WordHunterWoW_QuestEN[39388] = { title = "Moonclaw's Wisdom", description = "Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius.\n\nStill, there is much about these satyrs that I wish to tell you. This information would be most valuable to you.\n\nPlease meet me in my den before departing.", objectives = "" }
WordHunterWoW_QuestEN[39389] = { title = "It Hungers for Blood", description = "Bloodstones contain a great deal of power that can only be awakened once they are fed. \n\nYet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better.\n\nThere's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.", objectives = "" }
WordHunterWoW_QuestEN[39390] = { title = "A Mysterious Text", description = "You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.", objectives = "" }
WordHunterWoW_QuestEN[39391] = { title = "Pet Rocks", description = "I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me.\n\nIf they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.", objectives = "" }
WordHunterWoW_QuestEN[39392] = { title = "Bear Huntin'", description = "They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will.\n\nSome lesser hunters have been a meal for those bears. \n\nShow me you're more than a snack and bring me back a few of those bristlefur pelts.", objectives = "" }
WordHunterWoW_QuestEN[39394] = { title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", objectives = "" }
WordHunterWoW_QuestEN[39395] = { title = "Oronok's Offer", description = "", objectives = "" }
WordHunterWoW_QuestEN[39401] = { title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", objectives = "" }
WordHunterWoW_QuestEN[39404] = { title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", objectives = "" }
WordHunterWoW_QuestEN[39405] = { title = "Stories of Battle", description = "The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. \n\nIf Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. \n\nThe answer to her involvement likely lies within the remaining text.", objectives = "" }
WordHunterWoW_QuestEN[39417] = { title = "Rating Razik", description = "Hemet is expecting an update on how my munitions research and development is going.\n\nI'm sure you'll be happy to tell my boss that my latest creation worked flawlessly!\n\nYou can find him at his camp near the hunters' lodge.", objectives = "" }
WordHunterWoW_QuestEN[39419] = { title = "Hex-a-Gone", description = "The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them.\n\nThe Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[39422] = { title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Lunarfall and check in with Merreck?  Every ship we build gives us another advantage over Gul'dan's new Horde.", objectives = "" }
WordHunterWoW_QuestEN[39423] = { title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Frostwall and check in with Rolosh?  Every ship we build gives us another advantage over Gul'dan's new Horde.", objectives = "" }
WordHunterWoW_QuestEN[39425] = { title = "Stonedark Crystal", description = "Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now.\n\nI'm sure one of the Feltotem has it. If you find it, please return it to me.", objectives = "" }
WordHunterWoW_QuestEN[39426] = { title = "Blood Debt", description = "You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive.\n\nTorok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.", objectives = "" }
WordHunterWoW_QuestEN[39427] = { title = "The Eagle Spirit's Blessing", description = "The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge.\n\nIf you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.", objectives = "" }
WordHunterWoW_QuestEN[39429] = { title = "Assaulting the Haglands", description = "Proceed on foot into the Haglands and slay any harpies you find.\n\nQuell their numbers!\n\nWe will provide air support and force your prey to the ground where you can deal with them.\n\nShow these witches the fury of your... well... your \"you.\"", objectives = "" }
WordHunterWoW_QuestEN[39430] = { title = "Flasking for a Favor", description = "You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired.\n\nI'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker. He's a smith by trade, but those who know him say he was born to work glass.\n\nThose tauren don't work for free, so you may be in for some work yourself.", objectives = "" }
WordHunterWoW_QuestEN[39431] = { title = "Mending the Filter", description = "Bringing back the cloth in such a manner would not be beneficial to Deucus.\n\nPerhaps there's a tailor here in Val'sharah who'd be willing to mend it for you.\n\nThe priestess who helped you earlier may know of such a person.", objectives = "" }
WordHunterWoW_QuestEN[39432] = { title = "Unknowable Power", description = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", objectives = "" }
WordHunterWoW_QuestEN[39433] = { title = "Unseen Influence", description = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", objectives = "" }
WordHunterWoW_QuestEN[39436] = { title = "Haglands Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39437] = { title = "Deep in the Cavern", description = "We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. \n\nKill a few of them so they know they don't run things around here.", objectives = "" }
WordHunterWoW_QuestEN[39438] = { title = "Guhruhlruhlruh", description = "The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave.\n\nKill their leader. I think its name is something like \"Guhruhlruhlruh.\"", objectives = "" }
WordHunterWoW_QuestEN[39439] = { title = "Stonedark Relics", description = "The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern.\n\nWhile we warm up, do you think you could go find them?", objectives = "" }
WordHunterWoW_QuestEN[39440] = { title = "You Lift, Brul?", description = "Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.", objectives = "" }
WordHunterWoW_QuestEN[39455] = { title = "Cave of the Blood Trial", description = "All Bloodtotem and distinguished guests must go through a trial of blood in the cavern beneath this outpost.\n\nI hope it's a good sign that they wish you to participate in this rite of passage. You will need to show proof of your deeds, defeat a Warmonger in single combat, then perform sacrifice at an altar deep in the cavern.", objectives = "" }
WordHunterWoW_QuestEN[39456] = { title = "Unexpected Allies", description = "You have gained my trust. Not all drogbar are as violent as the savages led by Dargrul the Underking, nor are all tauren as bloodthirsty as the Bloodtotem.\n\nYou may tell Mayla Highmountain that she has our support. The cavern we call home is yours to explore freely as well, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39472] = { title = "Cut Out the Heart", description = "This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from.\n\nIf you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.", objectives = "" }
WordHunterWoW_QuestEN[39487] = { title = "Crystal Fury", description = "A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself.\n\nWe must destroy him before he gets too powerful.\n\nHe is in the upper caverns.", objectives = "" }
WordHunterWoW_QuestEN[39488] = { title = "Balance of Elements", description = "The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power.\n\nWe must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.", objectives = "" }
WordHunterWoW_QuestEN[39489] = { title = "Invading Spelunkers", description = "The drogbar and their earthen furies have overrun the cavern. They're perverting the magic within and destroying the elementals that have forever dwelled in this place.\n\nLet's work together to remove them from this sacred cave.", objectives = "" }
WordHunterWoW_QuestEN[39490] = { title = "Infestation", description = "Those bugs are destroying our crops and attack any of us who get near them.\n\nWould you exterminate some of those vile creatures?", objectives = "" }
WordHunterWoW_QuestEN[39491] = { title = "Ormgul the Pestilent", description = "We've lived at peace with the drogbar for years--our tribe even more than the others. But we were betrayed in our last trade with them at Riverbend.\n\nThey usually supply us with potent alchemy to prevent insects from infesting our fields. This time, led by Ormgul, they have attacked the crops that sustain us all.\n\nOrmgul the Pestilent is the one who brought the infection to our farmland. Destroy him, and bring me whatever he uses to attract the bugs to our land.", objectives = "" }
WordHunterWoW_QuestEN[39492] = { title = "Fishing Supplies", description = "The drogbar scattered our supplies everywhere! They ate whatever they felt like, scattered some of the smaller fish onto the shore, and smashed through the fishery like a hungry ettin on a rampage.\n\nWhile you are in the field, please bring back any of the supplies you can find.", objectives = "" }
WordHunterWoW_QuestEN[39493] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39495] = { title = "Hidden No More", description = "Now that you've uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can.\n\nIf you can deal with their leader, we will take care of the rest of his forces in that cave.", objectives = "" }
WordHunterWoW_QuestEN[39496] = { title = "The Flow of the River", description = "We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced.\n\nBut we aren't out of hot water just yet, {name}. The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.", objectives = "" }
WordHunterWoW_QuestEN[39498] = { title = "High Water", description = "Riverbend! Is that what the Underking said?\n\nThat is my home and the place where we store our winter supplies. We must make it there at all speed and warn them.\n\nMeet me there.", objectives = "" }
WordHunterWoW_QuestEN[39499] = { title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", objectives = "" }
WordHunterWoW_QuestEN[39500] = { title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", objectives = "" }
WordHunterWoW_QuestEN[39501] = { title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", objectives = "" }
WordHunterWoW_QuestEN[39502] = { title = "The Fel Spire", description = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights.\n\nIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", objectives = "" }
WordHunterWoW_QuestEN[39504] = { title = "The Fel Spire", description = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights.\n\nIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", objectives = "" }
WordHunterWoW_QuestEN[39505] = { title = "The Fel Spire", description = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights.\n\nIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", objectives = "" }
WordHunterWoW_QuestEN[39506] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39508] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39509] = { title = "Bloodied Blades of Zeth'Gol", description = "Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of 'em carry curved ritual blades for carvin' themselves up.\n\nBring me them blades, commander. We can turn their power against 'em.", objectives = "" }
WordHunterWoW_QuestEN[39510] = { title = "A Little Wetwork", description = "What be left of the Iron Horde is comin' to Tanaan through Ironhold Harbor. If we knew who was comin' and when, we could use our shipyard to cause some chaos.\n\nGo to Ironhold Harbor and fish up some intelligence!", objectives = "" }
WordHunterWoW_QuestEN[39511] = { title = "Blood of Fallen Brothers", description = "Orcs that drink Gul'dan's poison turn into fel beasts. Soulless savages.\n\nLady Liadrin an' the Blood Knights think maybe there be a way back. They be wantin' samples of blood from freshly turned orcs. Get their blood, {name}!\n\nYou be findin' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden is where you find the most.", objectives = "" }
WordHunterWoW_QuestEN[39512] = { title = "Secrets of the Shadow Council", description = "Gul'dan be growin' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don't burn 'em.\n\nCatch his minions out in the open and bring their secrets back to me! You find them workin' with the arakkoa in da Ruins of Kra'nak or atop the Throne of Kil'jaeden.", objectives = "" }
WordHunterWoW_QuestEN[39513] = { title = "Disarming Sha'naar", description = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin' the place. We gotta keep those crystals out of demonic hands, commander!\n\nAttack the mines behind the temple and grab them crystals.", objectives = "" }
WordHunterWoW_QuestEN[39514] = { title = "Harnessing Their Power", description = "Ol' Grommash Hellscream found a way to weaponize the gronn. Vol'jin wants to know how.\n\nTravel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin' help.", objectives = "" }
WordHunterWoW_QuestEN[39515] = { title = "Vengeance Will Be Mine!", description = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.\n\nQuickly, {name}, teach us what you have learned.", objectives = "" }
WordHunterWoW_QuestEN[39516] = { title = "Cry Havoc and Let Slip the Illidari!", description = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.", objectives = "" }
WordHunterWoW_QuestEN[39519] = { title = "Demonslayer of Tanaan", description = "Look to the north, {class}. The sky is turning a sickly green. Gul'dan's summoning portals are not yet at full strength, but already the stench of demon is on the wind.\n\nSlay them, {name}. Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha'naar is infested, as is the Throne of Kil'jaeden, although you may find others wandering about the jungle.", objectives = "" }
WordHunterWoW_QuestEN[39526] = { title = "Pressing the Attack", description = "We got Gul'dan's minions on the run, commander! If you be feelin' it, we should put some pressure on some of his other strongholds as well.", objectives = "" }
WordHunterWoW_QuestEN[39529] = { title = "Tooth and Claw", description = "Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, {class}, calling forth our primal instincts. There is no better way to feel alive than to court death.\n\nJoin me in the hunt, {name}! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!", objectives = "" }
WordHunterWoW_QuestEN[39532] = { title = "Bringing Down the Iron Horde", description = "Ever since the fall of Blackrock Foundry, Gul'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash's banner, through either fear or thirst for revenge, are now embracing the fel.\n\nWade into the battlefields of Tanaan and lay waste to Gul'dan's forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!", objectives = "" }
WordHunterWoW_QuestEN[39565] = { title = "Rumble in the Jungle", description = "Dem fancy cat-men gotta be shown who is da boss 'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle.\n\nY'gonna need dese totems to draw dem out.", objectives = "" }
WordHunterWoW_QuestEN[39566] = { title = "The Search for Knowledge", description = "While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!", objectives = "" }
WordHunterWoW_QuestEN[39567] = { title = "Bloodied Blades of Zeth'Gol", description = "The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors.\n\nThe curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.", objectives = "" }
WordHunterWoW_QuestEN[39568] = { title = "A Little Wetwork", description = "The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon.\n\nPerhaps you could gather some naval intelligence for our cause?", objectives = "" }
WordHunterWoW_QuestEN[39569] = { title = "Breaking Their Fel Bonds", description = "Gul'dan's fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn't give up on the whole race. If you could find samples of their blood, maybe we can reverse the process?\n\nYou'll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden are the most densely populated.", objectives = "" }
WordHunterWoW_QuestEN[39570] = { title = "Secrets of the Shadow Council", description = "Gul'dan has been building a spy network for himself - the so-called \"Shadow Council\". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra'nak or summoning demons at the Throne of Kil'jaeden.\n\nFind members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!", objectives = "" }
WordHunterWoW_QuestEN[39571] = { title = "Disarming Sha'naar", description = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei.\n\n{name}, it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.", objectives = "" }
WordHunterWoW_QuestEN[39572] = { title = "Moozy's Adventure", description = "<Moozy is floating down the river and must be reunited with his mother.>", objectives = "" }
WordHunterWoW_QuestEN[39573] = { title = "Harnessing Their Power", description = "We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how.\n\nVenture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.", objectives = "" }
WordHunterWoW_QuestEN[39574] = { title = "Pressing the Attack", description = "Gul'dan's minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.", objectives = "" }
WordHunterWoW_QuestEN[39575] = { title = "The Path of Huln", description = "Armies are vital to the success of a war. But so are symbols.\n\nFor our people, few things make for a better symbol than the blessings of our most eldest ancestors.\n\nMayla must walk the Path of Huln.\n\nThe path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her.\n\nWill you be the champion?", objectives = "" }
WordHunterWoW_QuestEN[39577] = { title = "An Ancient Secret", description = "Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well.\n\nIt is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.", objectives = "" }
WordHunterWoW_QuestEN[39578] = { title = "Titanic Showdown", description = "The tale of Huln did not end with him acquiring the Hammer of Khaz'goroth.\n\nNo. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead.\n\nCome, let us see what happened next.", objectives = "" }
WordHunterWoW_QuestEN[39579] = { title = "The Backdoor", description = "This will take Mayla some time to adjust to.\n\nThat being said, we should return to Thunder Totem.\n\nJust south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond.\n\nWe keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.", objectives = "" }
WordHunterWoW_QuestEN[39580] = { title = "The High Chieftain", description = "I understand what Ebonhorn has been trying to tell me for a while now.\n\nOur people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so.\n\nAnd between you and me, I am definitely terrified, but resolved.\n\nLet us return to Thunder Totem and prepare ourselves for war.", objectives = "" }
WordHunterWoW_QuestEN[39581] = { title = "Demonslayer of Tanaan", description = "Demons! Hate 'em!\n\nGul'dan is spinning up more summoning portals with each passing hour. There's only one way to stem the tide, {name}.\n\n<Parvink smashes her gauntleted fist against her open palm.>\n\nSmash 'em!\n\nThe Temple of Sha'naar is a good place to start, or head up to the Throne of Kil'jaeden if you're looking for a real challenge.", objectives = "" }
WordHunterWoW_QuestEN[39582] = { title = "Tooth and Claw", description = "These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth!\n\nWhat do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we'll compare our haul!", objectives = "" }
WordHunterWoW_QuestEN[39586] = { title = "Bringing Down the Iron Horde", description = "Ever since we humiliated 'em at Blackrock Foundry, the Iron Horde has been on the run. Gul'dan is converting them all into fel orcs, but I ain't scared. A bloodlusting orc is twice as strong but twice as stupid.\n\nHey! Let's wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn't matter to me.", objectives = "" }
WordHunterWoW_QuestEN[39588] = { title = "They Will Pay With Blood", description = "The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people.\n\nIt looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.", objectives = "" }
WordHunterWoW_QuestEN[39590] = { title = "Ahead of the Game", description = "The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see.\n\nIf you wish to catch his eye, show him you are worth being seen.\n\nSome of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.", objectives = "" }
WordHunterWoW_QuestEN[39591] = { title = "A Trial of Valor", description = "To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face.\n\nAbove us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.", objectives = "" }
WordHunterWoW_QuestEN[39592] = { title = "A Trial of Will", description = "Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim's Peak. \n\nBe on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.", objectives = "" }
WordHunterWoW_QuestEN[39593] = { title = "The Shattered Watcher", description = "When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body.\n\nI cannot allow a contender to pass through the vault while I remain unwhole. \n\nHis forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.", objectives = "" }
WordHunterWoW_QuestEN[39594] = { title = "A Trial of Might", description = "I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. \n\nGo now into the vault. There you will find the archive for the first trial you must undertake.\n\nI will meet you inside.", objectives = "" }
WordHunterWoW_QuestEN[39595] = { title = "Blood and Gold", description = "The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. \n\nIt might be a good idea to take some of these offerings with you to help in appeasing Yotnar.", objectives = "" }
WordHunterWoW_QuestEN[39597] = { title = "The Blessing of the Watchers", description = "As is your due for passing the Trial of Might, I will grant you the blessing of the watchers. \n\nFurthermore, to aid you in your trials to come, I will bestow upon your artifact the power of the vault's keeper. May it serve you well in your time of need.\n\nSpeak to me when you are ready to receive this gift.", objectives = "" }
WordHunterWoW_QuestEN[39601] = { title = "I Sunk Your Battleship", description = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.\n\nWe have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!", objectives = "" }
WordHunterWoW_QuestEN[39602] = { title = "Where's Lyndras: Sewer Sleuthing", description = "Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts.\n\nHopefully he hasn't caused any more commotion amongst the citizens of Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[39604] = { title = "I Sunk Your Battleship", description = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.\n\nWe have heard reports from Tanaan that a new Horde faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!", objectives = "" }
WordHunterWoW_QuestEN[39605] = { title = "Where's Lyndras: Downward Spiral", description = "Flitz mentioned a manhole near Violet Hold, perhaps that would be the best place to pick up Lyndras' trail.", objectives = "" }
WordHunterWoW_QuestEN[39614] = { title = "Fish Out of Water", description = "The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore.\n\nWorst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.", objectives = "" }
WordHunterWoW_QuestEN[39645] = { title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes.\n\nMyshalla Streambreeze in Feralas has demonstrated admirable attention to detail.\n\nI loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.", objectives = "" }
WordHunterWoW_QuestEN[39648] = { title = "Where Are the Children?", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.", objectives = "" }
WordHunterWoW_QuestEN[39649] = { title = "Menacing Grumplings", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", objectives = "" }
WordHunterWoW_QuestEN[39651] = { title = "Grumpus", description = "One of Draenor's oldest stories is the legend of Grumpus.\n\nThe story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions.\n\nBut Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!", objectives = "" }
WordHunterWoW_QuestEN[39652] = { title = "Where Dragons Rule", description = "Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes.\n\nShe has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. \n\nWould you join us?", objectives = "" }
WordHunterWoW_QuestEN[39654] = { title = "Odyn and the Valarjar", description = "Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself.\n\nI will take you to Odyn now, follow me.", objectives = "" }
WordHunterWoW_QuestEN[39655] = { title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", objectives = "" }
WordHunterWoW_QuestEN[39656] = { title = "Wolf Pack Attack", description = "It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot.\n\nThe critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders.\n\nHappy hunting!", objectives = "" }
WordHunterWoW_QuestEN[39657] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[39658] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[39659] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[39661] = { title = "Lifespring Cavern", description = "The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain.\n\nMeet me there and we will cleanse that sacred place of these dark-dwellers.", objectives = "" }
WordHunterWoW_QuestEN[39663] = { title = "On Felbat Wings", description = "It is time. We have dealt the Legion's forces a crippling blow from which they will never recover.\n\nQuickly, let us mount up and take the fight to Tyranna's command center.", objectives = "" }
WordHunterWoW_QuestEN[39665] = { title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blocade and expand our control of the Draenor seas.", objectives = "" }
WordHunterWoW_QuestEN[39666] = { title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Salty Jorren down at the docks, he should be able to help us out.", objectives = "" }
WordHunterWoW_QuestEN[39667] = { title = "Where's Lyndras: Leyflame Larceny", description = "The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either.\n\nPerhaps one of the guards knows what became of Lyndras.", objectives = "" }
WordHunterWoW_QuestEN[39668] = { title = "What Horrible Presents!", description = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable.\n\nTake this spirit bomb. Toss it on some of Grumpus's unusual gifts and take them out for good!\n\nWe're in this together, {name}. Now go and save the spirit of the holiday!", objectives = "" }
WordHunterWoW_QuestEN[39670] = { title = "Critter Scatter Shot", description = "The howlers in these hills travel in packs. Three against one isn't a fight I want to pick.\n\nLuckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo...\n\nSnatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.", objectives = "" }
WordHunterWoW_QuestEN[39674] = { title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", objectives = "" }
WordHunterWoW_QuestEN[39675] = { title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Kronk Rustspark down at the docks, he should be able to help us out.", objectives = "" }
WordHunterWoW_QuestEN[39676] = { title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blockade and expand our control of the Draenor seas.", objectives = "" }
WordHunterWoW_QuestEN[39680] = { title = "Between the Hammer...", description = "{name}, I fear that my spirit will remain bound to this place unless I am made whole again.\n\nLong ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled.\n\nI need that hammer back if I am to be at peace.", objectives = "" }
WordHunterWoW_QuestEN[39681] = { title = "The Properties of Leystone", description = "I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium.\n\nLet's try making something with it. How about a nice pair of gauntlets?", objectives = "" }
WordHunterWoW_QuestEN[39682] = { title = "Grand Theft Felbat", description = "You heard what Maiev said. We need to get out of here.\n\nThere is an elevator shaft at the far end of these caverns. Let us make our way there.", objectives = "" }
WordHunterWoW_QuestEN[39683] = { title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39684] = { title = "Beam Me Up", description = "To the east is an intricate prison chamber designed to contain the beholder, Glazer.\n\nIt began malfunctioning shortly after the breach.\n\nYou will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer's impenetrable shield.\n\nHurry. Altruis went ahead to assist the others, but we are losing the fight.", objectives = "" }
WordHunterWoW_QuestEN[39685] = { title = "Frozen in Time", description = "The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient.\n\nMany of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field.\n\nGo join up with Kayn. Do whatever it takes to seal that chamber!", objectives = "" }
WordHunterWoW_QuestEN[39686] = { title = "All The Way Up", description = "Kor'vas went ahead to meet up with Kayn and Altruis.\n\nStep onto the elevator when it arrives, and meet them in the Hall of Judgment above.", objectives = "" }
WordHunterWoW_QuestEN[39688] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "" }
WordHunterWoW_QuestEN[39689] = { title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[39690] = { title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[39691] = { title = "The Call of War", description = "Today, sorrow grips Stormwind, bastion of the Light. \n\nKing Varian Wrynn has fallen in battle, leaving the crown to his son Anduin.\n\nThe leaders of the Alliance have gathered to pay their respects. No doubt they will have need of your unique skills.\n\nYou will find the king upon the throne of Stormwind Keep, attended by one of your fellow Illidari. I am needed in Dalaran.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39692] = { title = "The Call of War", description = "The Warchief Vol'jin is expecting you.\n\nEnter Grommash Hold straight ahead, and make your introduction.", objectives = "" }
WordHunterWoW_QuestEN[39694] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "" }
WordHunterWoW_QuestEN[39696] = { title = "Rise, Champions", description = "", objectives = "" }
WordHunterWoW_QuestEN[39697] = { title = "Master vs. Commander", description = "I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling?\n\nGul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic.\n\nScramble the fleet, {name}! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!", objectives = "" }
WordHunterWoW_QuestEN[39698] = { title = "Making the Rounds", description = "As you can see, we have spared no expense in showing our support of your great quest.\n\nFinal preparations are being made - come, walk with me.", objectives = "" }
WordHunterWoW_QuestEN[39699] = { title = "Ironhorn Leysmithing", description = "I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares.\n\nThere is also a technique in how you hammer such quantities of leystone that I will instruct you on.\n\nUse our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[39702] = { title = "Legend of Black Rook Hold", description = "{name}, have you heard of Saris Swifthammer?\n\nHe was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists.\n\nI want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.", objectives = "" }
WordHunterWoW_QuestEN[39716] = { title = "Smashing Squashlings", description = "The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor.\n\nNow, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.", objectives = "" }
WordHunterWoW_QuestEN[39718] = { title = "Paradise Lost", description = "Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus' Landing in Dalaran immediately.", objectives = "" }
WordHunterWoW_QuestEN[39719] = { title = "Mutiny on the Boneship", description = "Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet.\n\nThe Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor.\n\nSeek out Bonerender and defeat him, before he sails back into the mist once again.", objectives = "" }
WordHunterWoW_QuestEN[39720] = { title = "Foul Fertilizer", description = "The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked.\n\nThe stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.", objectives = "" }
WordHunterWoW_QuestEN[39721] = { title = "Culling the Crew", description = "If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew.\n\nSee to a swift reduction in their numbers, and we might just push them back into the sea for another year.", objectives = "" }
WordHunterWoW_QuestEN[39726] = { title = "...And the Anvil", description = "If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made.\n\nThe breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility\n\nRelinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.", objectives = "" }
WordHunterWoW_QuestEN[39729] = { title = "The Knowledge of Black Rook", description = "You have honored me with your help and now I wish to return those favors to you. On that pedestal there is all my research. Take it with you and learn from it so you may carry on my legacy.\n\nThank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39731] = { title = "The Tranquil Forest", description = "Archmage Khadgar sent word about Val'sharah not long ago. It sounds like he has good news.\n\nYou should meet him on Krasus' Landing in Dalaran as soon as you are able.", objectives = "" }
WordHunterWoW_QuestEN[39733] = { title = "The Lone Mountain", description = "Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don't know his intentions, but his people could be an invaluable contact in the region.\n\nKhadgar is greeting the emissary at Krasus' Landing in Dalaran - you should seek him out.", objectives = "" }
WordHunterWoW_QuestEN[39735] = { title = "Stormheim", description = "Sky Admiral Rogers has sent word for you to meet her in Dalaran.\n\nShe should be waiting for you in the Violet Citadel. It sounded important.", objectives = "" }
WordHunterWoW_QuestEN[39741] = { title = "Into Our Ranks", description = "I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider.\n\nKor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.\n\nIt is time to officially raise them up as champions.", objectives = "" }
WordHunterWoW_QuestEN[39746] = { title = "A Ring Unbroken", description = "Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters.\n\nThe elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. {name}, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever.\n\nJoin me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[39756] = { title = "A Sound Plan", description = "The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back.\n\nLet's prove them wrong.\n\nWe've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nOnce you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast.\n\nWe will end this madness for good. Light help us all.", objectives = "" }
WordHunterWoW_QuestEN[39763] = { title = "For Whom the Fel Tolls", description = "<Matthew eyes you up and down, growling slightly>\n\nYou wish me to help you understand this rock? First you do something for me.\n\nThe legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution.\n\nBring me some cores and I'll give you the information you need.", objectives = "" }
WordHunterWoW_QuestEN[39764] = { title = "Shiny, But Deadly", description = "Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds.\n\nThose mindless vermin made off with the soul chambers that house our demonic captives.\n\nThe crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape.\n\nHead into the cave nearby and recover the soul chambers before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[39765] = { title = "Wax On, Wax Off", description = "I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head!\n\nHe's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself.\n\nKill one of their Skullcaptains and recover his Skull of Bossing Around, and they may let you into the cave.", objectives = "" }
WordHunterWoW_QuestEN[39768] = { title = "Candle to the Grave", description = "These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on.\n\nI can do nothing to stop them! Please rid this sacred burial ground of the kobold.", objectives = "" }
WordHunterWoW_QuestEN[39769] = { title = "The Gates of Wax", description = "Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.", objectives = "" }
WordHunterWoW_QuestEN[39770] = { title = "Burn the Candle at Both Ends [NOT USED]", description = "You no come in yet! You need yellow candle and green candle before let in to Candleking!", objectives = "" }
WordHunterWoW_QuestEN[39771] = { title = "The Voice of Thunder", description = "The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm.\n\nNow you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans.\n\nCome! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!", objectives = "" }
WordHunterWoW_QuestEN[39772] = { title = "Can't Hold a Candle To You", description = "Okay guess you can go say hi to Candleking now.", objectives = "" }
WordHunterWoW_QuestEN[39773] = { title = "The Soulkeeper's Fate", description = "Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst.\n\nPlease find Uriah. He is the only one who knows how to trap the demons.", objectives = "" }
WordHunterWoW_QuestEN[39774] = { title = "Demon Detainment", description = "The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail.\n\nI've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.", objectives = "" }
WordHunterWoW_QuestEN[39775] = { title = "Stormforged Grapple Launcher", description = "", objectives = "" }
WordHunterWoW_QuestEN[39776] = { title = "Battle Worms", description = "Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation.\n\nThe drogbar are using worms to burrow their way to the surface and deploy their troops.\n\nI am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[39777] = { title = "Buy Us Time", description = "We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers?\n\nI will direct my healers to get everyone that is unable to fight to safety.", objectives = "" }
WordHunterWoW_QuestEN[39780] = { title = "The Underking", description = "Mayla already chased the Underking into his cave. That is something we tell our children never to do.\n\nReckless child, but hey, who wants to live forever? Let us join her in battle.", objectives = "" }
WordHunterWoW_QuestEN[39781] = { title = "Neltharion's Lair: Death to the Underking", description = "I will direct my people to clear a path through this rubble and assault Dargrul's forces directly.\n\nIt will be a ruse.\n\nNavarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul.\n\nMuster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us.\n\nWe will provide the distraction you need to get a shot.", objectives = "" }
WordHunterWoW_QuestEN[39786] = { title = "A Stone Cold Gamble", description = "The second target is a basilisk called Stonefang that lives off the bank of the nearby river. \n\nI put a bigger wager on him, so if you can take him out I'll make sure you get a cut.\n\nI'll need his jaw to verify the kill. Hurry, before those tauren get him first!", objectives = "" }
WordHunterWoW_QuestEN[39787] = { title = "Rigging the Wager", description = "Care to help settle a bet, chum?\n\nThose tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim.\n\nIf you take em out before they do, I'll split the wager. Deal?\n\nThe first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...", objectives = "" }
WordHunterWoW_QuestEN[39788] = { title = "The Runewood's Revenge", description = "The Bonespeakers...they are corrupt... hungry for power.\n\nCut them from my woods...", objectives = "" }
WordHunterWoW_QuestEN[39789] = { title = "Eating Into Our Business", description = "Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you.\n\nAs you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels.\n\nI can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.", objectives = "" }
WordHunterWoW_QuestEN[39790] = { title = "Infernal Brimstone Theory", description = "I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes.\n\nBut the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown.\n\nIf we're wantin' to test this out, we'll have to get the help of some magic-users.\n\nTake this brimstone back and go see Matthew Rabis. He may know how to breathe life into it.", objectives = "" }
WordHunterWoW_QuestEN[39791] = { title = "Lay Them to Rest", description = "I would ask a favor, outsider.\n\nAs you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well.\n\nTake this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.", objectives = "" }
WordHunterWoW_QuestEN[39792] = { title = "A Stack of Racks", description = "So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more.\n\nI hear that musken ribs are the specialty here.  The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out!\n\nDon't worry, I'm pretty sure there aren't any dragons over there...", objectives = "" }
WordHunterWoW_QuestEN[39793] = { title = "Only the Finest", description = "Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back!\n\nI hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there.\n\nWhy don't you go and fetch some? I'm sure them tauren would pay you handsomely!", objectives = "" }
WordHunterWoW_QuestEN[39796] = { title = "To Haustvald", description = "Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate!\n\nIt is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.", objectives = "" }
WordHunterWoW_QuestEN[39799] = { title = "Our Next Move", description = "Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion!\n\nUnder cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles.\n\nChoose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.", objectives = "" }
WordHunterWoW_QuestEN[39800] = { title = "Greymane's Gambit", description = "The Skyfire is prepared to make way to Stormheim. Should we become engaged, I will require my best fighters on the front line.\n\nThis includes you, {class}.", objectives = "" }
WordHunterWoW_QuestEN[39801] = { title = "The Splintered Fleet", description = "Preparations have been made, and we are ready to set sail.\n\nWe must strike out at once. Do not dally, or you will be left behind.", objectives = "" }
WordHunterWoW_QuestEN[39803] = { title = "The Trials Continue", description = "<Havi's voice continues in your head as the raven stares on>\n\nIf valor you seek, then to the bones you must speak! \n\nBut first you must prepare!", objectives = "" }
WordHunterWoW_QuestEN[39804] = { title = "Speaking of Bones", description = "The Trial of Valor will be your next test, and test you it will!\n\nBut only a fool fights on an empty stomach. Are you a fool, outsider?\n\nNo? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.", objectives = "" }
WordHunterWoW_QuestEN[39808] = { title = "Sepulcher of the Sky Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39809] = { title = "Path of Huln Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39810] = { title = "Whitewater Wash Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39811] = { title = "Whitewater Wash Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39813] = { title = "Earthmother's Bounty Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39814] = { title = "Lifespring Cavern Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39815] = { title = "Sylvan Falls Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39816] = { title = "Champion: Thassarian", description = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.\n\n<Mograine turns and nods to a nearby guard.>\n\nHe should be here momentarily.", objectives = "" }
WordHunterWoW_QuestEN[39817] = { title = "The Brimstone's Secret", description = "While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this.\n\nUnless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible.\n\nThat's all I have to tell you. Go now and leave me before my hunger takes over.", objectives = "" }
WordHunterWoW_QuestEN[39818] = { title = "Champion: Nazgrim", description = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.\n\n<Mograine turns and nods to a nearby guard.>\n\nHe should be here momentarily.", objectives = "" }
WordHunterWoW_QuestEN[39819] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39820] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39821] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39822] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39823] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39825] = { title = "Stonedark Grotto Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39826] = { title = "Witchwood Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39827] = { title = "Haglands Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39830] = { title = "Hellfire Citadel: Hellfire and Brimstone", description = "When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself.\n\nPerhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.", objectives = "" }
WordHunterWoW_QuestEN[39832] = { title = "Plans and Preparations", description = "Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential.\n\nSiouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.", objectives = "" }
WordHunterWoW_QuestEN[39833] = { title = "The Ruins of Azsuna", description = "{class}t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity.\n\nThe Kirin Tor have also constructed a permanent waygate to enable speedy redeployment of our Knights between here and Dalaran - you can find it on the balcony should you wish to use it.", objectives = "" }
WordHunterWoW_QuestEN[39837] = { title = "An Unworthy Task", description = "This place is Helheim, the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it.\n\nWe should not be here.\n\nWe must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.", objectives = "" }
WordHunterWoW_QuestEN[39847] = { title = "Sign This", description = "Ah, a fellow scribe!\n\nYou don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles?\n\n(That's the big mass of islands we're floating over.)\n\nHowever! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.", objectives = "" }
WordHunterWoW_QuestEN[39848] = { title = "A Desperate Bargain", description = "It looks like your friend didn't make it. A pity, but we must move on.\n\nYou'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case.\n\nMeet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.", objectives = "" }
WordHunterWoW_QuestEN[39849] = { title = "To Light the Way", description = "Helya must think her challenge unwinnable. We will show her different.\n\nI am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions.\n\nI may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit.\n\nThere is a kvaldir ship nearby. See if you can find one there.", objectives = "" }
WordHunterWoW_QuestEN[39850] = { title = "Sundered", description = "I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit.\n\nHelya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free.\n\nBe careful, though. It is unlikely that Helya left your spirit fragments unguarded.", objectives = "" }
WordHunterWoW_QuestEN[39851] = { title = "Allies in Death", description = "Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us.\n\nEarlier, I had discovered several of them being tortured by the elemental forces of Helheim. You may think the dead can't drown, but with Helya's power, this is not the case. \n\nI could not release them then, but now that you possess the waylight, you may be able to.\n\nSeek them out and free them from an eternity of suffering!", objectives = "" }
WordHunterWoW_QuestEN[39853] = { title = "Victory is Eternal", description = "There is no more cause for hesitation. Now is the time to strike.\n\nWe will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. \n\nPrepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[39855] = { title = "Paid in Lifeblood", description = "We have fulfilled Helya's bargain. Now, we see if she will keep to her word.\n\nWhen you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now.\n\nI will follow your lead, outsider.", objectives = "" }
WordHunterWoW_QuestEN[39857] = { title = "The Eternal Nemesis", description = "<Helya's voice echoes in the sky above the altar>\n\nYou say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? \n\nI cannot, so you must show me.\n\nBring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.", objectives = "" }
WordHunterWoW_QuestEN[39859] = { title = "Note-Eating Goats", description = "I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales.\n\nBut my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle!\n\nHemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft!\n\nI have no hope of becoming a hunter if my manuscript isn't recovered.", objectives = "" }
WordHunterWoW_QuestEN[39860] = { title = "Rite of Blood", description = "Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof.\n\nBefore we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me.\n\nEnter the depths of the cave. Defeat whatever foe appears and return to me.", objectives = "" }
WordHunterWoW_QuestEN[39861] = { title = "Tying Up Loose Ends", description = "Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around!\n\nHe's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.", objectives = "" }
WordHunterWoW_QuestEN[39862] = { title = "The Siegebrul", description = "Worms do not like battle or the surface. They only go where their master tells them.\n\nSo, when in war, kill the master.\n\nSiegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north.\n\nSlay him.", objectives = "" }
WordHunterWoW_QuestEN[39864] = { title = "Stormheim", description = "Nathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran.\n\nHe should be waiting for you in the Violet Citadel. It sounded urgent.", objectives = "" }
WordHunterWoW_QuestEN[39867] = { title = "I'm Not Lion!", description = "I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin.\n\nThe beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break.\n\nI've told Hemet of this magical beast, but he laughs. I'm not lying, {name}! The lion exists.\n\nIf you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[39873] = { title = "I Have a Bad Feeling About This", description = "You have no reason to trust me. My cousins led by Dargrul have gone mad with power.\n\nBut I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain, and that Torok and his Bloodtotem are going to be responsible.\n\nIf you don't believe me, look for yourself at the northern side of Cliff's Edge.", objectives = "" }
WordHunterWoW_QuestEN[39874] = { title = "Some Enchanted Evening", description = "Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. \n\nArchmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly.\n\nYour arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?", objectives = "" }
WordHunterWoW_QuestEN[39875] = { title = "The Last Few", description = "As you can see, {name}, we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders.\n\nIf you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.", objectives = "" }
WordHunterWoW_QuestEN[39876] = { title = "Helping the Hunters", description = "Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna.\n\nHe and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible.\n\nThanks, {name}!", objectives = "" }
WordHunterWoW_QuestEN[39877] = { title = "In the Loop", description = "We could use your help down here, {name}. Some of our hunters would benefit greatly from having those vellums applied to their rings right now.\n\nHere take a few. I'll give the rest to one of my other soldiers to hand out.\n\nMy hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.", objectives = "" }
WordHunterWoW_QuestEN[39878] = { title = "Thunder Struck", description = "I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power.\n\nSeek out an enchanter named Twaintail and see if he will share his knowledge with us.\n\nTaurens are known for their sharing... right?", objectives = "" }
WordHunterWoW_QuestEN[39879] = { title = "Strong Like the Earth", description = "There are many types of spirits in this world, {name}. Some benevolent, some troubled.\n\nThey all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards.\n\nThey are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.", objectives = "" }
WordHunterWoW_QuestEN[39880] = { title = "Waste Not", description = "While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste.\n\nI'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued.\n\nBring me back the reagents so my tribe may use them to enchant new armor.", objectives = "" }
WordHunterWoW_QuestEN[39881] = { title = "Fey Enchantments", description = "The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor.\n\nI'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces.\n\nHer name is Nalamya. You'll find her near the Temple of Elune.", objectives = "" }
WordHunterWoW_QuestEN[39882] = { title = "Darkheart Thicket: The Glamour Has Faded", description = "I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor.\n\nArch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight.\n\nBefore his betrayal, I gave him my book of enchantments to study. I would very much like it back.\n\nI trust you with this task, enchanter. Bring my book back to me.", objectives = "" }
WordHunterWoW_QuestEN[39883] = { title = "Cloaked in Tradition", description = "You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles.\n\nHere, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you.\n\nPerhaps it will serve to help the greater cause of defeating the Legion.", objectives = "" }
WordHunterWoW_QuestEN[39884] = { title = "No Longer Worthy", description = "The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter.\n\nSuch behavior is intolerable... especially after all the help they've received from my folk and the others of this land.\n\nI want you to do me a favor, {name}. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.", objectives = "" }
WordHunterWoW_QuestEN[39885] = { title = "Demon Hunt: Wingterror Ikzil", description = "We only caught a glimpse of him - the eredar known as Wingterror Ikzil prowls the skies above Val'Sharah.\n\nThe fiend is meeting a small cadre of harpies in a cave on the eastern edge of the Nightmare in Andu'talah not long from now - if you hurry you may be able to ambush him.", objectives = "" }
WordHunterWoW_QuestEN[39886] = { title = "Echoes of the Past", description = "Long ago, the titans created shrines linked to their greatest champions throughout the Broken Isles; legend has it that only those blessed by the Light can activate the immense power within them.\n\nThe device we found may be able to help us locate these shrines, {class}t - you should seek it out before it falls into the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[39887] = { title = "Call of the Priestess", description = "Priestess Taria has guarded an ancient hidden moon well in the depths of Val'Sharah for centuries, but now the forces of nightmare threaten to corrupt its sacred waters.\n\nHighlord, you should seek her out and help her protect the well. The Nightmare already threatens to overtake the forest; we cannot afford to lose another battle against it.", objectives = "" }
WordHunterWoW_QuestEN[39889] = { title = "Led Astray", description = "The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders.\n\nI know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home.\n\nGo to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow. Let them be an example for those who can help, but wish to remain cowardly.", objectives = "" }
WordHunterWoW_QuestEN[39890] = { title = "Lost Altar of the Lightbringer", description = "We aren't certain, but we believe we've found a long-lost altar to none other than Uther the Lightbringer, first champion of the Silver Hand!\n\nThat altar could hold untold power - you should seek it out and claim it as your own.", objectives = "" }
WordHunterWoW_QuestEN[39891] = { title = "Cursed, But Convenient", description = "I need you to return to Azsuna at once, {name}. I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments.\n\nGo to her and see what you can learn at once.", objectives = "" }
WordHunterWoW_QuestEN[39892] = { title = "Stemming the Tide", description = "Highlord, we've found a small village of friendly vrykul who may be willing to work alongside us in Stormheim!\n\nYou'll need to head to their village on the eastern coastline quickly, we encountered several Legion scouts on our way into the area - I suspect an attack is imminent.", objectives = "" }
WordHunterWoW_QuestEN[39895] = { title = "Demon Hunt: Emissary Azathar", description = "The doom guard Emissary Azathar has been meeting with the less-fortunate Highmountain tauren in secret, offering them dark power in exchange for their fealty to his masters.\n\nThe Highmountain are our only allies in the region, Highlord. Azathar must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[39900] = { title = "Lost Altar of the Lightbringer", description = "We aren't certain, but we believe we've found a long-lost altar to none other than Uther the Lightbringer, first champion of the Silver Hand!\n\nThat altar could hold untold power - you should seek it out and claim it as your own.", objectives = "" }
WordHunterWoW_QuestEN[39903] = { title = "An Enchanting Home", description = "The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders!\n\nIldine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day!\n\nInvestigating the home might uncover valuable knowledge, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39904] = { title = "Halls of Valor: Revenge of the Enchantress", description = "For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left.\n\nIf you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.", objectives = "" }
WordHunterWoW_QuestEN[39905] = { title = "Ringing True", description = "While your presence here would continue to be of value to us, your master in Dalaran has called for you.\n\nI'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.", objectives = "" }
WordHunterWoW_QuestEN[39906] = { title = "Prepping For Battle", description = "To earn my mark, {class}, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him.\n\nBefore we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire.\n\nMake some for me so that I may become strong enough again to make a difference in this world.", objectives = "" }
WordHunterWoW_QuestEN[39907] = { title = "Elven Enchantments", description = "You have earned the marks of my most trusted companions. You have also returned my love to me.\n\nI am fortunate to have met you, {name}.\n\nNow return to your master and let him know of what you have learned.", objectives = "" }
WordHunterWoW_QuestEN[39910] = { title = "The Druid's Debt", description = "In order to grant you my mark, {class}, I must first be made strong enough to come to your aid should you need it.\n\nWithin the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself.\n\nBut you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home.\n\nFind my idols and return them to me. Do this and I will grant you my mark.", objectives = "" }
WordHunterWoW_QuestEN[39914] = { title = "Sentinel's Final Duty", description = "Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill.\n\nHis name is Fathom-Commander Eksis. He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows.\n\nI've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.", objectives = "" }
WordHunterWoW_QuestEN[39916] = { title = "Turnabout Betrayal", description = "Enchantress Ilanya remembers me?\n\n<The satyr pauses to wipe a tear away.>\n\nI made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals.\n\nNow the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.", objectives = "" }
WordHunterWoW_QuestEN[39918] = { title = "The Absent Priestess", description = "After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, {name}, I can at last return.\n\nGo and speak to Enchantress Ilanya. I will let her know that you are worthy of my mark.", objectives = "" }
WordHunterWoW_QuestEN[39919] = { title = "Imminent Loss", description = "The peaceful Wheathoof tribe are in great danger. Highlord. A Legion assault force is en route to their position - we don't have long before the entire village is lost.\n\nI suggest you embark for their lands immediately while they still have a chance.", objectives = "" }
WordHunterWoW_QuestEN[39920] = { title = "On Azure Wings", description = "I have some exciting news of my own to report, {name}. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose.\n\nOne of the dragons, Kharmeera, is an enchanter who expressed interest in working with you to perfect some of our enchantments.\n\nI understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.", objectives = "" }
WordHunterWoW_QuestEN[39921] = { title = "Neltharion's Lair: Rod of Azure", description = "Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together.\n\nWhen I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod.\n\nInstead of retrieving it I believe it would be much simpler to reconstruct it.\n\nHere's what we'll need...", objectives = "" }
WordHunterWoW_QuestEN[39923] = { title = "Down to the Core", description = "The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings.\n\nAccording to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City.\n\nIf you were to gather some friends and defeat these constructs, you could take their cores for us to study.", objectives = "" }
WordHunterWoW_QuestEN[39931] = { title = "Smashing Herbs", description = "Now that the formalities are out of the way, let's have you do something actually useful.\n\nOn the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with.\n\nI'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.", objectives = "" }
WordHunterWoW_QuestEN[39932] = { title = "Fish Ink", description = "You know, herbs aren't the only ways to obtain ink. Other materials can be inkified.\n\nSlightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I.\n\nTo do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.", objectives = "" }
WordHunterWoW_QuestEN[39933] = { title = "The Card Shark", description = "We have the pigment, but we still require one more ingredient.\n\nVisitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.", objectives = "" }
WordHunterWoW_QuestEN[39934] = { title = "Our New Allies", description = "Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them.\n\nEverybody needs glyphs, you know.\n\nGo see what you can discover about them. Azsuna is as good a place as any to start.\n\nPerhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", objectives = "" }
WordHunterWoW_QuestEN[39935] = { title = "The Price of Power", description = "You wish to learn what it is to be a demon hunter? That may take some time.\n\nThe first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them.\n\nReturn to me when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[39936] = { title = "Inscription of the Body", description = "We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.", objectives = "" }
WordHunterWoW_QuestEN[39937] = { title = "Opposites Repel", description = "There's a balance that must be struck, {name}, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature.\n\nFel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check.\n\nYou are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.", objectives = "" }
WordHunterWoW_QuestEN[39938] = { title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", objectives = "" }
WordHunterWoW_QuestEN[39939] = { title = "Scribal Knowledge", description = "We do not simply fight the demons, {name}. We observe them.\n\nOne of my best demon hunters, Zaria Shadowheart, is currently gathering intel on the demons in Felblaze Ingress.\n\nGo to her. She will teach you what she has learned from the demons invading that region.", objectives = "" }
WordHunterWoW_QuestEN[39940] = { title = "Runes of Power", description = "Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again.\n\nStudy these runes.", objectives = "" }
WordHunterWoW_QuestEN[39941] = { title = "Control is Key", description = "We demon hunters ritualistically remove our eyes in order to see the demons more clearly.\n\nDown below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check.\n\nDestroy his warding crystal, then slay him.", objectives = "" }
WordHunterWoW_QuestEN[39942] = { title = "Aethrem Crystal", description = "<Most aethril has a sharp crystalline fiber in the center of the bloom, but this one is particularly well-developed.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[39943] = { title = "The Burdens of Hunting", description = "There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[39944] = { title = "Mysterious Messages", description = "The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here.\n\nHis name is Nicholo Swiftfuse, and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated.\n\nThat is all.", objectives = "" }
WordHunterWoW_QuestEN[39945] = { title = "Runes Within the Ruins", description = "Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned.\n\nLooks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.", objectives = "" }
WordHunterWoW_QuestEN[39946] = { title = "Right Tool for the Job", description = "From what little I have been able to decipher, I know that the tablets are created using a special carving tool.\n\nIf we had one of those tools, along with a complete codex, we could easily create our own tablet.\n\nThat would also serve to prove that my deciphering of their language has been successful.\n\nRetrieve one of those tools for me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[39947] = { title = "Not So Complex?", description = "Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife.\n\nAll that's left is to make our own tablet and verify my other suspicion about these tablets:\n\nI believe that they're not just simple texts, but a sort of magical device.", objectives = "" }
WordHunterWoW_QuestEN[39948] = { title = "The Ink Flows", description = "{name}, I need you to make a quick delivery for me.\n\nYes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours.\n\nDeliver these contracts to Raethan, the Guard Captain in Dalaran's Underbelly.", objectives = "" }
WordHunterWoW_QuestEN[39949] = { title = "Once a Scribe Like You", description = "These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract.\n\nHis name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad.\n\n<Raethan hands you the contract.>\n\nThis says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.", objectives = "" }
WordHunterWoW_QuestEN[39950] = { title = "An Odd Trinket", description = "Wait, {name}, before you leave... did you not notice this?\n\n<Raethan peels a small piece of paper from the bottom of the jewel.>\n\nThis wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing.\n\nPerhaps it may be of some use to you.", objectives = "" }
WordHunterWoW_QuestEN[39951] = { title = "Roseate Essence", description = "<The pigment milled from this flower is of an exceptionally high quality.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[39952] = { title = "Sallow Essence", description = "<The felwort is reduced to a thick, clotted pigment. While all felwort-begotten pigment is somewhat offensive, this batch practically glows with a malevolent energy.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[39953] = { title = "Halls of Valor: Vision of Valor", description = "I think it's time for another field trip, {name}. To the Halls of Valor!\n\nThe Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.", objectives = "" }
WordHunterWoW_QuestEN[39954] = { title = "Mass Milling Techniques", description = "A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription?\n\nI suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm.\n\nI have a book about mass milling somewhere around the shop here. Find it, and it's yours.", objectives = "" }
WordHunterWoW_QuestEN[39955] = { title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge.\n\nStop reading, student. You are dismissed. And give me my book back!", objectives = "" }
WordHunterWoW_QuestEN[39956] = { title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't get into the voice o' the characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe ye'll have an easier time with it.", objectives = "" }
WordHunterWoW_QuestEN[39957] = { title = "Demon Ink", description = "These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them.\n\nFortunately, I have students like you that excel at fetching hard-to-get items.\n\nFor this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.", objectives = "" }
WordHunterWoW_QuestEN[39958] = { title = "Skin Deep", description = "Welcome, {name}. It's an honor to be working with someone of your caliber.\n\nIn order for us to begin our work together, we'll first need to collect some materials.\n\nThe Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well.\n\nGo and collect some materials for us so we may begin working.", objectives = "" }
WordHunterWoW_QuestEN[39959] = { title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity.\n\nStop reading, student. You are dismissed. And give me my book back!", objectives = "" }
WordHunterWoW_QuestEN[39960] = { title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't find the voice of my characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe you'll have an easier time with it.", objectives = "" }
WordHunterWoW_QuestEN[39961] = { title = "An Embarrassing Revelation", description = "This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel. The pages are just FILLED with tawdry tales of carnality.\n\nCould it have something to do with inscription? Either way, Professor Pallin should be confronted.", objectives = "" }
WordHunterWoW_QuestEN[39962] = { title = "Trouble for Okuna", description = "<You open the bottle and find a message inside.>\n\nHelp! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard.\n\nI was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!", objectives = "" }
WordHunterWoW_QuestEN[39964] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39965] = { title = "Sylvan Falls Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39966] = { title = "Riverbend Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39967] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39968] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39983] = { title = "Huln's War - The Arrival", description = "Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes.\n\nLive his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.", objectives = "" }
WordHunterWoW_QuestEN[39984] = { title = "Remnants of the Past", description = "<The journal entry appears hastily written.>\n\nI do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed.\n\nSome have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return.\n\nIn these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well.\n\nI do not know what will become of me. For now, I can only stay at my post and remain vigilant.", objectives = "" }
WordHunterWoW_QuestEN[39985] = { title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", objectives = "" }
WordHunterWoW_QuestEN[39986] = { title = "Magic Message", description = "For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was.\n\nThat barrier has come down.\n\nSince then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern.\n\nA spell, encrypted among the chaos.\n\nI have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!", objectives = "" }
WordHunterWoW_QuestEN[39987] = { title = "Trail of Echoes", description = "The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can.\n\nWe should be able to find her by tracking her magical echoes, the same way I found her distress call.\n\nI can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself.\n\nMy wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.", objectives = "" }
WordHunterWoW_QuestEN[39988] = { title = "Huln's War - Stormrage", description = "<Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>", objectives = "" }
WordHunterWoW_QuestEN[39990] = { title = "Huln's War - Reinforcements", description = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed.\n\nBut now, I ask for your help, Huln Highmountain. I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.", objectives = "" }
WordHunterWoW_QuestEN[39992] = { title = "Huln's War - The Nathrezim", description = "I am fully occupied here organizing my troops and planning for the battle to come.\n\nWhile I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain.", objectives = "" }
WordHunterWoW_QuestEN[39995] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39996] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39997] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39999] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40000] = { title = "A True Hunter", description = "I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! \n\nA true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility.\n\nSo tell me, {name}, do you have the skills of a true hunter? Better yet, prove it.\n\nTake down some of the Bonebeak Hawks that circle the nearby meadow.", objectives = "" }
WordHunterWoW_QuestEN[40001] = { title = "Knocking on Valor's Door", description = "The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness.\n\nYour dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir.\n\nFree your dragon friend, champion, and wash the Felskorn from the Gates of Valor!", objectives = "" }
WordHunterWoW_QuestEN[40002] = { title = "A Familiar Fate", description = "We had come to defend the Halls of Valor... I was taken from the sky...\n\nI cannot break free of my bindings. Find the jailer who made this cell...\n\nSet me free, friend...", objectives = "" }
WordHunterWoW_QuestEN[40003] = { title = "Stem the Tide", description = "Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. \n\nIf we wish to stem this tide, these portals must be destroyed. \n\nI will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!", objectives = "" }
WordHunterWoW_QuestEN[40004] = { title = "Break the Spine", description = "To lead his tainted forces,  the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders.\n\nThese demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. \n\nTake them down, and shatter the spine of Skovald's offensive!", objectives = "" }
WordHunterWoW_QuestEN[40005] = { title = "Stormheim's Salvation", description = "It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself!\n\nI cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat!\n\nFor Stormheim!", objectives = "" }
WordHunterWoW_QuestEN[40006] = { title = "Sylvan Falls Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40007] = { title = "Fields of An'she Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40008] = { title = "The Only Way Out is Through", description = "I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever.\n\n<Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.>\n\nIf we push through, we may find shelter up ahead.", objectives = "" }
WordHunterWoW_QuestEN[40009] = { title = "Arcane Thirst", description = "My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there.\n\n<Thalyssra holds her flask aloft, gently shaking free the last precious drops.>\n\nI'm afraid I have been rather reckless today. \n\nAlready, my senses are dulling. Without magic to feed upon, I will turn. \n\nPlease... find me something to feed upon... anything...", objectives = "" }
WordHunterWoW_QuestEN[40010] = { title = "Tapping the Leylines", description = "The arcways were built to tap into the magical leylines beneath Suramar. As we learned to subsist on the Nightwell, the old facilities fell out of use.\n\nThis chamber is clearly receiving power from elsewhere.\n\nThere is only a trickle now, but if you can direct more leyline energy here it will help to sustain us.\n\nThe closest source is to the north, near Anora Hollow.", objectives = "" }
WordHunterWoW_QuestEN[40011] = { title = "Oculeth's Workshop", description = "We need to make contact with Chief Telemancer Oculeth, the man who developed Suramar's teleportation network. \n\nOculeth had a workshop in old Suramar, from the age before the Sundering. He may be taking refuge there.\n\n<Thalyssra presses a small coin into your palm.>\n\nIf you find him, show him this. Hopefully you see him before he sees you...", objectives = "" }
WordHunterWoW_QuestEN[40012] = { title = "An Old Ally", description = "I was on my way to Ambervale in hopes of finding an old colleague.\n\nArcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them.\n\nWhen one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled.\n\nIf Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.", objectives = "" }
WordHunterWoW_QuestEN[40013] = { title = "Aethril Sample", description = "This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[40014] = { title = "Spayed by the Spade", description = "The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together.\n\nI suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts.\n\nStill, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.", objectives = "" }
WordHunterWoW_QuestEN[40015] = { title = "Ragged Strips of Silk", description = "Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered.\n\nThe feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?", objectives = "" }
WordHunterWoW_QuestEN[40016] = { title = "Desperation Breeds Ingenuity", description = "I believe we may be able to use this clue to our advantage, {name}.\n\nThe withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.", objectives = "" }
WordHunterWoW_QuestEN[40017] = { title = "A Slip of the Hand", description = "As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction.\n\nYou may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.", objectives = "" }
WordHunterWoW_QuestEN[40018] = { title = "Dreamleaf Sample", description = "The herb is brilliantly green, paper-thin, and somewhat sticky.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[40019] = { title = "An Empathetic Herb", description = "Something is different about this dreamleaf, though. It is less than pure.\n\nI have a theory.\n\nThe wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight.\n\nI need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.", objectives = "" }
WordHunterWoW_QuestEN[40020] = { title = "Twisted to Death", description = "The corruption has completely taken this herb.\n\nThis blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.", objectives = "" }
WordHunterWoW_QuestEN[40021] = { title = "One Dead Plant is One Too Many", description = "We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR!\n\nSatyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!", objectives = "" }
WordHunterWoW_QuestEN[40022] = { title = "Choked by Nightmare", description = "Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight.\n\nYou should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.", objectives = "" }
WordHunterWoW_QuestEN[40023] = { title = "The Last Straw", description = "We cannot falter in our crusade against this corruption, {name}.\n\nIt is our duty as heroes. As herbalists.\n\nAs hero-balists.\n\nSlaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran's summoning stone, and place this herb in front of it. Then... rip off his head.\n\nDo it for the plants.", objectives = "" }
WordHunterWoW_QuestEN[40024] = { title = "Foxflower Sample", description = "Something about this herb catches your eye... and your nose.\n\nYour herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.", objectives = "" }
WordHunterWoW_QuestEN[40025] = { title = "Teeny Bite Marks", description = "This herb has been chewed by some of the local wildlife.\n\nWhat kind of animal would eat foxflower? A bear?\n\nPerhaps your trainer in Dalaran will know.", objectives = "" }
WordHunterWoW_QuestEN[40026] = { title = "Chase the Culprit", description = "This is a powerful herb, {name}. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency.\n\nI'm intrigued. What kind of animal would eat foxflower? A moose?\n\nYou should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.", objectives = "" }
WordHunterWoW_QuestEN[40028] = { title = "The Pied Picker", description = "As you finish gathering the foxflower, a particular part of the bloom catches your eye.\n\nOne of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from.\n\nYour herbalism trainer would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40029] = { title = "Fjarnskaggl Sample", description = "To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed.\n\nYour herbalism trainer in Dalaran will want to see some more samples of this.", objectives = "" }
WordHunterWoW_QuestEN[40030] = { title = "Ram's-Horn Trowel", description = "The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist.\n\nApparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past.\n\nPerhaps she might be interested in seeing the tools that the vrykul use to harvest it.", objectives = "" }
WordHunterWoW_QuestEN[40031] = { title = "Vrykul Herblore", description = "<Kuhuine studies the trowel further.>\n\nThis is a standard digging tool. There is not much to be learned here, except...\n\n...this DOES suggest that the vrykul are still actively gathering this herb.\n\nThe vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.", objectives = "" }
WordHunterWoW_QuestEN[40032] = { title = "The Missing Page", description = "<The page appears to be ripped out of a larger book. It reads:>\n\n\"...the Cairn of the Sea, a place long-known to be beloved by the gods.\n\nHe placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\"\n\nThis may be related to the books you brought back to your herbalism trainer.", objectives = "" }
WordHunterWoW_QuestEN[40033] = { title = "Fjarnskaggl", description = "There! It seems that there was a vrykul herbalist, Torgus, who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors.\n\n<Kuhuine shrugs.>\n\nIt's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.", objectives = "" }
WordHunterWoW_QuestEN[40034] = { title = "Starlight Rosedust", description = "Despite all your training, the rose disintegrated in your hand.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[40035] = { title = "The Gentlest Touch", description = "Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.", objectives = "" }
WordHunterWoW_QuestEN[40036] = { title = "Jeweled Spade Handle", description = "An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off.\n\nYour herbalism trainer may be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40037] = { title = "The Spade's Blade", description = "Did you notice the script along the base of the handle, {name}? It says \"Herbalist Tharillon,\" in the writing of the nightborne.\n\nThe handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often.\n\nI would start my search for it in Suramar.", objectives = "" }
WordHunterWoW_QuestEN[40038] = { title = "Insane Ramblings", description = "Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye:\n\n     \"thinks HE knows how to gather herbs\n {name}{name}\n{name}{name}    steal my blade\n  slit his THROAT when I\n\n        just need\n      a bit more mana\n    maybe aethril, yes...\"\n\nYour herbalism trainer may be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40039] = { title = "Tharillon's Fall", description = "He mentions your name... his blade... aethril...\n\nI'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere.\n\nTharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.", objectives = "" }
WordHunterWoW_QuestEN[40040] = { title = "Felwort Sample", description = "This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[40041] = { title = "Felwort Analysis", description = "I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses.\n\nRyno Bloomfield is currently working in Un'goro Crater.\n\nDani Earthtouch is researching Freya's influence in Sholazar Basin.\n\nFinally, Lohor has been working in the overgrown portion of Gorgrond.", objectives = "" }
WordHunterWoW_QuestEN[40042] = { title = "The Emerald Nightmare: Felwort Mastery", description = "I have a theory on how we can better harvest this felwort, {name}. You see, sometimes in order to understand how something comes into being, you have to work backwards.\n\nI've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now.\n\nIf you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.", objectives = "" }
WordHunterWoW_QuestEN[40043] = { title = "The Hunter of Heroes", description = "Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago.\n\nHe has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.", objectives = "" }
WordHunterWoW_QuestEN[40044] = { title = "Shadows in the Mists", description = "Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time.\n\nThe ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade.\n\nSo tell me, how kind is your soul?", objectives = "" }
WordHunterWoW_QuestEN[40045] = { title = "Nature vs. Nurture", description = "I appreciate murloc-kind far too much to tell you to go kill all the adults.\n\nWhat we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. \n\nBring him to talk to the murloc tadpoles. He'll get them on our side.", objectives = "" }
WordHunterWoW_QuestEN[40046] = { title = "Scavenging the Shallows", description = "The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions.\n\nThey bring them here to transport to Helya, though the mists obscure any indications of how.\n\nYou seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.", objectives = "" }
WordHunterWoW_QuestEN[40047] = { title = "I'll Huff, I'll Puff...", description = "Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities.\n\nThere are a lot of pufferfish around in the water, and I think that they could be a good resource for him. \n\nKill a few and collect their eggs for Murky.", objectives = "" }
WordHunterWoW_QuestEN[40048] = { title = "Strings of the Puppet Masters", description = "I understand you were just here to deliver the vellums, but we could use your skills as a {class}. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp.\n\nThe stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons.\n\nI would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[40049] = { title = "Slime Time", description = "Murky's a growing boy, he needs to eat! What better than slimeweed for a young murloc?\n\nThere's plenty of it around in the water amongst the murlocs; swim through it and feed Murky!", objectives = "" }
WordHunterWoW_QuestEN[40051] = { title = "Fel Secrets", description = "The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent.\n\nBut there's only enough to enact one of the rituals. After that, the book will be consumed.\n\nIt's up to you to choose which secrets we want to use against the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[40052] = { title = "Ancient Vrykul Mastered", description = "Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran.\n\n<Nicholo sighs.>\n\nLearn from my example, {name}. If I were you, I'd break free from Pallin's \"requests\" as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[40056] = { title = "Our New Allies", description = "Student! Your fellow demon hunters in Azsuna have sent for you.\n\nI can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies.\n\nWhile you're down there, I'd like you to come up with some new glyphs for your abilities.\n\nSurely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", objectives = "" }
WordHunterWoW_QuestEN[40057] = { title = "The Price of Power", description = "I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then.\n\nI need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.", objectives = "" }
WordHunterWoW_QuestEN[40058] = { title = "Defense Symbology", description = "As you know, {name}, we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.", objectives = "" }
WordHunterWoW_QuestEN[40059] = { title = "Opposites Repel", description = "The ruins nearby have had an eruption of ley energies. Twisted night elves deemed \"Nightfallen\" are scavenging the area as we speak.\n\nCollect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I'll need to complete my ritual.", objectives = "" }
WordHunterWoW_QuestEN[40060] = { title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", objectives = "" }
WordHunterWoW_QuestEN[40061] = { title = "To Know Your Enemy", description = "As we fight the demons, we've also been studying them.\n\nGreat understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there.\n\nGo to her and see what she has learned from the demons invading that region.", objectives = "" }
WordHunterWoW_QuestEN[40062] = { title = "Bulging Nightmare Pod", description = "<The flower has folded inward, to protect itself from the nightmare energy trapped within.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[40063] = { title = "Control is Key", description = "I trust you remember why you removed your eyes?\n\nEven though we can see more clearly now, the demons have found ways to mask even their fel energies from us.\n\nA demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal.\n\nFind and destroy that crystal, then kill the commander.", objectives = "" }
WordHunterWoW_QuestEN[40064] = { title = "Woody Seed Cluster", description = "<Attempting to mill this flower has proven more difficult than usual. Located in the bushy center of the bloom is a densely-packed cluster of seeds.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[40065] = { title = "Fjarnsk", description = "<A goopy substance seeps from the interior of the bloom. It's not ink... it is something else entirely.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[40069] = { title = "Fledgling Worm Guts", description = "The drogbar use these caves as a place to train fledgling worms.\n\nThe rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle.\n\nTheir guts are also known to be quite useful, and I have need of them. Two worms, one stone.", objectives = "" }
WordHunterWoW_QuestEN[40070] = { title = "Eagle Egg Recovery", description = "Eagles are revered by the Skyhorn tribe, but their numbers are dwindling.\n\nThe drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. \n\nIf the drogbar continue to pilfer these eggs, the eagles may become extinct.\n\nHead deeper into the cave and recover any eagle eggs you can find.", objectives = "" }
WordHunterWoW_QuestEN[40071] = { title = "Tamer Takedown", description = "The drogbar will continue to breed vicious worms as long as their tamer lives. \n\nKorgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle.\n\nHead deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.", objectives = "" }
WordHunterWoW_QuestEN[40072] = { title = "Halls of Valor: Securing the Aegis", description = "The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked.\n\nYou, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones!\n\nThe Halls of Valor await!", objectives = "" }
WordHunterWoW_QuestEN[40077] = { title = "The Invasion Begins", description = "Our advance force of demon hunters is here and has engaged the Legion.\n\nMake our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40078] = { title = "A Heavy Burden", description = "With Ashildir's judgment, your final trial is complete. \n\nBut even Valhallas can wait, for now we must eat! Being dead works up quite an appetite.\n\nCome now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.", objectives = "" }
WordHunterWoW_QuestEN[40102] = { title = "Murlocs: The Next Generation", description = "The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future.\n\nThere's a nice cave not too far away... only problem is that it's filled with makrura.\n\nThis would be a good base for the tadpoles. Murky must go show them what for!\n\nMindmeld with Murky in his egg and show him how it's done!", objectives = "" }
WordHunterWoW_QuestEN[40112] = { title = "Huln's War - Malorne's Favored", description = "[In broken Common] Shan'do ask for you. Sent Eche'ro beast with message on rack.\n\nUnng Ak hear Eche'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.", objectives = "" }
WordHunterWoW_QuestEN[40114] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40115] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40116] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40120] = { title = "A Murky Fate", description = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end.\n\nThe creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites.\n\nThis is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.", objectives = "" }
WordHunterWoW_QuestEN[40122] = { title = "Cenarius, Keeper of the Grove", description = "Ahh, Val'sharah.\n\nIt has been an age since I have set foot in these sacred woods. Too long...\n\nOur work here is simple, {class}. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion.\n\nYou have many treacherous tasks in front of you. Consider your visit here a brief respite.\n\nCome, this will not take long.", objectives = "" }
WordHunterWoW_QuestEN[40123] = { title = "The Nightborne Pact", description = "<Thalyssra winces and holds her abdomen.>\n\nNgh... I can ignore this wound no longer.\n\nHelp me patch this up. I will explain everything.", objectives = "" }
WordHunterWoW_QuestEN[40125] = { title = "Branch of the Arcan'dor", description = "You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. \n\n<Thalyssra holds aloft a gleaming white branch.>\n\nThis fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together.\n\nI have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.", objectives = "" }
WordHunterWoW_QuestEN[40130] = { title = "Washed Clean", description = "Mighty though the Legion is, theirs is not the strongest power in Azeroth.\n\nThere is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, {name}.\n\nGo to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well.\n\nI will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[40131] = { title = "Stonehide Leather Sample", description = "The quality of this leather scrap appears representative of the beast hides found in the Broken Isles.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40132] = { title = "In One Piece", description = "<Your trainer looks over the hide.>\n\nThis hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, {name}. You make light of the gift that it gave to you.\n\nGo out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.", objectives = "" }
WordHunterWoW_QuestEN[40133] = { title = "Scrap of Pants", description = "The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word \"singwa\".\n\nWhile the term \"singwa\" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.", objectives = "" }
WordHunterWoW_QuestEN[40134] = { title = "Highmountain Hides", description = "So, ye're a skinner too, aye?\n\nThat's great news, {name}! I don't think I ever knew we shared that in common.\n\nYe've GOT ta see some o'the hides we've got here in Highmountain. Why, I'd give me spare monacle just t'get me hands on some o'those fine, silky hides...", objectives = "" }
WordHunterWoW_QuestEN[40135] = { title = "The Freedom to Roam", description = "I remember bein' young, {name}. D'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I'm pretty much stuck with my hunting crew, here in Highmountain.\n\nThere're so many interestin' creatures in the other regions o'the Broken Isles, though. I'll mark yer map, you get out there and do some skinnin'!", objectives = "" }
WordHunterWoW_QuestEN[40136] = { title = "Immaculate Stonehide Leather", description = "You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored...\n\nYour trainer in Dalaran would be VERY interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40137] = { title = "Leather for Ske'rit", description = "This hide certifies that you have learned everything about leather that I can teach you, {name}. My skills have dulled since I set up shop here in town.\n\nI have a former protege who skins the creatures of Suramar. His name is Ske'rit. His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.", objectives = "" }
WordHunterWoW_QuestEN[40138] = { title = "Trial of the Crusader: Hides of Legend", description = "Ya, I can train you. Ting is, I'm still workin' on my techniques 'ere in Suramar. In fact, you can probably help.\n\nI need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find.\n\nDo that, and I'll share my results with you and' ol' Kondal up in de city.", objectives = "" }
WordHunterWoW_QuestEN[40139] = { title = "Halls of Valor: The Hide of Fenryr", description = "While you be here, I got a favor t'ask you.\n\nI been hearin' whispers about one big, nasty wolf dat's been causin' all kinds of trouble up in de vrykul lands. His name be Fenryr.\n\nI want his hide.", objectives = "" }
WordHunterWoW_QuestEN[40140] = { title = "Ske'rit's Leather Handbook", description = "An' wit dat, my research be done.\n\n<Ske'rit hands you a scroll casing.>\n\nDis is what I been workin' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs.\n\nSince you been helpin' so much, I put your name on it, {name}. Hope you don't mind.", objectives = "" }
WordHunterWoW_QuestEN[40141] = { title = "Stormscale Sample", description = "This scale shimmers with electrical energy.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40142] = { title = "The Core of the Stormscale", description = "Ahh, yes. The elusive stormscale.\n\nI have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this.\n\nTo more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.", objectives = "" }
WordHunterWoW_QuestEN[40143] = { title = "Unfinished Treatise on the Properties of Stormscale", description = "Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use.\n\nPerhaps your skinning trainer in Dalaran could help you find its owner.", objectives = "" }
WordHunterWoW_QuestEN[40144] = { title = "Glielle", description = "One skinner makes the wilds of Azsuna her home. Her name is Glielle, and she is a night elf - or at least, she was, in life.\n\nPerhaps the scroll was hers.", objectives = "" }
WordHunterWoW_QuestEN[40145] = { title = "Under Down", description = "I can train you, though.\n\nEveryone knows about the bright stormscales on the hippogryph's hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look.\n\n<The night elf spirit indicates a few places near the hippogryph's wing joints.>\n\nNow go see if you can get some on your own.", objectives = "" }
WordHunterWoW_QuestEN[40146] = { title = "Seymour and Agnes", description = "The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour, and his mother Agnes.\n\nLast I heard, they were in Stormheim, hunting the storm drakes.", objectives = "" }
WordHunterWoW_QuestEN[40147] = { title = "Mother's Prized Knife", description = "The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn't good enough.\n\nHer knife is still up there, somewhere. I'd feel horrible just leaving it.", objectives = "" }
WordHunterWoW_QuestEN[40148] = { title = "Red-Eyed Revenge", description = "It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I'd ever seen came and... and...\n\n<Seymour finds his resolve.>\n\nI want you to kill as many of them as you can. Skin them, don't skin them, I don't care. Just get revenge for mother!", objectives = "" }
WordHunterWoW_QuestEN[40149] = { title = "Drakol'nir Must Die", description = "The dragon that took Mother's life was named Drakol'nir.\n\nMother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn't kill him alone, and she didn't care much for killing. Only skinning.\n\nYou... you wouldn't mind bringing it for her, would you?", objectives = "" }
WordHunterWoW_QuestEN[40151] = { title = "Immaculate Stormscale", description = "You have been skinning for a long time now, but never have you seen a scale specimen as fine as this.\n\nYour trainer in Dalaran would be VERY interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40152] = { title = "Scales for Ske'rit", description = "Your skills surpass mine, {name}. I have never even SEEN a scale such as this... let alone remove one so expertly.\n\nIf you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske'rit, and he was once my student.\n\nYou will find him in the wild areas of Suramar.", objectives = "" }
WordHunterWoW_QuestEN[40153] = { title = "Return to Karazhan: Scales of Legend", description = "I know a ting or two about scales, but I'm losin' my edge. I been starin' at stormscales so long, I be forgettin' what de other kinds look like.\n\nI need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o' insect chitin you can find.\n\nGotta get dese stormscales outta my head, bruddah.", objectives = "" }
WordHunterWoW_QuestEN[40154] = { title = "Eye of Azshara: The Scales of Serpentrix", description = "I got ta ask you a favor.\n\nI haven't been ta Azsuna, and I don't see myself leavin' Suramar anytime soon. Problem is, dere's a big ol' serpent out dere dat's just beggin' ta be skinned. Just BEGGIN' for it.", objectives = "" }
WordHunterWoW_QuestEN[40155] = { title = "Ske'rit's Scale-Skinning Suggestions", description = "Now dat I got all dese scales, I tink I know what I need to know.\n\n<Ske'rit hands you a few pages of handwritten notes.>\n\nHere's my latest findin's on stormscales. Bring 'em to Kondal, an' read through em' togethah.", objectives = "" }
WordHunterWoW_QuestEN[40156] = { title = "Felhide Sample", description = "This demonic hide is completely unlike any standard beast hide you are accustomed to.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[40157] = { title = "An Unseemly Task", description = "I'm quite impressed with what you've been able to skin in these lands, felhide in particular.\n\nBut as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts.\n\nYou can find my old apprentice, Ske'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.", objectives = "" }
WordHunterWoW_QuestEN[40158] = { title = "Darkheart Thicket: Demons Be Different", description = "Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task.\n\nTheir hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more.\n\nThere be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke.\n\nBring me his skin to show me you be picking up on what I'm sayin'.", objectives = "" }
WordHunterWoW_QuestEN[40159] = { title = "The Emerald Nightmare: The Pestilential Hide of Nythendra", description = "There is one more demon hide to gather... but it isn't that of a demon. It's a dragon.\n\nNythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body.\n\nGo on then, {name}. Show me what you've learned.", objectives = "" }
WordHunterWoW_QuestEN[40160] = { title = "Magic Clams", description = "<The clam resonates with a arcane energy.>\n\nWhat are murlocs doing with arcane clams?\n\nPerhaps your Nightfallen allies could make use of them.", objectives = "" }
WordHunterWoW_QuestEN[40161] = { title = "Tapping the Underground", description = "Have you seen them, {name}?\n\nThese are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. \n\nSomehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes.\n\nThese disturbances must be stopped if the ley line is to remain intact.", objectives = "" }
WordHunterWoW_QuestEN[40162] = { title = "Snowblind Mesa Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40163] = { title = "Snowblind Mesa Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40166] = { title = "Leying with Murlocs", description = "I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river.\n\nI doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus.\n\nBlargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual.\n\nInfuse yourself with ley energies and return to me.", objectives = "" }
WordHunterWoW_QuestEN[40167] = { title = "The Story of Huln", description = "You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain.\n\nHuln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.", objectives = "" }
WordHunterWoW_QuestEN[40168] = { title = "The Swirling Vial", description = "As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?", objectives = "" }
WordHunterWoW_QuestEN[40169] = { title = "Crossroads Rendezvous", description = "An old apprentice of mine left during the war, shortly before we were all cursed.\n\nI've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more.\n\nGo and find her. Take her journal to her and let her know that I don't blame her for what she did.\n\nAnd if she's willing, please bring her back to me.", objectives = "" }
WordHunterWoW_QuestEN[40170] = { title = "Amateur Hour", description = "The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics.\n\nWhile I'm a known expert with my rifle, I've yet to manage the art of negotiation.\n\nHow about ya do us all a favor and tell those novice hunters to head for the hills?", objectives = "" }
WordHunterWoW_QuestEN[40173] = { title = "The Unstable Prism", description = "As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.", objectives = "" }
WordHunterWoW_QuestEN[40174] = { title = "Raising the River", description = "You are brimming with raw energy, my friend. Let me see if I can refine it just a little.\n\n<Saylanna draws the energy from you and channels it into an ornate rod.>\n\nThere. I have concentrated the ley energies into this rod. The burst of energy should easily disrupt Blargrrrl and cease the summoning of Torrentus.", objectives = "" }
WordHunterWoW_QuestEN[40176] = { title = "From Head to Toe", description = "You've been busy, {name}. And you have some new patterns in your repertoire, I see!\n\nHow about we add another?", objectives = "" }
WordHunterWoW_QuestEN[40177] = { title = "Leather Lady", description = "I'd like you to start working with my apprentices.\n\nThe first is Diane Cannings, who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are.\n\nGo talk to her about this new type of leather.", objectives = "" }
WordHunterWoW_QuestEN[40178] = { title = "Vestment Opportunity", description = "While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest.\n\nGo to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.", objectives = "" }
WordHunterWoW_QuestEN[40179] = { title = "Stormheim Savagery", description = "There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend.\n\nWhat I remember most was how well-crafted their armor was.\n\nIf the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.", objectives = "" }
WordHunterWoW_QuestEN[40180] = { title = "Mail Men", description = "The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts.\n\nWhile Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade.\n\nIntroduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.", objectives = "" }
WordHunterWoW_QuestEN[40181] = { title = "Black Rook Bandit", description = "I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay.\n\nI'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking.\n\nHow about ye head over there and see what ye can \"borrow\" from their armory.", objectives = "" }
WordHunterWoW_QuestEN[40182] = { title = "Too Good To Pass Up", description = "All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces.\n\nIf ye can, try to find someone of importance there and... relieve them of their shirt.\n\nIf it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.", objectives = "" }
WordHunterWoW_QuestEN[40183] = { title = "Over Your Head", description = "Alright, {name}, I'd like you to assist me with creating a helm.\n\nFirst we'll need to shave the hides, then tan them, and finally cut them into usable pieces.\n\nFollow my lead.", objectives = "" }
WordHunterWoW_QuestEN[40184] = { title = "Tauren Tanning", description = "Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor.\n\nI've heard they have a leatherworking master there who might be able to help us come up with some new patterns.\n\nTravel to Highmountain and see if they're willing to teach you how they craft their armor.", objectives = "" }
WordHunterWoW_QuestEN[40185] = { title = "Shoulder the Burden", description = "During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar.\n\nYou would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.", objectives = "" }
WordHunterWoW_QuestEN[40186] = { title = "Drogbar Durability", description = "We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves.\n\nSlay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.", objectives = "" }
WordHunterWoW_QuestEN[40187] = { title = "Links in the Chain", description = "Well, lad, I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set.\n\nHowever, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist.\n\nGo there and search fer a master. Maybe they can fill in the missing patterns fer us.", objectives = "" }
WordHunterWoW_QuestEN[40188] = { title = "Best Served Cold", description = "My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend.\n\nThat \"friend\" has recently appeared in the ruins to the east. His name is Ranaris.\n\nGo to and take revenge for us and I will grant you some of my wisdom.", objectives = "" }
WordHunterWoW_QuestEN[40189] = { title = "Naga Know-How", description = "The naga of this region wear little armor, but what they do wear is particularly durable.\n\nIf you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct.\n\nThe city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.", objectives = "" }
WordHunterWoW_QuestEN[40190] = { title = "Hardening the Hide", description = "Back to Highmountain for you, {name}! I hear they know even more efficient ways to craft our patterns.\n\nWhen you get there, put in a good word for me, will ya? I'd like to start a relationship the tauren, so I don't have to keep sending you back and forth.", objectives = "" }
WordHunterWoW_QuestEN[40191] = { title = "Stamped Stories", description = "Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers.\n\nThey tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking.\n\nRead the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.", objectives = "" }
WordHunterWoW_QuestEN[40192] = { title = "Claw of the Land", description = "Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them.\n\nFor example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.", objectives = "" }
WordHunterWoW_QuestEN[40193] = { title = "Getting the Kinks Out", description = "Now listen, lad. Everything ye make can always be done better. I just haven't quite worked out the way to do it with these fancy new scales.\n\nPerhaps that ghost-like elf friend of yours can help ye. An' if she DOES know somethin', perhaps ye can relay that information back to us.\n\nIt would certainly go towards making the shop more lucrative.", objectives = "" }
WordHunterWoW_QuestEN[40194] = { title = "Reclaimed Cargo", description = "The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves.\n\nIf you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.", objectives = "" }
WordHunterWoW_QuestEN[40195] = { title = "A Daring Rescue", description = "My brother, Taldranis, was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive.\n\nI believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please.\n\nTake this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.", objectives = "" }
WordHunterWoW_QuestEN[40196] = { title = "Adventuring Anxieties", description = "{name}! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted.\n\nI'd like you to go and discuss this idea with her further.\n\nReturn to me when you're finished. Perhaps we can solve this issue together.", objectives = "" }
WordHunterWoW_QuestEN[40197] = { title = "The Necessary Materials", description = "In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather.\n\nI'll solidify our plans on fitting the pieces together. You go gather the leather.\n\nOnce that's done, we can begin crafting.", objectives = "" }
WordHunterWoW_QuestEN[40198] = { title = "Rats!", description = "I tell you, {name}, I have the worst luck sometimes.\n\nA package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers!\n\nProbably building nests with them as we speak. Please, {name}, can you go down there and see if you can retrieve any of them?", objectives = "" }
WordHunterWoW_QuestEN[40199] = { title = "Leather Legwork", description = "Good news, {name}! Langrom's Leather and Links recently delivered a shipment of mail armor to me.\n\nIt's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate.\n\nIf ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.", objectives = "" }
WordHunterWoW_QuestEN[40200] = { title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", objectives = "" }
WordHunterWoW_QuestEN[40201] = { title = "Playthings", description = "Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?!\n\nIt sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready.\n\nWhy don't you work on making the bed, and I'll work out the details for the flaming hoop.", objectives = "" }
WordHunterWoW_QuestEN[40202] = { title = "The Final Lessons", description = "{name}, Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land.\n\nI envy you, {name}... but I'm also proud to see that you've gained so much respect with him.\n\nGo now, and good luck!", objectives = "" }
WordHunterWoW_QuestEN[40203] = { title = "Strength of the Past", description = "As you know, the durability of your armor is only as strong as the materials you use to make them.\n\nLong ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds.\n\nHis natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me.\n\nThis will take all your strength to accomplish.", objectives = "" }
WordHunterWoW_QuestEN[40204] = { title = "Evolution of the Past", description = "As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again.\n\nFor centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them.\n\nGo, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.", objectives = "" }
WordHunterWoW_QuestEN[40205] = { title = "Respect for the Past", description = "We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes.\n\nScattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell.\n\nGo to these locations, pay your respect, and learn their lessons.", objectives = "" }
WordHunterWoW_QuestEN[40206] = { title = "A Debt Paid", description = "Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now.\n\nCelea has sent fer ye, lad. I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.", objectives = "" }
WordHunterWoW_QuestEN[40207] = { title = "Scales of the Arcane", description = "In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way.\n\nI wish to work with it again, {name}. Being in this form, I'm bound to this area, unable to experience the world any longer.\n\nI've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.", objectives = "" }
WordHunterWoW_QuestEN[40208] = { title = "Eye of Azshara: Scales of the Sea", description = "When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords.\n\nOne in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend.\n\nRepel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.", objectives = "" }
WordHunterWoW_QuestEN[40209] = { title = "Scales of the Earth", description = "While leather armor is strong on its own, integrating scales into the design is what truly sets it apart.\n\nThe type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales.\n\nA fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.", objectives = "" }
WordHunterWoW_QuestEN[40210] = { title = "Time Well Spent", description = "Unfortunately, {name}, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership.\n\nGo now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.", objectives = "" }
WordHunterWoW_QuestEN[40211] = { title = "Demon Flesh", description = "Something we haven't really explored yet, {name}, are the creatures of Suramar. Specifically, the demons.\n\nNow I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides.\n\nWe could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide.\n\nPerhaps there's someone in Suramar who can help...", objectives = "" }
WordHunterWoW_QuestEN[40212] = { title = "Wrong End of the Knife", description = "There he is! The man that isn't there! He's... he's...\n\nWait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal.\n\nIf you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.", objectives = "" }
WordHunterWoW_QuestEN[40213] = { title = "Hounds Abound", description = "I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\"\n\nI mean... sorry, {name}. My mind goes to strange places. You want to know about the demons, the ones with durable hides?\n\nBefore I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses.\n\nWe can discuss their hides afterwards.", objectives = "" }
WordHunterWoW_QuestEN[40214] = { title = "Fel Tanning", description = "Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short.\n\nYou want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.", objectives = "" }
WordHunterWoW_QuestEN[40215] = { title = "Mounting Made Easy", description = "{name}, I'm glad you're here. I confess: I've been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art.\n\nThe vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.", objectives = "" }
WordHunterWoW_QuestEN[40216] = { title = "A Hunter at Heart", description = "Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? \n\nYou seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill.\n\nYa best start off with some small game. We don't want the lass to get discouraged.", objectives = "" }
WordHunterWoW_QuestEN[40217] = { title = "An Offering of Ammo", description = "The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions.\n\nOur leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin.\n\nThey hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow.\n\nWhile I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.", objectives = "" }
WordHunterWoW_QuestEN[40218] = { title = "Debt Repaid", description = "I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning.\n\nYou should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.", objectives = "" }
WordHunterWoW_QuestEN[40219] = { title = "In Defiance of Deathwing", description = "It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing.\n\nToday we shall re-live moments of that day through the eyes of our ancestors.\n\nFor this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.", objectives = "" }
WordHunterWoW_QuestEN[40220] = { title = "Thorny Dancing", description = "The Thistleleaf sprites have gone completely mad.\n\nI suspect they are being manipulated by some very mischievous Thorndancers.\n\nPlease, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.", objectives = "" }
WordHunterWoW_QuestEN[40221] = { title = "Spread Your Lunarwings and Fly", description = "These poor faerie dragons are being tortured!\n\nWhat's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later.\n\nThis behavior is simply unacceptable.\n\nPlease free any trapped Lunarwings you can find.", objectives = "" }
WordHunterWoW_QuestEN[40222] = { title = "The Imp Mother's Tome", description = "See this giant cave? There's a terrifyingly powerful imp mother inside.\n\nBut that's not the good part. The good part is what she has.\n\nApparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book.\n\nWe need that power! We need her tome!", objectives = "" }
WordHunterWoW_QuestEN[40224] = { title = "The Hammer in the Deep", description = "<Thrall listens intently.>\n\nYou found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted.\n\nTherazane will open a portal directly there. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[40225] = { title = "A Ring Reforged", description = "Speak with Nobundo, and take your place around the circle, {name}. The Earthen Ring will rise again, with you as its leader!\n\nWithin these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...", objectives = "" }
WordHunterWoW_QuestEN[40227] = { title = "Bad Intentions", description = "Suramar is lost.\n\nOur leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them.\n\nBut cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here...\n\nI rejected both of these options and found myself here. I will find a third way.", objectives = "" }
WordHunterWoW_QuestEN[40228] = { title = "Scout It Out", description = "You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast.\n\nRumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close.\n\nTake this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!", objectives = "" }
WordHunterWoW_QuestEN[40229] = { title = "Step into the Dark", description = "With the threat to my people quelled, I believe it is time to introduce you to my kin.\n\nMeet me at Stonedark Grotto, and you will see where we live.", objectives = "" }
WordHunterWoW_QuestEN[40230] = { title = "Oh, the Clawdacity!", description = "The leader of the Cavemoss makrura, Clawdayshus, has been ordering raids into the Cavemoss village to steal the young for snacks.\n\nThis isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well!\n\nThis is a job for murlocs.\n\nMindmeld with Murky in his egg and show him how it's done!", objectives = "" }
WordHunterWoW_QuestEN[40235] = { title = "Abrogator Arbitrator", description = "Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals, da sooner I can get off dis stupid island. Da amount required is very precise!", objectives = "" }
WordHunterWoW_QuestEN[40236] = { title = "The Dawning Light", description = "It was a miracle that you were able to survive, {name}. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors.\n\nNow we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this.\n\nWe all agree that new leader should be you, {name}. You have shown strength, wisdom, courage, and kindness beyond measure.\n\nWalk with us to the temple and we will announce our decision.", objectives = "" }
WordHunterWoW_QuestEN[40237] = { title = "Work Work Stoppage", description = "We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat.\n\nI've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals.", objectives = "" }
WordHunterWoW_QuestEN[40238] = { title = "A Grim Equation", description = "They were waiting for us when we crashed. It was all we could do to establish our small outpost.\n\nEven now they drain the souls of our fallen to fuel their attacks.\n\nDestroy their soul coffers. Free our comrades and let them join the Light.\n\nWhen you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.", objectives = "" }
WordHunterWoW_QuestEN[40241] = { title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Serr'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", objectives = "" }
WordHunterWoW_QuestEN[40243] = { title = "Break Weapon Racks", description = "", objectives = "" }
WordHunterWoW_QuestEN[40244] = { title = "That Guy in the Costume", description = "Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head.\n\nOne of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out?\n\nYe can ask Tamara over there for a ride.", objectives = "" }
WordHunterWoW_QuestEN[40247] = { title = "Asking a Favor", description = "Caria Felsoul was one of our best... before she answered the Legion's foul call.\n\nShe now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself.\n\nWe sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source.\n\nCould you ask Khadgar for assistance? Our friends in this world are few.", objectives = "" }
WordHunterWoW_QuestEN[40249] = { title = "Vengeance Will Be Ours", description = "We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky.\n\nI think it best if you handle this matter yourself - there are none among us more capable on the field of battle.\n\nSave Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.", objectives = "" }
WordHunterWoW_QuestEN[40253] = { title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", objectives = "" }
WordHunterWoW_QuestEN[40254] = { title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40255] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "" }
WordHunterWoW_QuestEN[40256] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "" }
WordHunterWoW_QuestEN[40257] = { title = "Demon Hunter Choice 1", description = "PLACEHOLDER", objectives = "" }
WordHunterWoW_QuestEN[40259] = { title = "Demon Hunter Choice 2", description = "PLACEHOLDER", objectives = "" }
WordHunterWoW_QuestEN[40261] = { title = "Demon Hunter Choice 3", description = "PLACEHOLDER", objectives = "" }
WordHunterWoW_QuestEN[40265] = { title = "A Touch of Magic", description = "I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin.\n\nI can sense the power of a potent enchanter in you, {name}. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.", objectives = "" }
WordHunterWoW_QuestEN[40266] = { title = "The Lost Advisor", description = "You may as well assist me while you are here. I require a potion to be made, one that will set things right.\n\nI must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon.\n\nThe harpies around here cannot resist cliffthorn. It is what drew them to Tel'anor in the first place. \n\nYou should find plenty just outside this building.", objectives = "" }
WordHunterWoW_QuestEN[40267] = { title = "An Unexpected Message", description = "Ah, Felo'melorn. I am familiar with this weapon. \n\nFor ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. \n\nAs luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her.\n\nI suggest you start your search there. The portal over there will bring you back to the city.", objectives = "" }
WordHunterWoW_QuestEN[40268] = { title = "Neltharion's Vault Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40269] = { title = "Torok's Bluff Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40270] = { title = "The Path of Atonement", description = "Felo'melorn, the runeblade of the kings of Quel'Thalas. It was said to harness the very essence of flame and after being reforged by Kael'thas could even stand against the legendary Frostmourne.\n\nWe thought that the blade was lost with Kael'thas's death but an associate of mine has a lead on where it may be located.\n\nWe need every advantage we can get and with Felo'melorn in your hand the Legion surely will tremble!\n\nAh, our company is here.", objectives = "" }
WordHunterWoW_QuestEN[40297] = { title = "Lyana Darksorrow", description = "<A captive demon hunter floats in stasis in front of you; her soul slowly draining into the harvester crystal.>\n\n<In order to release her from stasis, you will need to destroy the soul harvester.>", objectives = "" }
WordHunterWoW_QuestEN[40300] = { title = "Tools of the Trade", description = "I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers  perform their rituals and venerate the dead.\n\nI would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[40306] = { title = "The Last Chapter", description = "The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair.\n\nI will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.", objectives = "" }
WordHunterWoW_QuestEN[40307] = { title = "Glaive Circumstances", description = "I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured.\n\nI'm not going to mince words, {name}. Azoran plans to use the Burning Legion command ship to destroy Dalaran.\n\nTo stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I'm still weakened from my imprisonment.\n\nSearch for the warglaives on the northern side of the crater, where I was shot down.", objectives = "" }
WordHunterWoW_QuestEN[40308] = { title = "Fragments of Memory", description = "<The beautiful elven burial urn is shattered carelessly on the ground. It was clearly handled roughly, but not scratched by the talons of the harpies.>\n\n<You find a trail of shards leading towards a cave. Those responsible are certainly within. Thaedris would be interested in the relics and their safe return.>", objectives = "" }
WordHunterWoW_QuestEN[40310] = { title = "Shipwrecked Captive", description = "I spent my life playing the pet in other peoples battles. Now it's my time to be the pet tamer! Best part of being dead is I can do this forever!", objectives = "" }
WordHunterWoW_QuestEN[40315] = { title = "End of the Line", description = "I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don't you understand?\n\nWe only need one last ingredient to complete the elixir. You will help me, won't you?", objectives = "" }
WordHunterWoW_QuestEN[40319] = { title = "The Final Ingredient", description = "The potion is complete, {name}. Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward.\n\nMy wife's bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it.\n\nI fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.", objectives = "" }
WordHunterWoW_QuestEN[40320] = { title = "Band of Blood Brothers", description = "You are the one that Toryl was bellowing about? Perhaps you can help me.\n\nWhen I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone.\n\nFind my kin, {name}.\n\nI cannot bear to think that they also share Throndyr's fate.", objectives = "" }
WordHunterWoW_QuestEN[40321] = { title = "Feathersong's Redemption", description = "I must confess I was not entirely honest with you, {name}. I meant to drink the potion and join my wife.\n\nAnd even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her.\n\nCome, young one. Let us take care of the harpy matriarch and restore Tel'anor to its former glory. We cannot let this poison go to waste, eh?", objectives = "" }
WordHunterWoW_QuestEN[40322] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40323] = { title = "Cave of the Blood Trial Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40324] = { title = "Arcane Communion", description = "All of Kel'danath's experiments to connect with the withered failed, and some even made them more dangerous.\n\nUntil he found Theryn.\n\nHis arcane essence - the very soul of the shal'dorei - had been touched by something special. But what? \n\nBy weaving my arcane essence together with Theryn's, I can create an empathic bond. This communion will bare his soul to us all - or what's left of it. \n\nWe need only to feed him mana, and lots of it, in order to begin.", objectives = "" }
WordHunterWoW_QuestEN[40325] = { title = "Scenes from a Memory", description = "Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control.\n\nI will need your help to sort through the visions, so be ready for anything.\n\nWith any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.", objectives = "" }
WordHunterWoW_QuestEN[40326] = { title = "Scattered Memories", description = "<As your fingers trace the elegant symbols on the page, a voice dictates the words in your mind.\n\nIt seems the nightborne have elevated even simple note-taking to a sorcerous art.\n\nArcanist Kel'danath was definitely working in this area. There must be more of his notes scattered around.>", objectives = "" }
WordHunterWoW_QuestEN[40327] = { title = "Testing the Metal", description = "Alright, if we're going to get out of here, we're going to have to maneuver around the naga and the sea giants.\n\nThe naga probably won't pose much trouble for someone of your skill, but those sea giants are strong beyond belief.\n\nJust get me out of this cave safely and I can find my own way home.\n\nHopefully this armor Celea made for me will protect me long enough to see this through.", objectives = "" }
WordHunterWoW_QuestEN[40328] = { title = "A Fate Worse Than Dying", description = "When the Burning Legion takes a prisoner, it is not an act of mercy.\n\nWhile death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul.\n\nThe Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored.\n\nThough countless have already perished in the soul engine, you may yet save those still alive inside.\n\nHurry and release them before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[40329] = { title = "Battle Pet Tamers: Warlords", description = "You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison.\n\nBy defeating them will show your dominance in Draenor.", objectives = "" }
WordHunterWoW_QuestEN[40331] = { title = "Bite of the Sashj'tar", description = "If I had been by Throndyr's side when he fought the naga, he might still be alive.\n\nThese serpents will regret the day that they decided to slither from their watery hole!\n\nKilling them is not enough. No! I will honor Throndyr with a necklace of naga fangs!", objectives = "" }
WordHunterWoW_QuestEN[40332] = { title = "Beach Bonfire", description = "Do not let... my body lie in... the mud.\n\nSet my flesh... aflame.", objectives = "" }
WordHunterWoW_QuestEN[40333] = { title = "Spiritwind Summit Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40334] = { title = "Fisherman's Tonic", description = "If you detest these serpents as much as we do, I ask that you continue the fight against them.\n\nThat will mean fighting them in their watery domain. I don't see any gills on you, so we're going to have to concoct an old tonic used by vrykul fishermen.\n\nThe ingredients are plentiful around here, taken that you do not mind picking through entrails.", objectives = "" }
WordHunterWoW_QuestEN[40336] = { title = "Turning the Tidemistress", description = "The Tidemistress has fallen back to the elven ruins and is licking her wounds.\n\nHer guard is undoubtedly protecting her. To best her, you will have to break her defenses.\n\nConstruct a ballista using the parts that you salvaged and end her once and for all.", objectives = "" }
WordHunterWoW_QuestEN[40339] = { title = "Candle of Command", description = "You no come in yet! Give orders to other kobold on Throne of Ordering Around if you want in, then maybe we talk.", objectives = "" }
WordHunterWoW_QuestEN[40341] = { title = "Throne of the Tides: Azshara's Power", description = "Wavespeaker Adelee tracked Sharas'dal to the Throne of Tides within the Abyssal Maw, then disappeared. {name}, if we go after her, we are almost certainly walking into a trap.\n\nBut the elements are with us, my friend. The naga will not expect a shaman of your caliber!\n\nSwim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let's find our missing shaman and get that artifact!", objectives = "" }
WordHunterWoW_QuestEN[40342] = { title = "Surprise the Sashj'tar", description = "The naga are preoccupied with recruiting the sea giants for Queen Azshara's battles in other lands.\n\nNow is the time to strike!", objectives = "" }
WordHunterWoW_QuestEN[40345] = { title = "Burn the Candle at Both Ends", description = "Why you come back already? Have to wait until jobs are done or I no let you through!\n\nGo back to Throne of Ordering Around and make sure they finish!", objectives = "" }
WordHunterWoW_QuestEN[40346] = { title = "Pilfered Provisions", description = "The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.", objectives = "" }
WordHunterWoW_QuestEN[40348] = { title = "Something in the Water", description = "There is something fouling these waters, {class}.\n\nWe will need to purify the waters in order to restore balance to the elemental forces below this ruin.\n\nThe magic here has warped the elementals and they are beyond restoration. Release their corrupted forms so that they may be reborn pure.", objectives = "" }
WordHunterWoW_QuestEN[40349] = { title = "Pristine Violetglass Vessel", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40350] = { title = "Pristine Inert Leystone Charm", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40351] = { title = "Pristine Quietwine Vial", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40352] = { title = "Pristine Pre-War Highborne Tapestry", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40353] = { title = "Pristine Nobleman's Letter Opener", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40354] = { title = "Pristine Trailhead Drum", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40355] = { title = "Pristine Moosebone Fish-Hook", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40356] = { title = "Pristine Hand-Smoothed Pyrestone", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40357] = { title = "Pristine Drogbar Gem-Roller", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40358] = { title = "Pristine Stonewood Bow", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40359] = { title = "Pristine Imp's Cup", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40360] = { title = "Pristine Flayed-Skin Chronicle", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40361] = { title = "Pristine Malformed Abyssal", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40362] = { title = "Pristine Orb of Inner Chaos", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40363] = { title = "Pristine Houndstooth Hauberk", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "" }
WordHunterWoW_QuestEN[40364] = { title = "Bubble Trouble", description = "{class}! The sea giants have already eaten half of my kin.\n\nWe are helpless in these accursed bubbles. I beseech you to get us out of here.\n\nTake heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.", objectives = "" }
WordHunterWoW_QuestEN[40368] = { title = "Turtle Powered", description = "In order to locate and purify the source of the corruption I am going to need an elemental focus.\n\nThe turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!", objectives = "" }
WordHunterWoW_QuestEN[40370] = { title = "Purge the Unclean", description = "Do you feel it in the air, {race}? The stage is set for us to make things right.\n\nWhile you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel'anor.\n\nTake the ritual focus, it should help you during the battle.", objectives = "" }
WordHunterWoW_QuestEN[40372] = { title = "The Tidemistress", description = "The forces of the Tidemistress have been shattered. All that remains is to confront the her and push back the naga for good.", objectives = "" }
WordHunterWoW_QuestEN[40373] = { title = "A New Direction", description = "{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\nIf you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.", objectives = "" }
WordHunterWoW_QuestEN[40378] = { title = "Enter the Illidari: Ashtongue", description = "Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force.\n\nThere are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple.\n\nLike most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don't you? Let us bring in our Ashtongue forces.", objectives = "" }
WordHunterWoW_QuestEN[40379] = { title = "Enter the Illidari: Coilskar", description = "The next gateway's down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side.\n\nPersonally, I wouldn't have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we'll see.\n\nWe'll have to find a way to power the gateway's activator. Like this last gateway, it runs on souls.\n\n<Allari the Souleater grins as Sevis says this.>", objectives = "" }
WordHunterWoW_QuestEN[40384] = { title = "Needs of the Hunters", description = "The eagle appears to have a message for you:\n\n             To: {name}\n\nThe time has come to strike back at the Legion.\n\nMeet me at Hunter's Reach in Dalaran as soon as you can.\n\n             -Emmarel Shadewarden", objectives = "" }
WordHunterWoW_QuestEN[40385] = { title = "The Spear in the Shadow", description = "Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned.\n\nI have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe.\n\nThe weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[40388] = { title = "Huln's War - Shadowsong", description = "Someone with whom I believe you are familiar commands in the battlefield below.\n\nJarod Shadowsong speaks highly of you, and has requested that you join him in battle.\n\nHe has plans to put an end to this fight.", objectives = "" }
WordHunterWoW_QuestEN[40391] = { title = "Take Me To Your Leader", description = "I am glad you are here, {name}.\n\nThis... Khadgar, the archmage who found my message, has called a meeting.\n\nHe wishes to meet us at the entrance to the city as soon as possible.\n\nWill you accompany me? I have the strangest feeling that he will not be alone.", objectives = "" }
WordHunterWoW_QuestEN[40392] = { title = "Call of the Marksman", description = "Time is of the essence! If Alleria and Thas'dorah are in Legion hands, it is only a matter of time until both are forfeit.\n\nIf you are ready, head to the Broken Shore to meet with Ranger-General Windrunner.\n\nShe has lent her personal hippogryph to fly you down to the surface.", objectives = "" }
WordHunterWoW_QuestEN[40393] = { title = "Axes for Arrows", description = "The scales of these naga are as strong as any armor. My arrows can barely pierce them. I need something better to strike these naga down.\n\nThe spines of the nearby Axetails make excellent arrowheads. I will watch over the camp while you are gone.", objectives = "" }
WordHunterWoW_QuestEN[40394] = { title = "Fish and Supplies", description = "Hail, {name}.\n\nWe need to restock our supplies after the naga attack. Too many of us are injured to properly hunt and forage.\n\nYou have helped us in the past. Would you help us yet again?", objectives = "" }
WordHunterWoW_QuestEN[40396] = { title = "That's the Spirit", description = "<Fjolrik motions for you to come closer.>\n\nHey {name}. I have heard stories of these naga distilling some concoction.\n\nI do not know what they use it for, but I have heard rumors that it provides a vrykul with a might kick, if you follow me.\n\nAsta will thank you for it.", objectives = "" }
WordHunterWoW_QuestEN[40400] = { title = "Clandestine Operation", description = "You have long been a trusted hero of the Alliance, {name}. And like the rest of us, you have endured many hardships to reach this point.\n\nNow, I must ask even more of you. Will you hear me out?", objectives = "" }
WordHunterWoW_QuestEN[40401] = { title = "A Way Back In", description = "I must get back into Suramar.\n\nI was exiled unfairly! I cannot live out here like this. I need the Nightwell's energies...\n\nI saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city.\n\nIt said \"We shall drink of the Well again.\"\n\nI cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.", objectives = "" }
WordHunterWoW_QuestEN[40402] = { title = "Clandestine Operation", description = "As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", objectives = "" }
WordHunterWoW_QuestEN[40403] = { title = "Clandestine Operation", description = "It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", objectives = "" }
WordHunterWoW_QuestEN[40408] = { title = "Weapons of Legend", description = "Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion.\n\nWe cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused.\n\nThat is why I asked you here, {name}. As one of our greatest champions, you must be our voice of reason and decide our next move.", objectives = "" }
WordHunterWoW_QuestEN[40412] = { title = "Azoran Must Die", description = "You won't have much time before the Legion is aware of your presence on the ship.\n\nWhen the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal.\n\nI will not let them succeed.\n\nI will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship.\n\nWe don't have much time... you must attack swiftly and without mercy.", objectives = "" }
WordHunterWoW_QuestEN[40415] = { title = "Well Spent Time", description = "Your respect for our ways has earned you all the knowledge we have to teach. Go now, {name}, and spread our ways to those who fight against the legion.\n\nPerhaps it will help to turn the tide in this war for our world.", objectives = "" }
WordHunterWoW_QuestEN[40417] = { title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting....", objectives = "" }
WordHunterWoW_QuestEN[40418] = { title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", objectives = "" }
WordHunterWoW_QuestEN[40419] = { title = "Rescue Mission", description = "The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims.\n\nIn case it's a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran.\n\nThis demonic magic is anathema to the mage, so we must move quickly. I'm ready when you are, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40424] = { title = "A Desperate Journey", description = "The city's entrances are under heavy guard. He must have another way.\n\nThanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack.\n\nYou will accompany me, {race}. You and this Astoril are my only chance at surviving now. \n\nI remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.", objectives = "" }
WordHunterWoW_QuestEN[40457] = { title = "Riverbend Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40458] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40459] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40460] = { title = "Pinerock Basin Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40461] = { title = "Fields of An'she Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40462] = { title = "Fields of An'she Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40463] = { title = "Fields of An'she Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40464] = { title = "Mucksnout Den Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40465] = { title = "Rockcrawler Chasm Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40466] = { title = "Howling Hills Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40467] = { title = "Howling Hills Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40468] = { title = "Bitestone Enclave Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40469] = { title = "Final Preparations", description = "We will need supplies for our trip into Suramar. We cannot exactly stop for refreshments at the gate with you two in tow, can we?\n\nThe water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval.\n\nThat's where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.", objectives = "" }
WordHunterWoW_QuestEN[40470] = { title = "Quality of Life", description = "I am afraid, {name}. We're so close to home, so close to salvation...\n\nAstoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?", objectives = "" }
WordHunterWoW_QuestEN[40485] = { title = "Skyhorn Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40486] = { title = "Skyhorn Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40490] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40492] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40495] = { title = "Ulthalesh, the Deadwind Harvester", description = "The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then he can get Ulthalesh!\n\nCalydus will wait here and await your return. Find Ulthalesh, friend!", objectives = "" }
WordHunterWoW_QuestEN[40504] = { title = "Skyhorn Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40512] = { title = "Snowblind Mesa Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40513] = { title = "Oro's Overlook Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40515] = { title = "A Walk With the Spirits", description = "The spiritwalker you saved from Riverbend has been insufferable since his arrival. He is insisting on showing you the ways of our people so that you better understand what is to come.\n\nHe is a strange one, even by spiritwalker standards.\n\nEven so, only a fool would discard his insight. Please, go to speak with him when you get a moment.", objectives = "" }
WordHunterWoW_QuestEN[40517] = { title = "The Fallen Lion", description = "I haven't left the deck of this ship since we got back. The fleet must be made ready for war. Don't know where we will be needed, but when the call comes, we'll be ready.\n\nTruth be told... I welcome the distraction. The others are paying their respects to Varian, but I... I cannot bring myself to face that casket. To face his son.\n\nVarian gave me a letter he wrote to Anduin. Please, take it to him on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[40518] = { title = "The Battle for Broken Shore", description = "Your warship awaits at the end of the dock, {name}. May your weapon bring you many kills today.\n\nThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", objectives = "" }
WordHunterWoW_QuestEN[40519] = { title = "Legion: The Legion Returns", description = "Heroes of the Alliance, I write to you in Azeroth's darkest hour. From the maw of hell, the burning armies of the Legion have returned.\n\nOur fleets depart for the Broken Isles at once. As a grand lance, we will pierce the Legion's lines and drive them back to the nether that spawned them.\n\nYour ship awaits in the Stormwind Harbor, make haste.", objectives = "" }
WordHunterWoW_QuestEN[40520] = { title = "To See the Past", description = "I would like for you to experience firsthand what Huln Highmountain was able to accomplish in a single battle during the War of the Ancients.\n\nTo do so, I will need very specific ingredients. They are not too difficult to obtain--you can find all of them near Thunder Totem.", objectives = "" }
WordHunterWoW_QuestEN[40522] = { title = "Fate of the Horde", description = "It is a wonder any of our troops survived that bloodbath on the Broken Shore. If not for Lady Sylvanas...\n\nHigh Overlord Saurfang has been asking for you at Grommash Hold. He will not say why... but he was insistent that I send you to him.", objectives = "" }
WordHunterWoW_QuestEN[40523] = { title = "Facet-nating Friends", description = "Excuse me, sir. Are you sure you're in the correct shop? We only deal in the finest of jewels here.\n\nAhh, I see... you're a fellow lapidary. Then perhaps we can work together.\n\nIntroduce yourself to my associates, so they're aware of who you are and what you may have to offer.", objectives = "" }
WordHunterWoW_QuestEN[40524] = { title = "A Familiar Ring to It", description = "{name}! Let's talk bling. I'm looking for a ring.\n\nSee, the elves down in Azsuna were some fine master jewelcrafters back in the day... or so they say. The books all talk about a ring called the \"Band of Farondis\". Can't hurt to ask around for it.\n\nLet's head to Azsuna. Bet I'll get there sooner!", objectives = "" }
WordHunterWoW_QuestEN[40525] = { title = "Getting the Band Back Together", description = "I like our dynamic, {name}. You're the muscle with all the hustle! And I'm the brains who entertains!\n\nI think this next task is all on you. Try to find that ring, or whatever the murlocs left of it.", objectives = "" }
WordHunterWoW_QuestEN[40526] = { title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", objectives = "" }
WordHunterWoW_QuestEN[40527] = { title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", objectives = "" }
WordHunterWoW_QuestEN[40528] = { title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", objectives = "" }
WordHunterWoW_QuestEN[40529] = { title = "Truly Outrageous", description = "Ore prospecting is our primary method of gem acquisition. And while prospecting... you're bound to find small, unusable gem chips.\n\nMany gem shops simply discard the small gem chips they find, but we here at Cartier & Co. let nothing go to waste.", objectives = "" }
WordHunterWoW_QuestEN[40530] = { title = "An Eye for Detail", description = "{name}, if there's one thing I despise, it's slander. A rumor is spreading that one of my recent commissions is a fake.\n\nWe need to quell these rumors as quickly as possible.\n\nI need you to visit the customers I recently worked for and examine their gems. If your claim of being a jewelcrafter is true, then you will be able to spot a fake gem from a mile away.\n\nHere's the list of my patrons. Return immediately if you find any truth to these rumors.", objectives = "" }
WordHunterWoW_QuestEN[40531] = { title = "Swift Vengeance", description = "I swear, when I find him...\n\n<Tiffany catches your eye and regains her composure.>\n\n{name}, I need you to track down my FORMER associate, Harold Winston. I doubt he's gotten far, given our location.\n\nWhen you find him, I would like you to recover the stolen property and return it to me.\n\nUse any means necessary. And don't worry about Ms. Moore's jewels, I'll redeliver a fresh supply to her personally.", objectives = "" }
WordHunterWoW_QuestEN[40532] = { title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Deadly Deep Amber.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", objectives = "" }
WordHunterWoW_QuestEN[40533] = { title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Quick Azsunite.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", objectives = "" }
WordHunterWoW_QuestEN[40534] = { title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Masterful Queen's Opal.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", objectives = "" }
WordHunterWoW_QuestEN[40535] = { title = "Raising the Drogbar", description = "Word travels fast around Dalaran, {name}. And the latest word is that there's a master jewelcrafter somewhere in Val'sharah.\n\nI want you to go down there and find this master.  Perhaps they have designs that can help bolster business here at the shop.\n\nI've heard the name \"Lasune Starblade\" tied to these rumors. She might be a good place to start looking.", objectives = "" }
WordHunterWoW_QuestEN[40536] = { title = "Bruls Before Jewels", description = "So, you wish to learn what Jabrul knows about jewels?\n\nWell, Jabrul needs your help. Before we leave this place, Jabrul still needs harpy necklaces.\n\nKeep those harpies off of Jabrul while he takes their necklaces and Jabrul will reward you with his knowledge.", objectives = "" }
WordHunterWoW_QuestEN[40537] = { title = "Drawing Blood", description = "Hey, {name}! I have something exciting to tell you about, but you must keep a secret. Just between us scribes.\n\n<Zooey gives you a wink and pulls out a large tome.>\n\nThis is the Bloodbound Ledger. Inscribing your name in it allows you to learn how to craft \"blood contracts\" which can hurt a little bit, but are absolutely worth it!\n\nI currently know one of them and I get so excited when I use it 'cause it... well, you'll see.\n\nSo whaddya say? Interested?", objectives = "" }
WordHunterWoW_QuestEN[40538] = { title = "Lapidary Lessons", description = "It's good to see you again, {name}.\n\nIt seems we've both been busy since last we spoke. I have something that you may be interested in.\n\nA recent shipment of rare jewels called maelstrom sapphires have finally arrived here at the shop.\n\nI came up with a beautiful design for them and would like to show you how to cut them into something useful.", objectives = "" }
WordHunterWoW_QuestEN[40539] = { title = "Hidden Intentions", description = "Word on the street is, yer a reliable resource for getting things done, let's say, discreetly.\n\nSo here's the job. I need a new set of lock picking tools. But not just any old lock picks will do.\n\nI need something special, something that won't break if ye apply too much pressure.\n\nI'm thinking a set of diamond lock picks might do the trick. That would be lock picks made out of diamond, not the ones shaped like a diamond.\n\nLook, ye in or what?", objectives = "" }
WordHunterWoW_QuestEN[40540] = { title = "Come at Me, Brul", description = "{name}, I received a... well, what can only be constituted as a \"letter\", carved into a piece of flat rock.\n\nThat jewelcrafting master you found in Val'sharah has sent for you. He said he's in Stormheim currently.\n\nWhen you see him, would you be so kind as to inform him that we don't wish to receive any more of his requests for your presence. They just make a mess.", objectives = "" }
WordHunterWoW_QuestEN[40541] = { title = "The Charge Within", description = "Before Jabrul shares his designs with you, he needs you to help him with a special project.\n\nJabrul has a jewel that can trap storm energy. The more lightning it traps, the brighter it shines.\n\nJabrul thinks the storm drakes' power would be better spent in his jewel than terrorizing the skies of Stormheim.\n\nDon't you?", objectives = "" }
WordHunterWoW_QuestEN[40542] = { title = "Eyes of Nashal", description = "Deadly eye of prophecy... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", objectives = "" }
WordHunterWoW_QuestEN[40543] = { title = "Eyes of Nashal", description = "Quick dawnlight... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", objectives = "" }
WordHunterWoW_QuestEN[40544] = { title = "Eyes of Nashal", description = "Masterful shadowruby... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", objectives = "" }
WordHunterWoW_QuestEN[40545] = { title = "Aww Scrap!", description = "It's a catastrophe! No, even worse, a conspiracy!\n\nI heard the Legion was back again, and I thought to myself, \"Hobart, now's your time to shine.\"\n\nI made us enough guns to blow those demons back to the beginning of time!\n\nBut then we get here, and what happens? Everyone just happens to \"find\" all these ancient artifacts to fight the demons with!\n\nLong story short, I have too many guns and need to get rid of 'em.", objectives = "" }
WordHunterWoW_QuestEN[40546] = { title = "Mysteries of Nature", description = "Jabrul wants to show you his special crystals. Nobody knows what they do. Very mysterious.\n\nIf you want to learn how to make one, Jabrul would be happy to show you.\n\nHigh in the mountains live storm drakes. They blast the cliffs with their lightning breath and sometimes blast so hard, they turn the rock to crystal.\n\nGet a piece of that crystal and bring it back to Jabrul.", objectives = "" }
WordHunterWoW_QuestEN[40547] = { title = "To Dalaran, With Love", description = "Jabrul was thinking that he'd like to come up to Dalaran and discuss jewel designs with the masters.\n\nBut Jabrul doesn't know how to get up to it. Jabrul did have an interesting idea that might work.\n\nIf you mailed Jabrul to Dalaran, then surely he'd arrive safe and sound.", objectives = "" }
WordHunterWoW_QuestEN[40556] = { title = "Jabrul Needs You", description = "Hello {name},\n\nJabrul needs your help with something. Could you please come to Azsuna and find Jabrul?\n\nThank you,\n\nJabrul", objectives = "" }
WordHunterWoW_QuestEN[40558] = { title = "Socket to Me", description = "You admire the contraption sitting on the counter. There's a button on it, but pressing it seems to warrant no response.\n\nTiffany tells you that it's an old toy box, but the crystal components are all broken.\n\nIf you were to find new ones, she could repair it and teach you how to make one for yourself.", objectives = "" }
WordHunterWoW_QuestEN[40559] = { title = "Black Rook Hold: The Raven's Wisdom", description = "{name}, I've been hearing a lot of talk about Black Rook Hold from our friend here, about a room which contains volumes of texts on just about every type of craft there is.\n\nI'm willing to bet there's a book in there on jewelcrafting that could come in handy for us.\n\nGo there and bring me back anything you find. I'll share a sweet new design I came up with you when you return.", objectives = "" }
WordHunterWoW_QuestEN[40560] = { title = "Maw of Souls: Spiriting Away", description = "What I'm about to ask you to do is no easy task, {name}.\n\nI need you to die. But, you'll be able to come back of course! \n\nThere's a ship, the Naglfar, that ferries souls from this world to the next. It's said that an ancient treasure called the Ring of the Fallen rests in the bowels of that ship.\n\nYou know me, {name}, and nothing catches my interest more than a sweet looking ring.\n\nFind a way onto that boat and bring me back that ancient treasure.", objectives = "" }
WordHunterWoW_QuestEN[40561] = { title = "Halls of Valor: Jewel of the Heavens", description = "Queens and kings wear the best rings! And I've heard that a certain king of gods has made his presence available.\n\nIn the Halls of Valor, the ruler Odyn has treasures unlike anyone in existence. If you happen to go there, try and... obtain, let's say, one of his rings for me.\n\nI doubt he'll just hand it over, so you may have the fight of a lifetime in store.", objectives = "" }
WordHunterWoW_QuestEN[40562] = { title = "A Personal Touch", description = "{name}, great to see you again. It feels like forever since last we spoke.\n\nWe've received some information about a group of jewelcrafting nightborne in Suramar that are doing fantastic things with necklaces. I'd like to take a look at some of their gems.\n\nAnd their designs.\n\nAnd... a new loupe might be nice, too. I hear the city inspectors carry them.", objectives = "" }
WordHunterWoW_QuestEN[40567] = { title = "Darkheart Thicket: Enter the Nightmare", description = "We could not save Ysera, but we did prevent her from destroying the temple.\n\nNow I can finally turn my attention to my husband.\n\nI do not know what fate he suffers now. I only know that if we stand any chance of saving him, you must go now.\n\nFollow Xavius into the Nightmare and find Malfurion.\n\nPlease, save my husband if you can.", objectives = "" }
WordHunterWoW_QuestEN[40568] = { title = "Fury of the Storm", description = "The Felskorn who ravage my brood were once Drekirjar - a tribe with whom we shared an ancient pact. Now, under the influence of the God-King, they forsake their oaths and strike at the forebears of their coveted drakes.\n\nThey should answer for this slight.\n\nAwaken your fury, {class}, and take the battle to them!", objectives = "" }
WordHunterWoW_QuestEN[40569] = { title = "The Legend of the Sands", description = "Nothing! There is next to nothing in our records about this weapon!\n\nI've checked and re-checked, and can find barely a shred of a tale. This can only mean that the story comes from a land outside Pandaria.\n\nLi Li Stormstout is young, but she is the most traveled on the entire isle except for you. If anyone might know of this weapon, it is she.", objectives = "" }
WordHunterWoW_QuestEN[40570] = { title = "Into The Heavens", description = "This stone is saturated with elemental power, possibly the remnant of the magic used against Irmaat!\n\nIf you went outside and held the stone aloft, it should unleash the stone's essence as a mighty whirlwind. So potent a windstorm could carry you and your companion all the way to Skywall!\n\nIf the hand blades of Irmaat, the Fists of the Heavens, are as powerful as the old tales say, they would certainly be found there.", objectives = "" }
WordHunterWoW_QuestEN[40573] = { title = "The Nightmare Lord", description = "You arrived just in time, friend.\n\nKagraxxis was moments away from sacrificing me to his master... I was certain I would perish.\n\nI am grateful, but we are not out of danger yet... Xavius has returned.\n\nThe Nightmare Lord is here in Val'sharah, personally orchestrating the corruption of this land. My captor revealed as much to me before I was to be sacrificed.\n\nWe must find Thaon Moonclaw and inform him before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[40578] = { title = "Paying Respects", description = "All I see is despair.\n\nLook, {race}. The grounds are overwhelmed with these wraiths, spirits of those interred here. Something has made them angry and they are lashing out. I can feel their pain.\n\nI will go look for remaining relics, and there is a tomb I must see. It is too late for these unfortunate souls. Please defeat any you find and return them to the rest they deserve.", objectives = "" }
WordHunterWoW_QuestEN[40579] = { title = "Weapons of Legend", description = "As the greatest warrior in these halls, you require a great weapon to do both your will and mine. I have looked down on Azeroth and found artifacts worthy of your hands.\n\nI leave it to you to choose which artifact you wish to seek out and wield against the Legion. We will recover the others in time.", objectives = "" }
WordHunterWoW_QuestEN[40583] = { title = "Making the Cut - Choice UI - Deadly Deep Amber", description = "", objectives = "" }
WordHunterWoW_QuestEN[40585] = { title = "Thus Begins the War", description = "The Legion thinks you are dead. It will be quite the surprise when you punish them for that assumption!\n\nThis allows us to see all across the Broken Isles and assign warriors to various tasks.\n\nOnce you've taken a look, you should choose your first area of operation. I've already picked out the best spots!", objectives = "" }
WordHunterWoW_QuestEN[40586] = { title = "Making the Cut - Choice UI - Quick Azsunite", description = "", objectives = "" }
WordHunterWoW_QuestEN[40587] = { title = "Making the Cut - Choice UI - Masterful Queen's Opal", description = "", objectives = "" }
WordHunterWoW_QuestEN[40588] = { title = "Following the Curse", description = "Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them.\n\nThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.\n\nCome with me to Ariden's camp. I will explain on the way.", objectives = "" }
WordHunterWoW_QuestEN[40593] = { title = "Demons Among Us", description = "The king is wise to focus on the Legion's threat, {name}. Even now, the demons move against us.\n\nThe Illidari will aid the cause of the Alliance. We believe they have set their sights on key locations around Azeroth. In fact, they could already be in your midst!\n\nI sense they are close...", objectives = "" }
WordHunterWoW_QuestEN[40594] = { title = "Justice Rains from Above", description = "Kill now, grieve later!\n\nHere, champion, take flight with one of my war eagles. Use the powers bestowed upon you by our united tribes and help us rain destruction down on these drogbar.\n\nLet us clog that new doorway to their lair with the bodies of their own!", objectives = "" }
WordHunterWoW_QuestEN[40597] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40598] = { title = "Finishing Touches - Choice UI - Skystone Loop", description = "", objectives = "" }
WordHunterWoW_QuestEN[40599] = { title = "Finishing Touches - Choice UI - Deep Amber Loop", description = "", objectives = "" }
WordHunterWoW_QuestEN[40600] = { title = "Finishing Touches - Choice UI - Azsunite Loop", description = "", objectives = "" }
WordHunterWoW_QuestEN[40602] = { title = "The Strength to Triumph", description = "I've been pouring through every last tome and scroll in our archives, and we've managed tae come up with a few ways we might further empower the Ashbringer - could ye take a look?\n\nIt will take some time to gather all of my notes, so we'll have tae focus on one at a time.", objectives = "" }
WordHunterWoW_QuestEN[40603] = { title = "Seeking the Valkyra", description = "We simply cannot risk another catastrophe like that; we have to protect the Heart against fel energy before we continue our work.\n\nThe mighty Ashildir has proven willing to aid those who she deems worthy, and her master just may be able to help us protect the Heart.\n\nYou should seek her out at the Vault of Eyir in Stormheim. I'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[40604] = { title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", objectives = "" }
WordHunterWoW_QuestEN[40605] = { title = "Keep Your Friends Close", description = "The Legion is bold indeed to strike at the Horde's stronghold! You aided our defense, but now I have a more important task for you.\n\nIt seems the demon hunters will play a crucial part in this war... but I still don't trust them. You will be my envoy to the Illidari. Learn what they know. Study their techniques. If they betray us, we'll use their own knowledge against them.\n\nTheir camp lies atop the plateau in the city. Go. Nathanos and I will clean up this mess.", objectives = "" }
WordHunterWoW_QuestEN[40606] = { title = "To Point the Way", description = "Though the journal devolves into dark ramblings written in hurried scribbles, one entry stands out:\n\n\"Ulthalesh. The name rings in my head. I can hear it calling, but where?\n\n\"The spirits... the very land here is tied to it. It is no wonder we would so often get lost in this place. The forces pull my compass point in every direction...\n\n\"Perhaps if it had a stronger pull, the compass could show the way...\"", objectives = "" }
WordHunterWoW_QuestEN[40607] = { title = "Demons Among Us", description = "Look around. What do you see?\n\n<Allari glares at something over your shoulder.>\n\nThe Legion has already infiltrated the Horde... even now, they are among you.\n\nWe must protect your Warchief.\n\nWhen you are ready to see what lies beneath the veil, say the word.", objectives = "" }
WordHunterWoW_QuestEN[40608] = { title = "The Mark", description = "Your blade is powerful, but it has not yet met its full potential. The all-powerful Odyn in the Halls of Valor can bestow upon you his strength.\n\nIn order to seek this blessing, you must bring him a worthy tribute. I know where you may obtain such a gift, but in order to retrieve it you must first receive the mark of the Valkyra.\n\nProve yourself worthy of our mark, champion, then you may enter the Vault of Eyir- the goddess will guide you from there.", objectives = "" }
WordHunterWoW_QuestEN[40611] = { title = "The Fate of Deadwind", description = "The journal mentions a \"stronger pull\" for the compass. If the spirits of this place are indeed tied to it, they may serve as the pull we need.\n\nI've come upon several locations in the pass where restless spirits tend to appear. Perhaps if you show the spirits there the compass, they may be able to help point it in the right direction.\n\nYou seek these locations out. I'll continue on to Karazhan and see if I can find anything leading to the Dark Riders.", objectives = "" }
WordHunterWoW_QuestEN[40613] = { title = "Maw of Souls: Retrieving the Svalnguard", description = "The Svalnguard was once Odyn's shield; it is said that it hid the Halls of Valor from the endless darkness below his realm.\n\nHelya, who was cast from the shining halls long ago, stole the Svalnguard and keeps it on her accursed ship, the Naglfar.\n\nYou must board the Naglfar, defeat Helya, and retrieve the Svalnguard - it will make a worthy tribute for Odyn.", objectives = "" }
WordHunterWoW_QuestEN[40614] = { title = "A Feast Fit for Odyn", description = "It is customary in the Halls of Valor to feast after battle is finished. Presenting a truly glorious feast to Odyn from beasts worthy of his throne will show him your determination to earn his blessing.\n\nAcquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and the finest cut of steak from Leytusk in Azsuna. They will make a feast worthy of the great battle to come.", objectives = "" }
WordHunterWoW_QuestEN[40615] = { title = "Halls of Valor: Odyn's Blessing", description = "You are ready, {class}.\n\nTravel to Odyn's shining halls and offer the feast on the altar just inside. Mighty Odyn will then set his gaze upon you - you must pass the ancient trials of the Valarjar under his watch.\n\nOnly then will you receive Odyn's blessing.", objectives = "" }
WordHunterWoW_QuestEN[40617] = { title = "Turn Around, Nighteyes", description = "Stranger, you must help me!\n\nNighteyes, my old friend... he was scouting ahead and I heard him cry out a warning. I tried to run after him, but in my carelessness I stepped in this trap.\n\nHe's so close, just on the other side of this ridge. Please find him!", objectives = "" }
WordHunterWoW_QuestEN[40618] = { title = "Weapons of Legend", description = "Three weapons... three worthy paths.\n\nAcquiring one such artifact will be the first step in battling the Legion. The weapon will grow in power as you wield it, so you must choose the one which will be the focus of your efforts, {name}.\n\nAfter a time, you will be able to pursue the other weapons. But you must decide which to seek first.", objectives = "" }
WordHunterWoW_QuestEN[40623] = { title = "The Dark Riders", description = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "" }
WordHunterWoW_QuestEN[40625] = { title = "A Different Source", description = "I need you to fetch me something.\n\nI think I might be on the verge of a breakthrough of a new source of magic, but I require tools. \n\nI can no longer access my workshop, but I have seen the smaller demons below using tools. Bring me one of their tools and I can save our people.", objectives = "" }
WordHunterWoW_QuestEN[40631] = { title = "Basking in Glory", description = "You... you glow with the radiance of Odyn himself...\n\nYou must return to your people at once. Odyn's light is a gift that must be shared with all.", objectives = "" }
WordHunterWoW_QuestEN[40632] = { title = "Take Me To Your Leader", description = "I am glad you are here, {name}.\n\nThis... Khadgar, the archmage who found my message, has called a meeting.\n\nHe wishes to meet us by the entrance to the city as soon as possible.\n\nWill you accompany me? I have the strangest feeling that he will not be alone.", objectives = "" }
WordHunterWoW_QuestEN[40633] = { title = "Off To Adventure!", description = "Oh I'd love to go see if that story is true! But Pops is too busy stuffing his gut and being a grouch to let me go do any real exploring. He even told me that I can't leave the village unless I have a guardian!\n\nIs Pops for real? I can protect myself just fine!\n\nSay, would you be my guardian? Please, get me away from this boredom and you will totally be my hero!", objectives = "" }
WordHunterWoW_QuestEN[40634] = { title = "Thunder on the Sands", description = "I know the tale of Irmaat well. It is said that his home was the ancient city of Ahmtul, long buried under the desert sands.\n\nRecently a strange storm has appeared over the ruins. What's more, I am told that an elemental called Nader has attacked my people in nearby lands.\n\nThese events must be related.\n\nFind this Nader and put an end to him. Make sure to search his body for clues as to what is behind this.", objectives = "" }
WordHunterWoW_QuestEN[40635] = { title = "Sashj'tar Slayer", description = "I cannot believe that Throndyr is gone.\n\nBy the horns on my head, we shall have revenge for all of the pain that the Sashj'tar have inflicted on us!\n\nPress forward, {name}. Kill them! Kill them all!", objectives = "" }
WordHunterWoW_QuestEN[40636] = { title = "Prepare To Strike", description = "The Burning Legion took us by surprise at the Peak of Serenity. We will not allow them to do so again!\n\nWe have trained hard, but we need weapons capable of destroying this great evil if we are to have any chance of success.\n\nOur scrolls speak of several weapons that should prove suitable, but we are unable to decide which one to pursue first.\n\nThe choice, Grand Master, is yours.", objectives = "" }
WordHunterWoW_QuestEN[40637] = { title = "Proof of Honor", description = "<Brandolf breathes heavily.>\n\nThis cave will be my final resting place, {name}.\n\nFind Toryl. Tell her of what happened here today.\n\nTell all of Jandvik that I died defending our village...", objectives = "" }
WordHunterWoW_QuestEN[40642] = { title = "Power! Get The Power!", description = "I need more power. I need more!\n\nI can control the energies, and they are enough to sustain me. For now.\n\nI will not end up withered, like those weaklings.\n\nGo out into Felsoul Hold and slay the demons. Bring me their essence and make it quick!", objectives = "" }
WordHunterWoW_QuestEN[40643] = { title = "A Summons From Moonglade", description = "{name}, Your presence is requested at Moonglade at once.\n\nWe are preparing for a ritual of great importance and will require your assistance.\n\nI will meet you there, so please come with haste.", objectives = "" }
WordHunterWoW_QuestEN[40644] = { title = "The Dreamway", description = "The preparations for the ritual are now complete.\n\nCome with me, {name}, I will guide you to the ceremony.", objectives = "" }
WordHunterWoW_QuestEN[40645] = { title = "To The Dreamgrove", description = "The portal to the Dreamway is open and it is here where our paths must part. The Moonglade remains vulnerable to the attacks of the Burning Legion and I must ensure it is well defended.\n\nI'm entrusting you with the mission to Val'sharah, {name}. Archdruid Greathoof is the leader of the druids there. He is wise in the old ways and will provide us invaluable assistance.\n\nThe Dream can be dangerous so I will send Keeper Remulos to guide you. Meet with him upon the other side.", objectives = "" }
WordHunterWoW_QuestEN[40646] = { title = "Weapons of Legend", description = "I agree with Keeper Remulos. To confront and defeat the Legion, we will need weapons of legendary power.\n\nAmong the history of our kind, there have been four weapons of renown.\n\nTell me, which weapon would you pursue first?", objectives = "" }
WordHunterWoW_QuestEN[40647] = { title = "When Dreams Become Nightmares", description = "Now that we have Ursol's blessing, we can safely pass the magical wards and reach the claws' resting place!\n\nNow, we must pass into the Dream. Lay down before the Shrine of Ursol and drink of the moonwater you brought earlier and your spirit will drift off into the dream.\n\nBe careful, the Dream can be a dangerous place.", objectives = "" }
WordHunterWoW_QuestEN[40649] = { title = "Meet with Mylune", description = "It would seem we are fortuitous that you seek G'Hanir this day, {name} - the dryad Mylune arrived not long ago from the sacred shrine where the staff has been guarded for many centuries.\n\nFew are privy to its hidden location within the roots of Shaladrassil, but you have certainly earned that right.\n\nSpeak to Mylune when you are ready to depart - I saw her last just east of here up the hill.", objectives = "" }
WordHunterWoW_QuestEN[40650] = { title = "Champion: Zen'tabra", description = "", objectives = "" }
WordHunterWoW_QuestEN[40652] = { title = "Word on the Winds", description = "It is time that we turn our attention to matters in the Broken Isles.\n\nSkylord Omnuron has gathered information on events from all over the Isles. If we are presented with any opportunity to strike against the Legion he will know of it.\n\nGo and see if he has anything available.", objectives = "" }
WordHunterWoW_QuestEN[40653] = { title = "Making Trails", description = "The Burning Legion threatens the life of Azeroth, but the nightmare threatens its very soul. We must remove both threats if our world is to survive.\n\nThis map will allow us to track the developments all across the Broken Isles and respond to threats as they arise. Our forces are limited for now, so we should focus our efforts where they will be the most effective.\n\nOnce you've taken a look, you should choose where we shall begin.", objectives = "" }
WordHunterWoW_QuestEN[40654] = { title = "Druids of the Claw", description = "A new ally has joined our ranks. His name is Yaris Darkclaw, a skilled trainer among the Druids of the Claw.\n\nGo speak to him now.", objectives = "" }
WordHunterWoW_QuestEN[40656] = { title = "Cutting the Crystal Flow", description = "I have never known sea giants to befriend anyone, especially the naga. They respond only to one thing. Treasure.\n\nGold, gems, anything that shines or sparkles...\n\nWhen I was returning to Jandvik, I noticed a group of the Sashj'tar harvesting crystals from the trench. I would wager that they are using those crystals to entice the sea giants.\n\nDestroy those crystals and we can halt their payments.", objectives = "" }
WordHunterWoW_QuestEN[40657] = { title = "The Road to Fel", description = "An early step to understanding how magic works is to understand and study materials made using that magic. That was how I made my breakthrough on warlock soul crystals, after all. \n\nThe wyrmtongue minions in this pit hammer plates into their structures for support and maintenance. Those will be a good starting point. Fetch me some, my faithful assistant!", objectives = "" }
WordHunterWoW_QuestEN[40659] = { title = "Seeing Stars", description = "You think those naga are good sport, little rabbit?\n\n<Stokalfr chuckles.>\n\nI would savor the chance to do battle with one of those barnacle-crusted behemoths.\n\nIf you want to impress me, bring me the stars from their heads. I might consider you a true {class} then.", objectives = "" }
WordHunterWoW_QuestEN[40660] = { title = "Away From Prying Eyes", description = "Magni Bronzebeard, legendary dwarven king of Ironforge, forged the Ashbringer in the days following the Second War.\n\nHe was only recently released from his crystal prison in the depths of the city, and he...\n\n<Sister Elda lowers her voice.>\n\nHe wants to meet with ye away from the public eye in the hills below Ironforge, {class}t.\n\nHe believes he can reforge the blade into something even more incredible.", objectives = "" }
WordHunterWoW_QuestEN[40661] = { title = "Protect the Home Front", description = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.\n\nWe must seek them out and stop them, everywhere their darkness touches.\n\nWe've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map.\n\nMake them suffer, {name}!", objectives = "" }
WordHunterWoW_QuestEN[40665] = { title = "Away From Prying Eyes", description = "King Magni Bronzebeard of Ironforge forged the Ashbringer in the days following the Second War.\n\nHe was only recently released from his crystal prison in the depths of the city, and he...\n\n<Sister Elda lowers her voice.>\n\nHe wants to meet with ye, {class}t. He believes he can reforge the Ashbringer into something even more powerful.\n\nHe wants to meet in the hills below the city - it's not safe for ye in Ironforge proper, especially in a time of war.", objectives = "" }
WordHunterWoW_QuestEN[40668] = { title = "Eye of Azshara: The Heart of Zin-Azshari", description = "The naga in the Eye of Azshara summon terrible storms that ravage the coastline of Azsuna - storms far beyond the abilities of even their best sirens.\n\nIt can only be the Heart of Zin-Azshari.\n\nPrior to the Sundering, Azshara's chosen used the Heart to greatly magnify their power - it is said to have been key in their dominance of the Well of Eternity.\n\nIf you can journey to their domain and retrieve it, {name}, we will put its power to far better use than those foul creatures.", objectives = "" }
WordHunterWoW_QuestEN[40670] = { title = "Shattering the Sashj'tar", description = "The Tidemistress has slunk back into the cracks of the ruins and is shielding herself with her most vile serpents.\n\n<Toryl hands you a scepter>\n\nI would never normally hand this over to a stranger, much less a {race}, but you have proven yourself capable at slaying these serpents. It will help you.\n\nBreak it or lose it and I will have your head.", objectives = "" }
WordHunterWoW_QuestEN[40672] = { title = "Neltharion's Lair: Presentation is Key", description = "Odyn will demand a feast worthy of the ancient trials you must complete; a feast's merit begins not at the great beasts piled upon it, but at the dish used to serve it.\n\nDeep beneath Highmountain lies the former lair of Neltharion - you may know the infernal drake better as Deathwing. You will find remnants of the adamantium plating used to hold his molten skin together in the deepest recesses of his lair.\n\nThey will form a fine dish for the feast.", objectives = "" }
WordHunterWoW_QuestEN[40673] = { title = "Lost Knowledge", description = "We are indeed familiar with the Nightborne's magic, but we were never allowed access to the Heart. It was a right reserved only for the Queen's favored.\n\nHowever, we can still learn how to properly tap its magic.\n\nThousands of years ago, a Nightborne scholar studied the Heart and documented his findings in great detail. He was executed and the scroll of his writings banned, but the Nightfallen secreted it away in their escape.\n\nIf you obtain the scroll, we can help you.", objectives = "" }
WordHunterWoW_QuestEN[40674] = { title = "Jars for Jandvik", description = "Last time we met, {race}, I was in a cage. You risked your life once before for my kin. Are you willing to aid me once again?\n\nThe serpents' attack has left many of us wounded. I require mending waters to perform my healing rituals.\n\nI have seen the serpents use this water. Return any that you find to me.", objectives = "" }
WordHunterWoW_QuestEN[40675] = { title = "The Arcway: Rite of the Captain", description = "Only a captain of the Guard may receive the power of our order - our ancient laws forbid otherwise.\n\nYou must complete the rite of the captain.\n\nTraditionally, aspirants patrol the Arcway for three weeks without rest, the vast labyrinth putting their skills as a Guard to the test. Our laws must still be honored, but I believe there another way you may prove yourself.\n\nElisandre's advisor, Vandros, has recently descended into the Arcway's depths. Kill him, and take his Eon Winder.", objectives = "" }
WordHunterWoW_QuestEN[40676] = { title = "You Must Make Haste", description = "I suggest that you set off immediately, {name}. You have been here for far too long - the Legion's assassins could close in at any moment to make an attempt on your life.\n\nDo take caution when using the heart - even with the bindings to aid you the power within is dangerous.", objectives = "" }
WordHunterWoW_QuestEN[40677] = { title = "Power Overwhelming", description = "According to your scroll, in order to harness the full power of the heart we must travel to the the very plane of storms - the Throne of the Four Winds.\n\nI was hoping to use the Great Forge, but no matter - we'll make our own there!\n\nI've borrowed a couple of Ironforge's gryphons to get us to the throne - I'm sure nobody will even notice they're gone.\n\nLet me know when you're ready to set off.", objectives = "" }
WordHunterWoW_QuestEN[40678] = { title = "Twisted Power", description = "It is time we put our work to the test by infusing the most potent source of power I know of - fel magic.\n\nRarely, the Legion's minions will carry fragments of the greater portal stones used to usher in their eredar masters. If you gather enough to form a complete stone, you can use it in Faronaar to call forth the eredar lord Vizuul the Twisted at the Altar of End Times.\n\nThe bindings Vizuul wears to augment his power should push the Heart to its very limit.", objectives = "" }
WordHunterWoW_QuestEN[40679] = { title = "Shock and Awe", description = "Our work here is done, {name}.\n\n<King Magni places his hand on your shoulder.>\n\nFrom one leader to another, thank ye. Thank ye for putting yer life on the line, and for giving this old dwarf one last adventure.\n\nIt's time we go our separate ways - we've both got good people depending on us.", objectives = "" }
WordHunterWoW_QuestEN[40682] = { title = "Rampant Rabbits", description = "There are rabbits even smaller than you around here, {race}. The rabbits that bound around Jandvik are a key ingredient to my favorite stew.\n\nThey are also as fast as a lightning bolt.\n\nProve how swift you are by grabbing a few of them. I might even share my stew with you.", objectives = "" }
WordHunterWoW_QuestEN[40683] = { title = "Discovery Requires Experimentation", description = "I can sense residues of magic all over you. You will be useful.\n\nI must study how the demon bodies can handle the fel energies in such large quantities. I have plenty of flesh to sample, but there must be something...\n\nGo retrieve some spines from the nearby basilisks so that I may analyze their magical residues. No sense in both of us getting our hands dirty, is there?", objectives = "" }
WordHunterWoW_QuestEN[40684] = { title = "The Tome of Blighted Implements", description = "The book you carry is the key to your friends' salvation, and to your absolute power! It holds within information about many relics too dangerous to the Legion to leave unchecked.\n\nRead, friend. And decide which of these artifacts you will use to strike Jagganoth down!", objectives = "" }
WordHunterWoW_QuestEN[40693] = { title = "Eyes of Nashal - Choice UI - Deadly Eye of Prophecy", description = "", objectives = "" }
WordHunterWoW_QuestEN[40694] = { title = "One Small Step for Magic", description = "It is time to embrace the future.\n\nI have mastered every magic known to our kind. I will master this one.\n\nBy applying the principles of arcane magic it is fairly trivial to control the primitive fel energies within the material you have given me. I need to move to live prey next.\n\nLet us start with a small summoning. Defeat the creature for me and watch how a true scholar works!", objectives = "" }
WordHunterWoW_QuestEN[40695] = { title = "Eyes of Nashal - Choice UI - Quick Dawnlight", description = "", objectives = "" }
WordHunterWoW_QuestEN[40696] = { title = "Eyes of Nashal - Choice UI - Masterful Shadowruby", description = "", objectives = "" }
WordHunterWoW_QuestEN[40704] = { title = "Champion: Li Li Stormstout", description = "", objectives = "" }
WordHunterWoW_QuestEN[40705] = { title = "Priestly Matters", description = "Master {name}, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat.\n\nIf you would meet him at Faol's Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.", objectives = "" }
WordHunterWoW_QuestEN[40706] = { title = "A Legend You Can Hold", description = "To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider.\n\nYou must decide which weapon to pursue first. I have the utmost confidence in your decision.", objectives = "" }
WordHunterWoW_QuestEN[40710] = { title = "Blade in Twilight", description = "I have been working with Moira Thaurissan to infiltrate the Twilight's Hammer cult. We've learned of an ancient and powerful Old God relic, a blade used at various points in history to wreak havoc.\n\nMoira's double agent informs us a new leader is rising, and plans to cement his ascension using this weapon in an unholy ritual. You must find him, stop the ritual, and seize the artifact.\n\nWe will meet in Dalaran afterwards.", objectives = "" }
WordHunterWoW_QuestEN[40712] = { title = "The Power Possessed", description = "I was wrong about you, warlock. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.\n\nNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Ulthalesh, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, warlock.", objectives = "" }
WordHunterWoW_QuestEN[40713] = { title = "The Black Tome", description = "I have made a great discovery, {name}.\n\nThere is a powerful warlock in the Soul Engine, in possession of a powerful tome. It contains forbidden secrets to summoning the most powerful of demons.\n\nEven the Legion is afraid to call on these fel lords, but now I possess knowledge beyond theirs.\n\nFetch me the tome and I will never want for magic again.", objectives = "" }
WordHunterWoW_QuestEN[40714] = { title = "The Call To War", description = "<A chilling thought brushes your mind.>\n\nHear me, {name}.\n\nThe Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades.\n\nYour brethren within Dalaran have begun to gather at Krasus' Landing. Go, meet with Duke Lankral and all will be explained.", objectives = "" }
WordHunterWoW_QuestEN[40715] = { title = "A Pact of Necessity", description = "We have an unexpected ally in this war, {name}, and we're going to need every advantage we can get to defeat the Burning Legion.\n\nThe Ebon Blade will serve as the Lich King's arm as long as the Scourge is confined to Northrend. In return for our assistance, our ally has offered to assist in obtaining powerful weapons for the strongest of our knights. Weapons powerful enough to end the Legion once and for all!\n\nYou are one of our best, {name}. I want you to decide which weapon you would like to seek out.", objectives = "" }
WordHunterWoW_QuestEN[40716] = { title = "The Sixth", description = "Greetings, warlock. I speak on behalf of the Council of the Black Harvest.\n\nWith the Legion invasion upon us, it is painfully clear that our only hope is to grow stronger. The council plans to tap into the Twisting Nether and call forth more powerful demon allies. The ritual is ready, but we are short one number.\n\nNo doubt you have heard of the fate that befell Kanrethad Ebonlocke.\n\nYou will be his replacement. Do you accept?", objectives = "" }
WordHunterWoW_QuestEN[40717] = { title = "Calling of the Council", description = "<The arcane anomaly turns to address you, speaking in what is clearly Khadgar's voice.>\n\nThough I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we must be at our full strength to overcome it.\n\nSome will not agree with this position.\n\nPlease join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms. You'll find it over Deadwind Pass, above Karazhan.", objectives = "" }
WordHunterWoW_QuestEN[40718] = { title = "Calling of the Council", description = "<The arcane anomaly addresses you in Khadgar's voice.>\n\nThough I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we require the full might of Azeroth's people to overcome it.\n\nThe Horde must become part of the Kirin Tor once again. Some will not agree with this position.\n\nPlease join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms, above Karazhan.", objectives = "" }
WordHunterWoW_QuestEN[40727] = { title = "All Along the Waterways", description = "I've noticed some wandering eyes, lately.\n\nI am more than happy to continue delivering the goods to Vanthir, but it is getting increasingly dangerous to do so. \n\nThe Duskwatch that walk the bazaar are by far the most observant.\n\nFind and slay the Orbitists so that I may deliver the goods safely.\n\nI will follow behind with the shipment.", objectives = "" }
WordHunterWoW_QuestEN[40729] = { title = "The New Blood", description = "It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[40730] = { title = "Redistribution", description = "I would imagine you thought I would simply have wine to deliver.\n\n<Deline chuckles.>\n\nIf it were that easy, his people would not be starving.\n\n<Her expression becomes serious.>\n\nThese... loyalists, shall we say, enjoy abundance. They dance to the Magistrix's whims and so they have all that they need.\n\nThere is no Arcwine shortage. The Magistrix created one to keep us in line.\n\nThey will not miss a few bottles. They have plenty.\n\nSearch the square and bring as much as you can carry back.", objectives = "" }
WordHunterWoW_QuestEN[40731] = { title = "The Heart of the Dreadscar", description = "Friend has the artifact! Now Jagganoth does not stand a chance!\n\nQuickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth's vengeance.\n\nIf you take the heart of the overlord, his army will be yours to command!", objectives = "" }
WordHunterWoW_QuestEN[40740] = { title = "The Dead and the Damned", description = "<A powerful mind again touches your thoughts.>\n\nGorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned.\n\nA group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed.\n\nYou will not be alone in this, I've sent Baron Sliver ahead to assist you.\n\nGo, obtain the Maw of the Damned and ensure that Gorelix is no more.", objectives = "" }
WordHunterWoW_QuestEN[40741] = { title = "In Need of Information", description = "Now that the Commander is dead, we need to find out what they know.\n\nSylessa overheard a conversation suggesting a meeting is about to take place. An informant and one of Commander Elvire's Sentries will exchange very valuable information.\n\nI need you to follow whoever the informant is, and find out what that meeting is about.\n\nYou must not be seen. If you are, the meeting may not take place at all.\n\nNow is the time for discretion, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40742] = { title = "The Elusive Three", description = "Bad news.\n\nWord has started to circulate about a possible infiltration into the city. That was fast, even for our standards.\n\nWe're going to do some damage control. I need you to find three of my best assassins. Start by seeking Cyrille- she resides in the Docks District, acting the part of a Steward.\n\nShe will guide you to the others, and ultimately your target. Commander Elvire.\n\nThat will buy you and Thalyssra some time.", objectives = "" }
WordHunterWoW_QuestEN[40744] = { title = "An Ancient Recipe", description = "Suramar is... was... an intellectual's dream.\n\nWe studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in?\n\nLook at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, {race}. Perhaps you would help me procure them?\n\nI am going to need some harpy talons. Crushed into a powder, they will be a potent reagent.", objectives = "" }
WordHunterWoW_QuestEN[40745] = { title = "Shift Change", description = "This is as good a chance as we are going to get to rescue Verene's daughter.\n\nHere is how this is going to work. \n\nYou are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in.\n\n<Silgryn marks a spot on your map.>\n\nYou will know the guard by their bright red armor.\n\nFollow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination.\n\nThe child's name is Korine. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[40746] = { title = "One of the People", description = "It is time for you to enter the city proper, {name}.\n\nI am sending you to my loyal friend Vanthir. I do hope you remember him- I can guarantee that he remembers you.\n\nI will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long.\n\nFarewell for now.", objectives = "" }
WordHunterWoW_QuestEN[40747] = { title = "The Delicate Art of Telemancy", description = "I hadn't the time to gather my instruments before fleeing the palace. I came here to salvage some equipment.\n\nThis old workshop is actually several rooms connected by teleporter pads.\n\nElisande's goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles.\n\nYou go in. I'll monitor your position and ensure the teleporters work normally for you.\n\nFind these two parts and bring them back!", objectives = "" }
WordHunterWoW_QuestEN[40748] = { title = "Network Security", description = "We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk.\n\n<The inactive attunement device near Oculeth hums to life.>\n\nThis will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!", objectives = "" }
WordHunterWoW_QuestEN[40749] = { title = "A Token of Remembrance", description = "The flower rests peacefully in your hand, glowing softly.\n\nWhile it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here.\n\nPerhaps laying down some flowers on the remaining graves will ease the gloom.", objectives = "" }
WordHunterWoW_QuestEN[40753] = { title = "Blingtron 6000", description = "", objectives = "" }
WordHunterWoW_QuestEN[40755] = { title = "Hiding in the Stacks", description = "Magni's information was enlightening. It should prove handy to have a friend who has the ear of a titan.\n\nIt's time to head into Karazhan. Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard.\n\nI'll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.", objectives = "" }
WordHunterWoW_QuestEN[40760] = { title = "Emissary", description = "As if things weren't unsettled enough, guests have arrived... the Illidari.\n\nThese demon hunters have been imprisoned since their master's fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed.\n\nTheir delegation's leader, Allari \"the Souleater,\" claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now.\n\nYou will speak with her at once. Find out whether this threat is credible.", objectives = "" }
WordHunterWoW_QuestEN[40761] = { title = "Whispers from Oronaar", description = "Ethereals, the Void, a Dark Naaru... I feel they are all connected.\n\nI explored the ruins below while you and Velen were seeking the Crown. There are survivors, {name}.\n\nBroken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own.\n\nIf the Void is to blame, we will need to start our investigation there.\n\nI will conduct my own search in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[40762] = { title = "Zealot's Dues", description = "Commander Domitille represents the very essence of the Nightborne's corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard.\n\nTake her helm to Lothrius as proof of her demise.", objectives = "" }
WordHunterWoW_QuestEN[40763] = { title = "Casual Redistribution", description = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. \n\nI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.\n\nWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.\n\nBring me as much Arcwine as you can carry. I will see that it gets to the right people.", objectives = "" }
WordHunterWoW_QuestEN[40779] = { title = "We Need Even More Power!", description = "Good new, {race}! I have located another power orb.\n\nI last saw it down by the Nightborne encampment to the southwest. I had to get out of there before their patrols saw me, but it should be no trouble for you, now should it?", objectives = "" }
WordHunterWoW_QuestEN[40783] = { title = "The Scythe of Elune", description = "I have received word that Tyrande herself has authorized the release of a great artifact, the Scythe of Elune, to aid our cause. Valorn Stillbough has agreed to give up the weapon, which he has kept as part of an investigation into the cursed worgen of Duskwood.\n\nI believe that you, champion, will be our best hope at wielding its power without succumbing to the animal rage that ebbs within. You must go to Duskwood, and take up the scythe against our foes!", objectives = "" }
WordHunterWoW_QuestEN[40784] = { title = "Its Rightful Place", description = "Though it goes against my better judgment, it is Tyrande's wish that the Scythe of Elune be brandished once more against the new Legion threat. It is a small comfort to see it wielded by a keeper of the balance, such as yourself.\n\nKnow that the last time the scythe was wielded, it resulted in great calamity. You must be vigilant to contain the bestial wrath that ebbs within. \n\nWith those words in your heart, take the scythe and bring its fury against our foes. May the light of Elune protect you.", objectives = "" }
WordHunterWoW_QuestEN[40785] = { title = "A Foe of the Dark", description = "I cannot believe the Dark Riders found us here. Long have they hunted the scythe to sate their lust for the artifacts of Azeroth. We thought we would be protected within the grove...\n\nAnd now, Valorn is gone...\n\nYou must become the hunter, {name}. Seek the Dark Riders and recover the scythe. We last encountered them near Manor Mistmantle in Duskwood. Start your search there.\n\nAnd {name}... bring justice to Valorn. The rider must pay.", objectives = "" }
WordHunterWoW_QuestEN[40786] = { title = "The Smoldering Ember", description = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear conversation taking place in Orgrimmar and the familiar sight of circle portals bubbles to the top.", objectives = "" }
WordHunterWoW_QuestEN[40787] = { title = "The Smoldering Ember", description = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear the hustle and bustle of Stormwind and the familiar sight of circle portals bubbles to the top.", objectives = "" }
WordHunterWoW_QuestEN[40793] = { title = "A Matter of Planning", description = "Your weapon is stronger than ever, now is the perfect time to put it to use and take our fight to the Legion.\n\nMaster Hsu has set up a command table by the training grounds, and has collected reports from our friends and allies around all of Azeroth.\n\nWhen you are ready, Grandmaster, he should have an update prepared for you.", objectives = "" }
WordHunterWoW_QuestEN[40794] = { title = "Fate of the Queen's Reprisal", description = "<This is the kind of intelligence that should be shared. Perhaps someone at the Greyfang Enclave on Dalaran will know what to do with it.>", objectives = "" }
WordHunterWoW_QuestEN[40795] = { title = "The Fight Begins", description = "The Burning Legion has left a trail of ruin all across the face of Azeroth. We must strike at their bases within the Broken Isles if we are to have any hope of ending this war.\n\nI've put together a map of the isles and a list of tasks that we will need to have done there.\n\nOnce you've had a chance to peruse the map, you should choose where we will begin our assault.", objectives = "" }
WordHunterWoW_QuestEN[40796] = { title = "Lingering on the Edge", description = "I h-have made... mistakes...\n\n<Absolon draws in a rasping breath.>\n\nI want to make it right... I want to live! But the madness... the WITHERING..\n\nI am... fading.\n\n<Absolon stares at you helplessly.>", objectives = "" }
WordHunterWoW_QuestEN[40798] = { title = "Cling to Hope", description = "Your kindness has inspired me, friend.\n\nI thought I would wander forever among the empty husks of the Withered, but Thalyssra invited me in.\n\nI have chosen to remain here with my people and together we will take back Suramar.\n\nFor now I have but one request.\n\nTake this letter to my wife. She should know that I still live, among other things.\n\nGive her the hope that you gave me.", objectives = "" }
WordHunterWoW_QuestEN[40801] = { title = "Journey to Azsuna", description = "{class}t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity.\n\nThe Kirin Tor have also constructed a permanent waygate to enable speedy movement between here and Dalaran - you can find it near the path down in the village should you wish to use it.", objectives = "" }
WordHunterWoW_QuestEN[40814] = { title = "The Power to Survive", description = "We have long relied on Lord Illidan to vanquish the Legion's strongest warriors - many have expressed concern over our efforts without him.\n\nThankfully, their concerns may not matter much longer.\n\nWe know of two pairs of blades rumored to be more powerful than even Lord Illidan's that are not yet out of reach.\n\nIf we act quickly we should be able to hunt down one without forsaking our watch over the Legion's movements.\n\nI must defer judgment on which is most worthy of our time to you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40815] = { title = "From Within", description = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "" }
WordHunterWoW_QuestEN[40816] = { title = "The Power to Survive", description = "Illidan and I may have disagreed, but he was unarguably powerful. He was pivotal in vanquishing some of the Legion's most powerful soldiers.\n\nHowever, that may not matter much longer.\n\nThere are two pairs of blades rumored to be more powerful than even Illidan's that may still be within reach.\n\nRegrettably, our numbers are too few to hunt both while maintaining our vigil over the Legion. I fear our window of opportunity is waning quickly.\n\nAs the ranking Illidari, that decision falls to you.", objectives = "" }
WordHunterWoW_QuestEN[40819] = { title = "Making Arrangements", description = "Do you recall Varedis, {name}? He was once our lead trainer, but fell with the Black Temple years ago.\n\n...or so we thought.\n\nKor'vas spotted the traitor alongside the Legion... wielding glaives imbued with power unlike anything she'd ever seen.\n\nThe Kirin Tor have an eredar lord locked away in the Violet Hold that will know where Varedis' stronghold lies. The prison warden has agreed to consider granting us access to the fiend.\n\nTime to do some convincing.", objectives = "" }
WordHunterWoW_QuestEN[40823] = { title = "Rebuilding the Council", description = "It seems that friend has caught the attention of Mephistroth. This is very bad news, as the dreadlord will surely wish to seek revenge for losing his general.\n\nFriend will need more than the Dreadscar to stand against him, you will need powerful warlocks such as those who were captured.\n\nCalydus thinks the orc still lies in the pit where you were chained. Friend must revive him, and rebuild the council!", objectives = "" }
WordHunterWoW_QuestEN[40824] = { title = "The Path of the Dreadscar", description = "It would seem that where the council has failed, you have found untold success. These Dreadscar should prove powerful allies, but they may not be enough.\n\nFor now, we must look to rebuild. I will send agents out to locate the whereabouts of the captured council members, as well as any other warlocks who may be able to aid the cause.\n\nMeet me at the scrying pool, and we will plan our action from there.", objectives = "" }
WordHunterWoW_QuestEN[40830] = { title = "Close Enough", description = "<Oculeth's eyes have dulled. His voice trembles.>\n\nAre we... are we close?\n\nSo hungry...", objectives = "" }
WordHunterWoW_QuestEN[40832] = { title = "Call of The Uncrowned", description = "My masters gave me strict instructions to deliver this letter to you as quickly as possible.\n\nIts contents are for you and you alone.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[40834] = { title = "Following the Curse", description = "In my previous confrontation with your foe, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they once were.\n\nCome, we must go to Ariden's Camp in Deadwind Pass. I can explain its significance along the way.", objectives = "" }
WordHunterWoW_QuestEN[40835] = { title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", objectives = "" }
WordHunterWoW_QuestEN[40837] = { title = "The Deadwind Hunt", description = "The Nightbane! If they are in Deadwind Pass, then they may be seeking the scythe as well.\n\nLet's split up and try to track them down. We'll see where their trail leads...", objectives = "" }
WordHunterWoW_QuestEN[40838] = { title = "The Dark Riders", description = "This sewer grate leads to the catacombs underneath Karazhan. I've never paid it much attention, but it seems to be where the Nightbane are being drawn to.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "" }
WordHunterWoW_QuestEN[40839] = { title = "The Final Shadow", description = "You walk in the halls of the Uncrowned. We are the slayers of kings, the downfall of empires, the unseen blades that write the true history of this world.\n\nSeated before you are the Shadows, the council which aims the blades of the Uncrowned wherever our will demands.\n\nWe have brought you here today with an offer. Take your seat as the final Shadow and help us lead the Uncrowned.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[40840] = { title = "A Worthy Blade", description = "For quite some time, we've been looking for someone who can operate outside these halls.\n\n{name}, you are the answer to that search. You will be the blade in the dark that vanquishes our foes.\n\nIn order to do so, you require weapons capable of striking down the Legion's best.\n\nGreymane, Tethys, and Valeera each have devised plans to obtain weapons worthy of the tasks to come. I suggest you hear each out before proceeding.", objectives = "" }
WordHunterWoW_QuestEN[40847] = { title = "A Friendly Accord", description = "I'd like to offer ya an accord.\n\nThe Dread Admiral Eliza wields a pair of cursed blades that have made her the scourge of the south seas. She also stole one of me best ships - the Horizon's Edge - and has it anchored off the shore of Azsuna as we speak. \n\nIf you help me take back me ship, then her cursed blades are yours.\n\nNow, assuming that sounds agreeable, meet me aboard the Crimson Veil. We have her docked right in Booty Bay - not a cheap arrangement.", objectives = "" }
WordHunterWoW_QuestEN[40849] = { title = "The Dreadblades", description = "I can promise ya a safe journey to Eliza's position, but once we're there... well, we both know there be no guarantees.\n\nThe plan is simple. We'll take the Crimson Veil as close as we can get her without being seen and disembark from there.\n\nOnce we're ashore, we'll board the Horizon's Edge, bribe her mutinous crew to hand it over, and hunt down Eliza and her legendary blades wherever she may be.\n\nJust say the word when yer ready.", objectives = "" }
WordHunterWoW_QuestEN[40854] = { title = "Endless Possibilities", description = "Say, since you're down here, I have something that you might be interested in.\n\n<Filgo points over to a husk lying in the junk behind him.>\n\nI found that thingy down in Azsuna, just lying on the beach. I'm sure with a little tinkering, an engineer like you could probably get it up and running in no time.\n\nMight even be useful against the Legion. Kind of like fighting fel with fel, heh!", objectives = "" }
WordHunterWoW_QuestEN[40855] = { title = "Our Man in Azsuna", description = "Yikes! OK. This thing is missing a LOT of parts.\n\nWhy don't you go hunt down some new gears or whatever while I do what I can to its existing frame?\n\nA colleague of ours, down in Azsuna, may be able to help out here. His name's Flintlocke.\n\nFetching parts should keep him out of trouble. Just don't let him BUILD anything.", objectives = "" }
WordHunterWoW_QuestEN[40856] = { title = "It'll Cost You", description = "If yeh need demon parts, oh aye, this place is right teeming with them fel buggers.\n\nYer bound ta find what'yer lookin' fer probably near them portals they've got jus' sou'east of 'ere.", objectives = "" }
WordHunterWoW_QuestEN[40857] = { title = "Bits and Pieces", description = "So many artifacts to catalogue, and never enough time.\n\nGood to see you again, {name}. Brann Bronzebeard and the Explorers' League are in Stormheim right now and could use your help tracking down an ancient titan relic.\n\nBrann can fill you in on the details when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[40858] = { title = "The Missing Pieces", description = "Yeh seem ta 'ave everything yeh need. Head back to Didi now wit' yer supplies and giv'er a slap on tha back from me!", objectives = "" }
WordHunterWoW_QuestEN[40859] = { title = "The Latest Fashion: Headguns!", description = "So Grapplehammer's got hisself a whole lotta extra guns, right? Glorious! An'it got me ta thinkin', \"What if we put 'em on our heads?\"\n\nHear me out!\n\nSee, yer hands are already busy with yer current weapons, but what's yer head doin'? It's just sittin' there LOOKIN' at stuff. That's me plan. Weaponize yer head!\n\nYou, me lucky lad, can test it out. Strap this on. Now, go blast some fel-tainted critters down below. Blammo!", objectives = "" }
WordHunterWoW_QuestEN[40860] = { title = "Resupplying the Line", description = "{name}, I need you to make a delivery for me.\n\nFlintlocke's sent word from Val'sharah stating that they're out of bullets.\n\nI sent him down there with enough ammo to cut the planet in half, but Flintlocke goes through ammunition the way you or I go through... air. Go help him out!", objectives = "" }
WordHunterWoW_QuestEN[40861] = { title = "In My Sights", description = "I used up all me bullets on a wee invention of mine. I call it: Tha Deployable Bullet Dispenser!\n\nOh aye. It shoots in-der-scriminantly wit'out all that messy and time-consumin' \"aiming\" or \"thinkin'\" that us people-folk are wont ta do.\n\nWe had deployed quite a few of 'em east o' here when this swarm of plants came a'thrashin from tha trees.\n\nI didn't 'ave time ta go back an' get me turrets. Would ye mind gettin' them back fer me? Or at least, what's left of 'em?", objectives = "" }
WordHunterWoW_QuestEN[40862] = { title = "All Charged Up", description = "If yer gonna wander inta these woods, ye'll be wantin' somethin' with some punch. These plants are a might grabby.\n\nI've got me special explosive charges here that should send those fertilizer mutations back to the dirt.\n\nTake 'em with yeh and give them viney beasties a what-fer!", objectives = "" }
WordHunterWoW_QuestEN[40863] = { title = "Always the Last Thing", description = "Well, I've worked out all the kinks. Added a few nuts and bolts, and fitted a new housing for the power core.\n\nProblem is, none of the batteries I have here seem to work. I think we're gonna have to fashion somethin' new together.\n\nI'm gonna need your help, {name}. Let's start by trying a charged gem from the jewelcrafting shop down the way.", objectives = "" }
WordHunterWoW_QuestEN[40864] = { title = "Modular Modifications", description = "Now that we got this baby running, let's give it some cool abilities.\n\nWhen I was fixing Reaves up, I installed a module port onto his motherboard. This will allow us to upload anything we want.\n\nI'll teach you one of my module designs and you install it on Reaves.", objectives = "" }
WordHunterWoW_QuestEN[40865] = { title = "It's Not Rocket Science", description = "{name}, I need you to help me track down Flintlocke again.\n\nI sent him to Stormheim to gather some materials for an invention of mine and he hasn't been back for days. I'm not worried about Flintlocke, but I DO fear for Stormheim.\n\nSee if you can find him!", objectives = "" }
WordHunterWoW_QuestEN[40866] = { title = "The Shell, You Say?", description = "I know ol' Hobart sent me down 'ere to acquire 'is precious murloc glass thingies, but I have designs of me own!\n\nI've seen those murlocs carrying interesting lookin' shells that would go perfectly into me music box I've been workin on.\n\nYa lead the charge an'a I'll be right behind ya.", objectives = "" }
WordHunterWoW_QuestEN[40867] = { title = "Bubble Baubles", description = "Ol' Hobart wanted me ta gather up these shiny, glass trinkets the murlocs carry around, but those bloody buggers ain't willin' to jes' hand 'em over!\n\nI tried the dip-ler-matic approach, but I don't speak murloc, so I just end up shootin' 'em.\n\nMaybe you might have better luck gettin' them baubles.", objectives = "" }
WordHunterWoW_QuestEN[40868] = { title = "Wibbly-Wobbly, Timey-Wimey", description = "I gotta finish up 'ere, so why don'tcha take those trinkets back to Hobart fer me.\n\n'Sides, I'ma thinkin' he likes ya more than me.", objectives = "" }
WordHunterWoW_QuestEN[40869] = { title = "Fire and Forget", description = "They say, \"When life gives you lemons, make lemonade.\" Well, life gave me a butt-load of guns.\n\nSo I've been figuring out ways to turn these guns into useful tools.\n\nMy latest modification is a gun that shoots bandages! Imagine it, you're on the battlefield, you see your ally go down, you pull out your bandage gun, shoot him with it and bam, he's back in the fight!\n\nI just need you to test it first and make sure it's safe.", objectives = "" }
WordHunterWoW_QuestEN[40870] = { title = "Here Comes the BOOM!", description = "{name}, they stole all my fireworks, the little scamps.\n\nYou didn't see them? I was just on the verge of creating a new module for Reaves when these kids came in here and ran off with my fireworks.\n\nI need them back if I'm going to finish what I'm working on. Can you go get them back for me?", objectives = "" }
WordHunterWoW_QuestEN[40871] = { title = "Locke and Load", description = "Flintlocke's been looking for you, {name}. I think he needs your help again.\n\nI sent him out to test out a couple of new inventions of mine back down in Azsuna. Look for him on the shoreline west of Oceanus Cove!", objectives = "" }
WordHunterWoW_QuestEN[40872] = { title = "Going Out With a Bang", description = "While I was, eh, testin' out this new flight pack fer Hobart, it sorta exploded an' sent me flyin' back over 'ere.\n\nYou can see all the pieces out there in tha water.\n\nNow, I've got these boots 'ere that Hobart gave me to test out too, but they're not quite me size.\n\nI figure we could kill two birds with one stone and 'ave ye test 'em out while pickin' up the broken bits of the pack.\n\nMind tha sharks while yer out there.", objectives = "" }
WordHunterWoW_QuestEN[40873] = { title = "Keep Yer Powder Dry", description = "So while we've got all tha parts for tha pack again, I'm afraid I'm all outta gunpowder.\n\nThis is the worst thing ta ever happen ta me.\n\nBut there's hope. Just o'er to tha north are caves filled with crashed ships. Chances are them sea giants crashed one or two ships with cannons. And cannons mean gunpowder, sweet gunpowder.\n\nSearch their caves fer sum powder an' bring it on back.", objectives = "" }
WordHunterWoW_QuestEN[40874] = { title = "I'd Do It Myself, But...", description = "If yer headed over ta tha sea giant caves, do me a favor give those slimy naga a right bludgerin'.\n\nThey done run oft with me rogue friend an' I figure some revenge is in order.\n\nI'd do it meself but ol' Hobart would give me wut-fer if I abandoned his stuff.", objectives = "" }
WordHunterWoW_QuestEN[40875] = { title = "Going to Waste", description = "Me wee rogue friend Lowping were\ngnome-napped by them dirty naga when we got 'ere. He's gone! They drug him right oft toward tha cove!\n\nBut 'ere's tha real issue. He 'ad a schematic on 'im fer one of me greatest inventions.\n\nAnd by \"on 'im,\" I mean I tattooed it to tha top o' his head. FOR SAFETY!\n\nWhen ye find 'im, jes shave 'is head and make a quick copy o' tha design.", objectives = "" }
WordHunterWoW_QuestEN[40876] = { title = "Locke, Stock and Barrel", description = "Well that jes' about wraps up me work 'ere. I'll start packin up an'ead back ta Dalaran.\n\nIf yeh wouldn't mind, could yeh tell Hobart 'ow things went down 'ere? Maybe leave out tha bits with tha explodin', tha drownin', an' tha gettin captured an' what not.\n\nYer a proper friend, {name}!", objectives = "" }
WordHunterWoW_QuestEN[40877] = { title = "Halls of Valor: Trigger Happy", description = "In order to complete my latest invention, I need a special relic known as the Runestone of Vitality.\n\nOdyn, king of the Halls of Valor is known to use it to breathe life into his constructs.\n\nWhat I'm asking is no easy task, but I need to take the runestone from Odyn and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[40878] = { title = "Assault on Violet Hold: Cheating Death", description = "Hobart was showing me a copy of a design you found, and it got me to thinking of a new module for Reaves.\n\nUnfortunately I didn't have the materials required to test it.\n\nCould you make me a couple Failure Detection Pylons?\n\nI'll also need a plasmatic laser bolt. You should be able to find one in the Violet Hold.", objectives = "" }
WordHunterWoW_QuestEN[40879] = { title = "It's On With Automatons", description = "", objectives = "" }
WordHunterWoW_QuestEN[40880] = { title = "Short Circuit", description = "While I've got you here, I was wondering if you could track something down for me.\n\nI'm sure you're familiar with a Blingtron, yes? Well, I started askin' around, and it seems no one really knows where the design for it came from. One rumor does pop up more than others, though:\n\nArea 52.\n\nInterested in a field trip?", objectives = "" }
WordHunterWoW_QuestEN[40881] = { title = "Oil Rags to Riches", description = "Didi will be very interested in reading the journal you found as well as examining the circuit design.\n\nYou should return to her as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[40882] = { title = "Court of Stars: Revamping the Recoil", description = "{name}, you'll be very excited to hear that I've been working on a newer, better version of those goggles that Flintlocke rigged up.\n\nThe ones I've designed have double the power, but unfortunately they also have double the recoil. I'm afraid if you use them, they'll break your neck.\n\nBut I found a solution. Deep inside Suramar City lies a magical mechanism that will reduce the recoil to practically nothing.\n\nRecover that mechanism for me and we're in business!", objectives = "" }
WordHunterWoW_QuestEN[40883] = { title = "Fate of the Guard", description = "<Thalrenus looks you over.>\n\nYou are not one of them.\n\nThe Nightborne came to our gates hours after the shield over Suramar fell. We thought them friends, despite our long separation.\n\nWe were wrong.\n\nThey poured into our stronghold and began the slaughter. We were unprepared. Though we fought, we were beaten.\n\nThe keep is lost. Our leaders have perished and their corpses lay in the streets.\n\nFind them, give them their final rites.\n\nWhile you search, look for survivors. Help them if you can.", objectives = "" }
WordHunterWoW_QuestEN[40890] = { title = "The Tears of Elune", description = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.", objectives = "" }
WordHunterWoW_QuestEN[40898] = { title = "Fresh Meat", description = "This crater is infested with felfire basilisks.\n\nThey may not be the most cunning of creatures, but they are as vile and dangerous as any demon.\n\nHowever, they may yet prove useful to us. Slay the basilisks, but return to me with chunks of their fel-infused flesh.\n\nI have plans to make use of their freshly carved flesh...", objectives = "" }
WordHunterWoW_QuestEN[40900] = { title = "The Burden Borne", description = "Your assistance against the Dark Riders has proven a great service to the Light. Though our beliefs may separate us, I know that we share one goal.\n\nYou have allowed me to fill my purpose in returning these artifacts to their rightful owners, and for this I am thankful. As for the Scythe of Elune, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40901] = { title = "Grimwing the Devourer", description = "You have my thanks for rescuing me from captivity, {class}.\n\nHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.\n\nIf you wish to continue with me, I need proof of your strength.\n\nGrimwing the Devourer is the strongest of the felbats and a suitable test of skill. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.\n\nReturn to me with her head and I will not doubt your ability.", objectives = "" }
WordHunterWoW_QuestEN[40904] = { title = "Shadow of the Defiler", description = "Crimson energy swirls within this disturbing object, which seems to have slightly different contours each time your gaze returns to it.\n\nIts power is utterly foreign, unlike anything you have seen in Draenor or during your battles with the Legion. Perhaps the keepers of Moonglade, back on Azeroth, might have some insight into its nature.", objectives = "" }
WordHunterWoW_QuestEN[40906] = { title = "Serpents from the Deep", description = "Hail, {class}.\n\nMy village of Jandvik has fallen under siege by a group of naga called the Sashj'tar.\n\nNormally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating.\n\nMany powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards.\n\nDo we have an accord?", objectives = "" }
WordHunterWoW_QuestEN[40907] = { title = "Removing Obstacles", description = "{class}! Interested in earning some coin?\n\nThe jarl of Jandvik is missing and two headstrong whelps are vying to take over leadership. I should be the next jarl, not them!\n\nI want you to enter Jandvik and defeat Calder and Eynar in mortal combat.\n\nI would not normally put my trust in an outsider, but this situation requires the aid of someone like you. Jandvik would condemn me if I were caught with their blood on my hands.\n\nMeet me in the center of Jandvik when the deed is done.", objectives = "" }
WordHunterWoW_QuestEN[40908] = { title = "Jarl Come Back Now", description = "You seem to follow my commands well, {name}. Perhaps I can use you again.\n\nJarl Throndyr, the leader of Jandvik, has been missing for some time now. I assume that he has fallen in battle to the invading Sashj'tar naga, but I must know for certain.\n\nFind out what has become of him.\n\nDo this task for me and I can assure you that my vrykul will not harm you.", objectives = "" }
WordHunterWoW_QuestEN[40919] = { title = "Fel Bent for Leather", description = "Ah, my faithful assistant. I have just the task for you.\n\nAs you have seen, fel power permeates living tissue and can easily be coaxed out.\n\nAlso, these damned bats are driving me to my wits' end. There is an opportunity to kill two bats with one blade, it seems. Your blade.\n\nTake this crystal. It should rip those hellions from the sky and into your waiting arms.\n\nYou may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.", objectives = "" }
WordHunterWoW_QuestEN[40927] = { title = "Jandvik's Last Hope", description = "Commander Malt'his was conferring with a sea giant?\n\nWithout your help, this village will surely fall to the combined forces of the Sashj'tar and the sea giants.\n\n<Toryl stands there quietly for a moment.>\n\nMeet me in an underground cave out in Azuregale Bay.\n\nI want to show you something that may turn the tide in this battle.", objectives = "" }
WordHunterWoW_QuestEN[40929] = { title = "Symbols of Power", description = "This demon has information that could lead us to those in charge.\n\nUnfortunately, he is more fearful of his master than he is of us. We need to change his mind about that.\n\nThe most powerful Burning Legion soldiers often carry an emblem of their rank and status within the demon army.\n\nSeek out the stronger demons in Felsoul Hold, slay them, and return to me with their emblems.\n\nWe will show this wyrmtongue servant who it is he should fear...", objectives = "" }
WordHunterWoW_QuestEN[40930] = { title = "Apocalypse", description = "<The Lich King's chill voice fills your mind once again>\n\nThere is an ancient blade, lost in the echoes of time, that has the power to bring my vengeance upon the Legion. \n\nIt is known as Apocalypse.\n\nI've sensed the blade in the possession of the Dark Riders of Deadwind Pass. Their magic conceals them from my sight but they cannot hide from the scourge! They were last seen by my agents near a place called Manor Mistmantle.\n\nGo there, {name}. Defeat the Dark Riders, and claim the blade!", objectives = "" }
WordHunterWoW_QuestEN[40931] = { title = "Following the Curse", description = "Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them.\n\nThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.\n\nCome with me to Ariden's camp. I will explain on the way.", objectives = "" }
WordHunterWoW_QuestEN[40932] = { title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. \n\nIt has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", objectives = "" }
WordHunterWoW_QuestEN[40933] = { title = "A Grisly Task", description = "Wet soil? Shallow graves?\n\nI think the journal is referring to the gravesites off of the lake near Karazhan. Nobody knows who is buried there, but they may be the key to finding the Dark Riders.\n\nYou can... speak to the dead, yes?", objectives = "" }
WordHunterWoW_QuestEN[40934] = { title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "" }
WordHunterWoW_QuestEN[40935] = { title = "The Call of Vengeance", description = "I was wrong about you, death knight. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.\n\nNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Apocalypse, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, death knight.", objectives = "" }
WordHunterWoW_QuestEN[40938] = { title = "The Light and the Void", description = "Alonsus Faol has been a valuable ally, and his instincts about you have proven true. I believe you are uniquely suited to assist in a matter that will bring a great force of good into this world.\n\nI must take you somewhere far from Azeroth to finish a task my people began long ago. Will you aid us?", objectives = "" }
WordHunterWoW_QuestEN[40947] = { title = "Special Delivery", description = "Verene's child has gone missing. I can guess what happened, but I need to be sure.\n\nMost guardsmen use couriers to relay delicate information. In this, magic is strictly the province of high ranking officials.\n\nTake this blade. Do not touch the cutting edge. Use it to silently waylay the couriers and collect any correspondence they carry.\n\nWith any luck, the missives will tell us exactly where to find the girl.\n\nWe guards know everything, after all.\n\n<Silgryn offers you a winning smile.>", objectives = "" }
WordHunterWoW_QuestEN[40949] = { title = "Not Their Last Stand", description = "I've been watching you- you are not with them.\n\n<Ivanel coughs quietly.>\n\nI am not long for this world, but there is one thing I would have you do while you are here.\n\nThe hippogryphs here still fight bitterly to defend their home and their companions in the Moon Guard. They have not accepted that the Guard is no more. \n\nPlease... send them away. Let them know there is nothing left for them to fight for here.", objectives = "" }
WordHunterWoW_QuestEN[40950] = { title = "Honoring Success", description = "All has gone as planned. Your new blades are a testament to that.\n\nWe will demand a great deal of you in the weeks and months to come, as we must. But we would be remiss if we failed to take a moment to celebrate a job well done.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[40952] = { title = "Hunter to Hunter", description = "Now that you wield Thas'dorah, it's time to learn more about the night elf who set you on this journey\n\nI suggest returning to the Hunter's Reach shop where you met my courier. Whoever this Emmarel Shadewarden is, it seems she has some part to play in the war against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[40953] = { title = "On Eagle's Wings", description = "Since ancient times, my order has stood vigil on these Broken Isles, watching for the Legion's return. Only a handful of us remain... but that changes today.\n\nThe artifact you hold is more than a weapon. It is a symbol that will unite hunters of all kingdoms and creeds.\n\nI'm sure you have questions. Meet me at the Trueshot Lodge in Highmountain and see with your own eyes what awaits us. Snowfeather and I will make our own way there.", objectives = "" }
WordHunterWoW_QuestEN[40954] = { title = "The Unseen Path", description = "For a thousand years, the Unseen Path has watched and waited. We remained few in number, quietly acting behind the scenes when Azeroth needed us. Only a select few even knew our group existed.\n\nBut the time for lingering in the shadows is over.\n\nBefore we begin our work, you should hear more about the Unseen Path.", objectives = "" }
WordHunterWoW_QuestEN[40955] = { title = "Oath of Service", description = "Assembled before you are many of our world's greatest archers, rangers, beast masters, and trappers, ready to fight the Legion as one.\n\nIt is time to take your first step in becoming a true leader of hunters.\n\nWe gather at the fire pit and take our oaths of service before the statue of Ohn'ahra. Touch the statue and kneel before it while I recite the oath, and the Unseen Path will be reborn!", objectives = "" }
WordHunterWoW_QuestEN[40956] = { title = "Survey Says...", description = "It is time to establish the first secure connection in our teleportation network.\n\nTake this beacon to the Ruins of Elune'eth above us and survey the area to find a suitable location.\n\nOnce your survey is complete, place the beacon and I will anchor a connection to it from here.", objectives = "" }
WordHunterWoW_QuestEN[40957] = { title = "A Strong Right Hand", description = "", objectives = "" }
WordHunterWoW_QuestEN[40958] = { title = "Tactical Matters", description = "Now that your artifact is ready, it's time to plan your first strike against the Legion.\n\nSpeak to Tactician Tinderfell, our expert on such matters.", objectives = "" }
WordHunterWoW_QuestEN[40959] = { title = "The Campaign Begins", description = "The Legion believes we are still reeling from our loss on the Broken Shore.\n\nLet's prove them wrong.\n\nOur scouts have mapped out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nChoose where to strike first, and you will lead the Unseen Path's efforts personally.", objectives = "" }
WordHunterWoW_QuestEN[40960] = { title = "Luminous Pearl", description = "Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand.\n\nThis is clearly a magical item, and should be brought to a magical person.", objectives = "" }
WordHunterWoW_QuestEN[40961] = { title = "The Dalaran Fountain", description = "You fished this up, did you? I'm... not quite sure what you want ME to do about that. Here.\n\n<Khadgar pats you on the head.>\n\n\"Good job.\"\n\nWith regard to the pearl... it does seem to be magical, but I couldn't tell you much more than that. Perhaps it might look nice in the Dalaran fountain?", objectives = "" }
WordHunterWoW_QuestEN[40962] = { title = "Dark Waters", description = "Come with me to the edge of Elune'ara. Its crystal waters can wash away even the darkest shroud to reveal the truth within.", objectives = "" }
WordHunterWoW_QuestEN[40963] = { title = "Take Them in Claw", description = "We should have seen this coming. My sister is dead, my friends are wounded and we will likely die here.\n\nI want revenge.\n\n<Lyrea hands you a vial full of growing green liquid.>\n\nWe cannot beat them, but we can turn the Stronghold against them.\n\nWild hippogryphs are attracted to the scent in this bottle. Wild hippogryphs are also notoriously violent when the object of their attraction is not a hippogryph.\n\nUse it to clear a path deeper into the stronghold.", objectives = "" }
WordHunterWoW_QuestEN[40964] = { title = "The Rift Between", description = "I was with Lothrius when the Nightborne poured into the stronghold.\n\nHe and his constructs managed to get the majority of us out of the Athenaeum, but he was cornered before he could make good on his own escape.\n\nI know he still lives- I feel it in my gut!- but I cannot go back for him myself. My injuries are too severe.\n\nBeakbuck will take you to where we last saw Lothrius. Simply let him know when you are ready to leave.\n\nGo quickly, and good luck!", objectives = "" }
WordHunterWoW_QuestEN[40965] = { title = "Lay Waste, Lay Mines", description = "They ransacked my library, {name}.\n\nIf they want our knowledge, we will give it to them. \n\nThis piece of rune work will allow you to cast an ensnaring spell on the ground. When the Nightborne cross the threshold they will see the true might of the Moon Guard.\n\nTeach them well!", objectives = "" }
WordHunterWoW_QuestEN[40967] = { title = "Precious Little Left", description = "I have not been able to leave the safety of my guardians to search, but there are three tomes of great importance to me and mine. \n\nThey contain secrets and cantrips that the Nightborne must NOT obtain. \n\n<Lothrius raises his hand to your forehead, cementing the names of three tomes into your mind> \n\nIf we cannot best them, we must preserve all we can. Hurry, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40968] = { title = "Recovering Stolen Power", description = "My injuries will not kill me, but I cannot fight. I have my own idea of how to deal with the remaining Nightborne.\n\nThey destroyed our defense matrix as soon as they arrived. Surely one of them carries the spell focus necessary to reactivate it.\n\nFind it, then go to a hippogryph. They linger throughout the Stronghold.\n\nThese loyal beasts will take you to the skies and take care of the rest.", objectives = "" }
WordHunterWoW_QuestEN[40969] = { title = "Starweaver's Fate", description = "I will take these tomes to Thalrenus.\n\nThere is one thing that weighs heavily on my mind, and I would like for you to attend to it in my stead. \n\nMy wife and life partner, Syrana Starweaver, resides in the Starweaver's Sanctum across the bridge. It fell shortly after the Nightborne entered the Stronghold. \n\nIf she still lives she will need to know of our efforts. Her power is sorely needed. \n\nGive her my best- I will be along shortly.", objectives = "" }
WordHunterWoW_QuestEN[40970] = { title = "The Orchestrator of Our Demise", description = "Conjurer Thalerian must be stopped.\n\nHe immediately sought out my father's private study when he arrived and he has not yet emerged. I worry that he may have found a very dangerous item.\n\nIt is called the Astromancer's Keystone. It is used to manipulate the stronghold's defenses.\n\nSuch magic was meant to protect the Moon Guard- used for any other purpose and it becomes unspeakably destructive.\n\nRetrieve the Keystone. Slay Conjurer Thalerian to get it, if you must.", objectives = "" }
WordHunterWoW_QuestEN[40971] = { title = "Overwhelming Distraction", description = "Do you see the Nightborne outside this room?\n\nThey hold us here, like mice in a cage. It is more convenient for them that we are pinned down while they search the Sanctum for my father's relics.\n\nMy companions and I can escape to higher ground with some help.\n\nTake this crystal. While standing on a mana focusing rune, use it to overcharge a Conjurer.\n\nTheir summons will turn on them and create an opening.\n\nUse it well, and we will meet you atop the stronghold when the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[40972] = { title = "Last Stand of the Moon Guard", description = "This is all that remains of the Moon Guard.\n\nTake a good look.\n\nWe are but a shadow of our former selves, and we have the Nightborne to thank for our demise.\n\nFor now there is nothing more we can do. If we want to live, we must leave immediately.\n\nRetribution can wait.", objectives = "" }
WordHunterWoW_QuestEN[40974] = { title = "Latosius' Trial", description = "I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, {name}, and the might of the Moon Guard will be yours forevermore.", objectives = "" }
WordHunterWoW_QuestEN[40976] = { title = "Audience with the Warchief", description = "\n\nTensions are running high, demon hunter. Warchief Vol'jin was gravely wounded in a disastrous assault on the Broken Shore.\n\nI suggest you offer your skills in service of the Horde before your presence is... misinterpreted.\n\nHigh Overlord Saurfang commands the city's defenses. Though wary of the Illidari, I believe he will give you a chance to prove your worth.\n\nSpeak to him and request passage into Grommash Hold.", objectives = "" }
WordHunterWoW_QuestEN[40982] = { title = "Second Sight", description = "Sylvanas becoming Warchief may be problematic. In life she was a proud ranger, known to many in our ranks. But since the Scourge took her, some of her own allies do not trust the Banshee Queen.\n\nThe Legion will strike at the first hint of dissension.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", objectives = "" }
WordHunterWoW_QuestEN[40983] = { title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Protect the Banshee Queen!", objectives = "" }
WordHunterWoW_QuestEN[40986] = { title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "" }
WordHunterWoW_QuestEN[40987] = { title = "The Call of Vengeance", description = "Our goals have been met, death knight, and it is time we part ways.  I think I will be glad to see the last of you.\n\nGo on, return to your dark masters. We are done here.", objectives = "" }
WordHunterWoW_QuestEN[40988] = { title = "Too Many Cooks", description = "Greetings. I am called Nomi.\n\nI couldn't help but notice that recipe that you just picked up and... well, you'd never guess it, but I'm a bit of a chef myself.\n\nUnfortunately, I'm not much of a fighter, and this place is dangerous. You, on the other hand, are clearly an accomplished {class}.\n\nCome find me in Dalaran. Maybe we can work together!", objectives = "" }
WordHunterWoW_QuestEN[40989] = { title = "The Prodigal Sous Chef", description = "{name}? Master, is that you?\n\nDon't you recognize me? It's me, Nomi! Remember, we cooked together in Pandaria? More accurately, you cooked and I learned. I was not much more than a cub back then.\n\nBoy, am I glad to see you!\n\nI'm headed back to the Dalaran kitchens. Come find me! Maybe we can work together!", objectives = "" }
WordHunterWoW_QuestEN[40990] = { title = "A Good Recipe List", description = "I've tried adventuring, and it isn't for me. Cooking is my one true passion: the heat of the stove, the sizzle of bacon... nothing beats it.\n\nLet me help you, Master {name}. If you can bring me some recipes, I can work on improving them, here in Dalaran.\n\nWe'll make a great team. What do you say?", objectives = "" }
WordHunterWoW_QuestEN[40991] = { title = "Opening the Test Kitchen", description = "I can cook, but I can't really hunt... or even fish, for that matter.\n\nIf you bring me ingredients, however, I will use them to research new recipes for you.\n\nWe can start with the few fish I managed to scrounge up. You'll find them in the barrel in the back of the kitchen.", objectives = "" }
WordHunterWoW_QuestEN[40996] = { title = "Delegation", description = "If I might impart some advice to aid you on the trials and tribulations ahead: do not hesitate to use the many resources of the Uncrowned to aid your efforts.\n\nThere is a communal board in the tavern beyond this chamber where we organize the efforts of our underlings.\n\nSeek out Nikki by the board - she can show you the ropes.", objectives = "" }
WordHunterWoW_QuestEN[40997] = { title = "Lethal Efficiency", description = "Word is you're headin' down to the Broken Isles. That true?\n\nSoon as news got out about the place, we combed through every book, tome, and paper we could get our hands on. We put together quite the report! You should take a look.\n\nWhile you're here, this board is where the magic of the Uncrowned happens. You can put a bounty on a king's head, offer a reward for felsilk cloth... just jot down your latest whim and your agents will take care of it.", objectives = "" }
WordHunterWoW_QuestEN[41000] = { title = "King Forgalash's Burden", description = "That sea witch spoke the truth.\n\nI witnessed the Tidemistress confer with King Forgalash on several occasions.\n\nKill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise.\n\nI will meet afterwards in the center of Jandvik. I need to warm myself by its fires.", objectives = "" }
WordHunterWoW_QuestEN[41001] = { title = "Shatter the Sashj'tar", description = "The Sashj'tar forces may have dwindled, but the Tidemistress has surrounded herself with her fiercest naga.\n\nThis is the time to strike a final crushing blow against the Sashj'tar.\n\nIf we can defeat them now, we may finally break the back of this menace and save Jandvik.", objectives = "" }
WordHunterWoW_QuestEN[41002] = { title = "A Weapon of the Horde", description = "It would seem I underestimated your initial value.\n\nWe will have need of your kind in the coming war. I plan to hunt these demons to the ends of Azeroth, and your kind will be the arrow I shall loose upon them.\n\nTell your Illidari within Orgrimmar to make ready to serve the Horde.\n\nBut make no mistake, your kind once served the Betrayer. Betray me, and there is no world you can run to that will save you from my vengeance.", objectives = "" }
WordHunterWoW_QuestEN[41003] = { title = "The Emperor's Gift", description = "Ah, Sheilun, the legendary staff wielded by our last emperor. If the Legion were to acquire this weapon, they could unleash untold horrors across the whole of the continent. They must be stopped!\n\nIf you want to get to the Terrace as fast as possible, you should hitch a ride directly to the mainland. Tak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", objectives = "" }
WordHunterWoW_QuestEN[41004] = { title = "Jandvik Craftsmanship", description = "{name}, you have slain both Tidemistress Sashj'tar and King Forgalash, an incredible feat for a {race}.\n\nEven without their leaders, I am certain that the naga and the sea giants will regroup and unleash a final assault on us.\n\nWe will need your help if Jandvik is going to survive.\n\nFjolrik and I have devised a plan of attack. Go and speak with him.\n\nBe sure to drag that prow with you. Fjolrik will need it.", objectives = "" }
WordHunterWoW_QuestEN[41005] = { title = "Coastal Cleanup", description = "Toryl wants me to construct a mighty war machine to strike a final blow against the naga. I have a plan to turn the Sashj'tar's own siege weapons against them.\n\nWe sent a war party out earlier to destroy a cluster of ballistae that were assailing Jandvik from the coast.\n\nSift through the wreckage and salvage any useful parts that you can get your hands on.\n\nKeep an eye out for harpoons.", objectives = "" }
WordHunterWoW_QuestEN[41006] = { title = "Assassinate That Guy", description = "", objectives = "" }
WordHunterWoW_QuestEN[41007] = { title = "Building a Better Boat", description = "I am a master craftsman, but even my siege weapons cannot reach the Sashj'tar's base from Jandvik. I will need to construct a seaworthy boat on which to mount my weapon.\n\n<Fjolrik examines the prow.>\n\nYes, this will make a sturdy brace beam for a boat... I think.\n\n<Fjolrik scratches his head.>\n\nI've never built a boat before, but I am certain that if you bring me enough wood, I can construct something that will float.", objectives = "" }
WordHunterWoW_QuestEN[41008] = { title = "Hunter to Hunter", description = "I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey.\n\nI can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness.\n\nFight well, {name}. May Talonclaw serve you well.", objectives = "" }
WordHunterWoW_QuestEN[41009] = { title = "Hunter to Hunter", description = "Now that Titanstrike is yours, ye should learn more about the night elf who set us on this journey.\n\nShe might well be back at the Hunter's Reach shop where you met her. Whoever this Emmarel Shadewarden is, I'd bet me beard she has some part to play in the war against the Legion!\n\nThanks again fer the fun, {name}. If ye ever have need of me, just call!", objectives = "" }
WordHunterWoW_QuestEN[41010] = { title = "Fish Frenzy", description = "{name}!\n\n<pant, pant>\n\nYou've got to see it! The fish, they're... they're everywhere!\n\nOff the coast of Val'sharah, something's whipping them up into a frenzy.\n\nI've never seen better fishing in my life!\n\nI've got a boat down below. Grab your pole and I'll take you there!", objectives = "" }
WordHunterWoW_QuestEN[41019] = { title = "Actions on Azeroth", description = "Let me show you the Command Map. Thanks to some draenei construction and naaru magic we now have a window into the Broken Isles! You can devise strategy, send your agents on missions, and choose our first area to operate in.\n\nTake a look and let me know where we are going!", objectives = "" }
WordHunterWoW_QuestEN[41027] = { title = "One Last Breath", description = "<The parchment is soaked in seawater. A note is hastily scribbled on it.>\n\nTo whomever finds this note first,\n\nBefore I was cast from Suramar, I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne.\n\nAll of this was forgotten when the Legion came.\n\nBefore I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea.\n\nDrink it and explore the vast deep in my honor.", objectives = "" }
WordHunterWoW_QuestEN[41028] = { title = "Power Grid", description = "This station has fallen into disrepair. The circuit is broken, and to mend it we must recharge the seals in the central chamber.\n\nBoth a high potency current and low potency current are needed for each seal. Direct the currents to point at the same seal, then engage the seal.\n\nMe? I shall supervise. You are the help, after all.", objectives = "" }
WordHunterWoW_QuestEN[41030] = { title = "Sigil Reclamation", description = "The smooth square sigil weighs a fair amount more than its appearance would suggest. \n\nHandling it results in an intense tingling sensation in your palm- this is an object of focused, pure power. \n\nSuch an advantage should not be so easily surrendered to the Nightborne.", objectives = "" }
WordHunterWoW_QuestEN[41031] = { title = "For the People", description = "We have a problem, friend.\n\nAcross the canal is a district not well known for affluence. Since the demons' arrival, it has been locked down. I have heard the cries of those who have been deprived of sustenance.\n\nTake this wineskin. Find an Arcwine fountain and take your fill.\n\nFind those who are suffering and offer them a drink. It is the best we can do in the present circumstances.\n\nYou must not be seen doing this, {name}. It will end badly.", objectives = "" }
WordHunterWoW_QuestEN[41032] = { title = "Stop the Spell Seekers", description = "The Nightborne are here in force. As if that were not worrying enough, they now bring reinforcements.\n\nI have seen them opening large portals to Suramar.\n\nThrough these portals they have called in their constructs. They are immune to much of my magic and so represent something of a stumbling block to rejoining the others.\n\nFind the portals and close as many as you can. That should buy us some time.", objectives = "" }
WordHunterWoW_QuestEN[41033] = { title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", objectives = "" }
WordHunterWoW_QuestEN[41034] = { title = "Testing the Waters", description = "There is no place that the Sashj'tar can hide from you now, {name}.\n\nThey will not be expecting a direct attack in their waters. This is a perfect opportunity to cut down their commanders.\n\nMeet me in Jandvik after you have slaughtered them.", objectives = "" }
WordHunterWoW_QuestEN[41035] = { title = "Felstorm's Plea", description = "You may not know me, but I need your help, {name}.\n\nMeet me in the Violet Gate and I'll explain everything. \n\nMake haste. I fear we have little time.", objectives = "" }
WordHunterWoW_QuestEN[41036] = { title = "The Dreadlord's Prize", description = "Kathra'natir escaped my grasp, but I know what his next step will be.\n\nHe seeks an ancient relic called the Forge of the Guardian, used for centuries by the Council of Tirisfal to infuse their power into the Guardian. The forge was hidden away, its location known only to the Council themselves.\n\nNow the dreadlord has this knowledge.\n\nWe must go to the Violet Hold. I only hope we are not too late.", objectives = "" }
WordHunterWoW_QuestEN[41037] = { title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", objectives = "" }
WordHunterWoW_QuestEN[41038] = { title = "The Mead Master", description = "The Storm Brew is created by a legendary vrykul brewmaster named Melba. Here is the location of her meadery along the northern Stormheim coast.\n\nIf we can convince her to share her secret recipe with us, we will gain a significant advantage over the enemy.\n\nGrandmaster, how are your skills of persuasion?", objectives = "" }
WordHunterWoW_QuestEN[41039] = { title = "Stolen Knowledge", description = "Morjirn, the head brewer of the Tideskorn clan, has the Storm Brew recipe.\n\nI have never been strong enough to assault his fortress alone, but together with you, I think we can claim retribution for my fallen master. I would like nothing better than to pry the recipe from Morjirn's cold, dead fingers.\n\nWhile we are there, we will sample his Storm Brew. I'd like to see if his brewing skills are even near my master's.", objectives = "" }
WordHunterWoW_QuestEN[41040] = { title = "Halls of Valor: The Brewmaster", description = "I've made a new breakthrough with Melba's Storm Brew recipe.\n\nWe need the use of a special cauldron, one owned by Odyn himself.\n\nThis cauldron is located in none other than the Halls of Valor.\n\nThere is only one way to enter this exalted place, and that is through the storm god's favor.\n\nYou must find a way to enter the hall of warriors. You may require allies for this endeavor, {name}.", objectives = "" }
WordHunterWoW_QuestEN[41043] = { title = "Jandvik's First Sailor", description = "It should not take me long to build the boat, but you will need someone to pilot it while you are unleashing havoc on the Sashj'tar.\n\nWhen Brandolf heard about our plan, he volunteered to be your oarsman.\n\n<Fjolrik laughs.>\n\nYou must have made quite the impression on him. No vrykul has dared set boot to boat in an age.\n\nGo speak with him when you are ready to begin your assault.", objectives = "" }
WordHunterWoW_QuestEN[41044] = { title = "Attack and Assail!", description = "I will row with the strength of a titan while you use that contraption that Fjolrik made to send the Sashj'tar back to the black abyss that they came from!\n\nLet me know when you are ready, and we will begin our final assault.", objectives = "" }
WordHunterWoW_QuestEN[41052] = { title = "A Desperate Plea", description = "{name}, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard.\n\nI fear he is determined to return to the Broken Shore. Will you speak to him?", objectives = "" }
WordHunterWoW_QuestEN[41054] = { title = "Love Lost", description = "Malfurion, my love...\n\nIn vision I saw him, enraged and then distressed, and now lost beyond my mind's reach.\n\n{race}, I know we have little reason to trust one another, but I will not turn away your help.\n\nIf you value the sanctity of this world, you will come with me.", objectives = "" }
WordHunterWoW_QuestEN[41056] = { title = "Love Lost", description = "Malfurion, my love...\n\nIn vision I saw him, enraged and then distressed, and now lost beyond my mind's reach.\n\nHe is strong, but the horrors that have befallen this land are all-consuming.\n\nI must find him, and you must help me!\n\nGather your wits, {race}, and follow me.", objectives = "" }
WordHunterWoW_QuestEN[41059] = { title = "Halls of Valor: Odyn's Cauldron", description = "Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge.\n\nWith you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn's Cauldron, which can be found in the great hall just ahead.\n\nYou have my blessing to borrow it. Good luck in your journey ahead, {name}.", objectives = "" }
WordHunterWoW_QuestEN[41060] = { title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", objectives = "" }
WordHunterWoW_QuestEN[41062] = { title = "Spoils of Victory", description = "The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest.\n\nBattlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.", objectives = "" }
WordHunterWoW_QuestEN[41066] = { title = "The Hunter's Gaze", description = "{name}, before you lies your nether crucible - more powerful than any we've crafted before.\n\nThe souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth.\n\nWhat we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[41067] = { title = "Time is of the Essence", description = "As you can see, there is little time to spare - the Legion's armies already encroach on our world.\n\nKayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", objectives = "" }
WordHunterWoW_QuestEN[41069] = { title = "Direct Our Wrath", description = "We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease.\n\nUntil then, we must do what we can on the ground to alleviate their foothold before it grows further.\n\nThis citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault.\n\nI think you would agree that none would be better suited to lead our charge than you.", objectives = "" }
WordHunterWoW_QuestEN[41070] = { title = "Spoils of Victory", description = "In conquering this citadel we obtained something that I think would be of great use to you.\n\nGaardoun's men have it well-guarded just below - I suggest you have him show you.", objectives = "" }
WordHunterWoW_QuestEN[41085] = { title = "A Mage's Weapon", description = "It is decided, then.\n\nThe foundation of the Tirisgarde's strength lies in the ancient artifacts wielded by its champions. Your first task will be to retrieve one such artifact.\n\nThe master appendix of this library lists every artifact known to the Council of Tirisfal. There should be a few choices in there worth looking into.\n\nI will leave it to you to choose which to pursue.", objectives = "" }
WordHunterWoW_QuestEN[41086] = { title = "A Peaceful World", description = "Word has reached us that the Legion is advancing on the Broken Isles.\n\nThey beset us from all sides, and if we do not stand strong, they will spill over into the rest of Azeroth.\n\n{name}, we need your help more than ever. Lend your strength to those defending at the front. We cannot fail here.", objectives = "" }
WordHunterWoW_QuestEN[41087] = { title = "Storm Brew", description = "Grandmaster, the Legion is attacking the Wandering Isle!\n\nWe sent defenders up to the Ridge of Laughing Winds, but they can't hold for long.\n\nOur only chance is to finish making the Storm Brew. Chen and Aegira have already gone up to the Chamber of Whispers, but they are under heavy attack as well.\n\nSpeak to Tak Tak and take a kite up to join them at once!", objectives = "" }
WordHunterWoW_QuestEN[41094] = { title = "Hatchlings of the Talon", description = "Greetings, hatchling. Do you wish to soar amongst the clouds as my children do?\n\n<Aviana chuckles - a clicking, crow-like noise.>\n\nVery well, receive my blessing and we shall see how developed your wings are.", objectives = "" }
WordHunterWoW_QuestEN[41096] = { title = "Time is of the Essence", description = "As you can see, there is little time to spare - the Legion's armies already encroach on our world.\n\nAltruis has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", objectives = "" }
WordHunterWoW_QuestEN[41097] = { title = "Shard of Vorgos", description = "According to the wyrmtongue servant, there is a portal that will take you into the Burning Legion command ship. However, the portal is locked to those without the keys.\n\nThe first key shard is held by an Ered'ruin known as Vorgos. He resides within the Fel Breach, which is at the end of the Arcway.\n\nSlay Vorgos and place the key shard into its position next to the portal.", objectives = "" }
WordHunterWoW_QuestEN[41098] = { title = "Shard of Kozak", description = "The demon leading the operation in Felsoul Hold is an eredar named Azoran. In order to get to him, we will need to open a portal to the Burning Legion command ship.\n\nAzoran has a demon jailer in his service known as Kozak the Afflictor.\n\nKozak the Afflictor holds one of the key shards necessary to open a portal to the ship. He can be found in the prison quarters known as the Halls of the Eclipse in the lower portion of Felsoul Hold.\n\nSlay Kozak and place his key shard next to the portal.", objectives = "" }
WordHunterWoW_QuestEN[41099] = { title = "Direct Our Wrath", description = "The Tomb of Sargeras is the Legion's primary entrance into our world - it must be destroyed.\n\nNo easy task, but until we have the means to do so we must do what we can to stop their invasion.\n\nThe Legion used this citadel to spearhead invasions on other worlds - we can use its navigation systems to plan our own assault against them.\n\nYou, of course, must take the honor of first breaking ground on their territory, but we will soon follow.", objectives = "" }
WordHunterWoW_QuestEN[41104] = { title = "The New Jarl", description = "We have done it, {name}! We have shattered the Sashj'tar!\n\nCome! Let us tell Toryl and all of Jandvik of our victory!", objectives = "" }
WordHunterWoW_QuestEN[41105] = { title = "The Sword of Kings", description = "The first king of the humans, Thoradin, performed many acts of heroism and valor. While on a personal quest near the end of his reign, he stumbled upon the tomb of my brother Tyr... and the grave-prison of the monstrosity he died fighting. Thoradin unintentionally awoke the beast and gave his life to keep it from escaping.\n\nIt is Thoradin's sword, Strom'kar, that has kept the monster at bay. Retrieve it and finish what Tyr and Thoradin started. Kill Zakajz the Corrupted.", objectives = "" }
WordHunterWoW_QuestEN[41106] = { title = "Call of the Wilds", description = "Beating the Legion requires us to strike quickly and unexpectedly.\n\nWe have discovered a Dreamway by which we can travel through the Emerald Dream itself. Though only a short walk through the Dream, it will allow us to cross vast distances on Azeroth and even access the ancient home of all druids, Val'sharah.\n\nMalfurion is preparing the ritual to open the Dreamway. I need you to summon Zen'tabra and Naralex to his side.\n\nOnly by combining our efforts can we hope to succeed.", objectives = "" }
WordHunterWoW_QuestEN[41107] = { title = "Bad Apples", description = "That fruit over there? That's a pale imitation to what I can grow.\n\nBut that accursed Daglir somehow manages to gain the favor of the courts, so we must dine on mediocrity!\n\nWe must teach Daglir a lesson for stealing my crop, but we must be discreet.\n\nOutside the shield grows a purple flower called Shadowbloom. Fetch some for me and we'll make sure that he pays dearly for his insolence!", objectives = "" }
WordHunterWoW_QuestEN[41108] = { title = "Rain Death Upon Them", description = "Aboard the hippogryph you now possess a unique opportunity. It is time for the Nightborne to regret letting you live.", objectives = "" }
WordHunterWoW_QuestEN[41109] = { title = "Waiting for Revenge", description = "The Volatile Spell Focus hums with energy as you hold it. Handle with care! \n\nOnly with this item in your possession will the Hippogryphs allow themselves to be mounted.", objectives = "" }
WordHunterWoW_QuestEN[41110] = { title = "Waiting for Revenge", description = "The Hippogryph eyes you curiously, searching your hands.", objectives = "" }
WordHunterWoW_QuestEN[41111] = { title = "Rain Death Upon Them", description = "The hippogryph before you presents a unique opportunity. It is time for the Nightborne to regret letting you live.", objectives = "" }
WordHunterWoW_QuestEN[41112] = { title = "The Great Akazamzarak", description = "There is a goblin who is a master of portals and teleportation by the name of Akazamzarak. His talents have gone mostly unnoticed, however, since he mostly uses them for chicanery.\n\nHe is, what you would call, a street performer.\n\nFortunately for us, he is performing in the streets of Dalaran, grifting coins from the unenlightened masses.\n\nTake this bag of gold. See if you can convince him to change vocations.", objectives = "" }
WordHunterWoW_QuestEN[41113] = { title = "The Only Way to Travel", description = "Portals? Teleportation? You bet I can help you out with that! I mean, how do you think I pull the rabbit out of...\n\n...um, you didn't hear that.\n\nAnyway, I can help you move your mages around, if the price is right. Heck I can even teach those combat mages a thing or two. Ever been on the receiving end of an exploding bunny? It ain't pretty!\n\nFor starters, let me whip up a portal to take us to this hall you're talking about.", objectives = "" }
WordHunterWoW_QuestEN[41114] = { title = "The Champion's Return", description = "I can sense the power of the artifact you hold. It will do well against the Legion as it is, but we have the ability to unlock its power even further. \n\nYou must return to the Hall of the Guardian. You can use the incantation I taught you before to pass through the runes.", objectives = "" }
WordHunterWoW_QuestEN[41115] = { title = "Champion: Chen Stormstout", description = "", objectives = "" }
WordHunterWoW_QuestEN[41119] = { title = "The Hunt", description = "You must lead this hunt, {name} - a small force will join you to ensure Varedis meets his end.\n\nYou must try to make it into Varedis' hold undetected; the less time you spend in Legion territory the better.\n\nMeet at Krasus' Landing when you are prepared to leave.", objectives = "" }
WordHunterWoW_QuestEN[41120] = { title = "Making Arrangements", description = "Do you remember Varedis? He was once our lead trainer at the Black Temple, but fell early in the siege.\n\n...or so we thought.\n\nKor'vas spotted the traitor amongst the Legion wielding glaives imbued with power unlike anything she'd ever seen.\n\nThe Kirin Tor have an eredar lord interred in the Violet Hold that will know where Varedis' base of operations is. The hold's warden has agreed to consider granting us access to him.\n\n<Altruis smirks.>\n\nTime to play the friendly diplomat.", objectives = "" }
WordHunterWoW_QuestEN[41121] = { title = "By Any Means", description = "We need to find out Varedis' location from the eredar inside this prison - the kind warden and his men here are all that stand in our way.\n\nWe'll take them on together if need be - whatever it takes.", objectives = "" }
WordHunterWoW_QuestEN[41123] = { title = "An Artisan's Mark", description = "You there! Do you have a moment?\n\nI need you to meet with my friend in the Promenade and retrieve a signet ring. I would send my oaf of an apprentice, but he is not finished with the simple task I gave him.\n\nI am expecting a guest at any moment and I simply must have it before he arrives. Can you help me, friend?", objectives = "" }
WordHunterWoW_QuestEN[41124] = { title = "The Tirisgarde Reborn", description = "The Tirisgarde is reformed.  It is time we begin our mission in earnest.\n\nThe order will need leaders, and though I may be an experienced mage,  I am no strategist. You have proven yourself capable, in both your past exploits and present. \n\nWill you take on this challenge, {name}?", objectives = "" }
WordHunterWoW_QuestEN[41137] = { title = "Fall of the King", description = "All that remains is the Sea Giant King.\n\nPlace our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him.\n\nThere is a derelict boat that washed up on the shore. Use that to quickly get to the king's island.\n\nGird your loins, {name}. This fight will not be easy.", objectives = "" }
WordHunterWoW_QuestEN[41138] = { title = "Feeding Shal'Aran", description = "With leyline energy feeding in from Anora, this chamber can begin to awaken.\n\nIt will be a slow process, and we must take care to mask this activity from our enemies, a process which itself requires enormous effort and focus.\n\nFurthermore, there is the conundrum of actually consuming the mana in this form. A stream too weak is not enough to provide sustenance - too powerful and it would vaporize us.\n\nThere is much work to be done yet. For now, let us examine the feed.", objectives = "" }
WordHunterWoW_QuestEN[41139] = { title = "The Key Is Around Here Somewhere...", description = "Well aren't ye a sight fer sore eyes!\n\nIt's no use tryin' to bust open this cage, this one needs a key!\n\nNow, I know what yer thinkin', \"How is it possible that the Burnin' Legion could capture a dwarf as mighty as ol' Angus here.\"\n\nYe can rest easy knowin' I let myself be captured. I'm here to rescue a dear friend o' mine, an' gettin' captured was the only way!\n\nI had the key in me pocket... but it musta' fell out.\n\nIt's  errm... around here somewhere.\n\nA felhunter ate it a wee while back...", objectives = "" }
WordHunterWoW_QuestEN[41140] = { title = "Search and Rescue!", description = "We've got to find Brambley before it's too late!\n\nOl' Brambley an' I have been fightin' side by side since the Third War. When the Burnin' Legion invaded, we didn't think twice about coming to the Broken Isles.\n\nFightin' is what we do best!\n\nDuring the battle ol' Brambley got caught too deep an' got himself captured. Now we've got to rescue him!\n\nLast I saw, the demons were keeping him in a prison cell not far from here... let's go!", objectives = "" }
WordHunterWoW_QuestEN[41141] = { title = "A Conjuror's Duty", description = "I don't know about you but I'm ready to get this show on the road. This place is nice and all, but it's a bit stuffy.\n\nI'll see what I can do to get some more mages in this group of yours. You go ahead and check the map over there. It'll help you plan your first moves.", objectives = "" }
WordHunterWoW_QuestEN[41143] = { title = "Mglrgrs Of Our Grmlgrlr", description = "Mlrg...mglrmlr...\n\nGmlrgmlr mglrml gmlrg! Mlrgrlgr!\n\n<Mrgrglilgrl points at the trail of spiderwebs leading out of the ruin.>", objectives = "" }
WordHunterWoW_QuestEN[41146] = { title = "Elegant Design", description = "Amateur merchants complain about supply and demand. Masters create their own.\n\nYou have done well retrieving the last two pieces I requested, but they are baubles compared to this.\n\nYour target is the Lady Anastae, and she has something very valuable of mine: A design for a masterwork gem cut. \n\nGo and get it from her by any means necessary, but take care. She is a master manipulator and will tell you all manner of lies.", objectives = "" }
WordHunterWoW_QuestEN[41148] = { title = "Dispensing Compassion", description = "There is much you need to learn about our city.\n\nFirst and foremost, Arcwine. It is the vehicle by which we imbibe the Nightwell's energies. Without it, we wither and die.\n\nPalace lackeys have seen fit to ration it, thinking this will control us. Keep us quiet, complacent.\n\nI would like you to look for those in need near the tavern. You will find many, but those most desperately afflicted by this rationing will be obvious.\n\nTake this flask. Revive them. Tend to their suffering.", objectives = "" }
WordHunterWoW_QuestEN[41149] = { title = "A Re-Warding Effort", description = "<This small device of elegant nightborne design crackles gently with arcane power.\n\nKel'danath's notes mention wards that keep the withered at bay. It seems he found some form of spellcasting that does not tempt their ravenous appetite for magic.\n\nThese may prove useful in your search for the missing arcanist.>", objectives = "" }
WordHunterWoW_QuestEN[41155] = { title = "The Dark Riders", description = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "" }
WordHunterWoW_QuestEN[41156] = { title = "The Power Possessed", description = "Our goals have been met, warlock, and it is time we part ways.  I think I will be glad to see the last of you.\n\nGo on, return to your dark masters. We are done here.", objectives = "" }
WordHunterWoW_QuestEN[41157] = { title = "Corrupted Studies", description = "Stormheim is steeped with artifacts from tha War of the Ancients. Demon artifacts ta be exact.\n\nI think these artifacts can clue us into some knowledge about their leader, Sargeras. I've already found some fragments to a titan disc, but need ta find the rest of 'em.\n\nI need ya ta dig around Stormheim and see if ye can find any more fragments so we can reassemble the disc.", objectives = "" }
WordHunterWoW_QuestEN[41158] = { title = "Fragments of the Fjords", description = "{name}, have you seen my ledger around here? I seemed to have misplaced it when I was stowing some canopic jars.\n\nOh, nevermind. Brann Bronzebeard has sent for you though. He's in Stormheim continuing his research.\n\nMake your way out to him and let him know I'm still waiting on those flayed-skin chronicles he found.", objectives = "" }
WordHunterWoW_QuestEN[41159] = { title = "Process of Elimination", description = "With so many places ta dig up fragments, it's become quite a pain figuring out where ta look for more of the titan disc.\n\nI have a plan though. I need ye ta eliminate potential areas where the disc could exist so we can narrow down where in Stormheim it might exist.\n\nYou take part of the area an' I'll take the other part. Meet back here if ye find anythin'.", objectives = "" }
WordHunterWoW_QuestEN[41160] = { title = "Earth to Earth", description = "From the earth comes strength, and such strength can be imbued into weapons of power.\n\nYou have the look of one who seeks to know how to create such weapons.\n\nThere are creatures that still inhabit this dying planet who bear such strength. Bring me their cores and I shall trade you the knowledge you seek.", objectives = "" }
WordHunterWoW_QuestEN[41161] = { title = "Out of the Frying Pan", description = "Oh hello, {name}. I tell you, ever since I was given this shop, it's been nothing but a headache. I can't seem to ever find what I'm looking for.\n\nWhich reminds me, Brann Bronzebeard has sent for you. He's in Azsuna tracking down more pieces of whatever it is he's searching for.\n\nNow where'd those pewter drinking cups go...", objectives = "" }
WordHunterWoW_QuestEN[41162] = { title = "And Into the Fel Fire", description = "I found something, {name}. Well, a couple of things actually.\n\nFirst I found an ancient text talking about a demon who harnessed the power of the titan disc I've been searching for.\n\nThen I found a device which supposedly is used to summon 'im! Only, it's missin' some pieces from what I can make out.\n\nI'm sure if we survey around Azsuna some more, those missin' pieces are sure ta turn up.", objectives = "" }
WordHunterWoW_QuestEN[41163] = { title = "The Apocalypse Bringer", description = "Right, well, I managed to piece the device back together.\n\nI guess I'll jes' turn it on when you're ready and we'll see what happens, yea?", objectives = "" }
WordHunterWoW_QuestEN[41164] = { title = "One Step Closer", description = "{name}! I just heard that Brann Bronzebeard - that crazy, titan-obsessed dwarf - has decided to go hunting for his precious disc in Suramar.\n\nTalk about the last place you'd want to go digging around, given the current events.\n\nI'm sure he could use your help.", objectives = "" }
WordHunterWoW_QuestEN[41165] = { title = "Deciphering Demonology", description = "I found a piece of what appears to be a key to something. I'm certain I can restore it if we can find the other bits.\n\nAfter that, we need to figure out what it's a key to. An' I think I know how to do that.\n\nI've been studying some of the artifacts I've found, and they seem to be pointing to a hidden chamber. I jes' need some more artifacts to study.", objectives = "" }
WordHunterWoW_QuestEN[41166] = { title = "Dark Secrets", description = "I fixed the key and am ready to open the chamber.\n\nMeet me there when you have a chance and we'll discover what waits inside together!", objectives = "" }
WordHunterWoW_QuestEN[41167] = { title = "Fel Fragments", description = "Brann Bronzebeard has requested that I send him more surveying equipment, but I just don't have the time.\n\nWould you be a dear and take this crate to him, {name}? I'd truly appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[41168] = { title = "The Purple Hills of Eredath", description = "Now that we're re-supplied, we can get back ta work.\n\nI found something here that I think ye'll be interested in. It's a page of a book talking about the world of Argus. But before the demons destroyed it.\n\nAnyway, it's been me experience that if ye find one of something, there's sure ta be more of it around.\n\nKeep lookin' around Val'sharah for more of these pages and bring what ye find back ta me. And take the page I found with ya so ye know what yer lookin' fer.", objectives = "" }
WordHunterWoW_QuestEN[41169] = { title = "Darkheart Thicket: Through the Fog", description = "I can't believe that after all that searchin' ye did, it's still missing a chapter!\n\nI'm willin' ta bet that those satyrs got a hand on it and took it somewhere. Probably somewhere dark where no one could find it.\n\nI've heard rumors of a place, the Darkheart Thicket they call it, where the strongest of the satyrs are.\n\nIf I had ta guess, I'd say ye need to go there and look around fer it.", objectives = "" }
WordHunterWoW_QuestEN[41170] = { title = "The Relic Renewed", description = "Very good, very good! Now that we have all the pieces, it's time to put this disc back together!", objectives = "" }
WordHunterWoW_QuestEN[41171] = { title = "The Reliquary Calls", description = "Tae'thelan of the Reliquary has asked me to send anyone who may be able to help them in Azsuna.\n\nSeeing as how you happened into my shop purely by coincidence, I thought you'd be willing to go, {name}.\n\nBack to work for me though. So much to do and so little help.\n\n<Dariness lets out a sigh.>", objectives = "" }
WordHunterWoW_QuestEN[41172] = { title = "Echoes of My Ancestors", description = "This land holds many secrets and many artifacts of ancient times.\n\nFrom what I've been able to discern there's an artifact of great power close to here. I just need to narrow down its location.\n\nI'd like you to dig up more artifacts and learn what you can. When you feel you've done enough research, come back to me and share your knowledge.", objectives = "" }
WordHunterWoW_QuestEN[41173] = { title = "A Beacon of Hope", description = "I've marked the location of the artifact on your map. It's in a rather hostile location, so I'd like you to go there and find it.\n\nWhen you've recovered it, bring it back to me so I can discern its power.", objectives = "" }
WordHunterWoW_QuestEN[41174] = { title = "Worth Its Weight", description = "{name}, if you were a crate of black trilobites, where do you think I would have put you?\n\n<Dariness begins looking around the shop.>\n\nOh, that reminds me. Tae'thelan has requested your presence. He's onto something in Suramar and needs your help.", objectives = "" }
WordHunterWoW_QuestEN[41175] = { title = "Fit for an Elven Queen", description = "The nightborne have dropped their shield allowing us to penetrate their city and learn their secrets.\n\nOne such secret I've discovered is a crown of immeasurable power.\n\nI'd like you to find this crown and report back to me on what it does.", objectives = "" }
WordHunterWoW_QuestEN[41176] = { title = "Sifting Through the Rubble", description = "Then I believe it's clear what we must do next. Find the jewels.\n\nThey're bound to be here somewhere in Suramar, so we better start looking.\n\nI'll coordinate the search from here, while you and my assistants look for the jewels.", objectives = "" }
WordHunterWoW_QuestEN[41177] = { title = "Goblin Archaeology", description = "I'm not sure if you're in on this, but the Reliquary has commissioned the goblins to help them with uncovering artifacts in this land.\n\nI'd like you to go and see if there's any validity to this rumor... and I'd also be interested to know the results.", objectives = "" }
WordHunterWoW_QuestEN[41178] = { title = "Explosive Results", description = "As you may or may not have heard, I've been working with the goblins on using a new way of uncovering our artifacts.\n\nAnd if you know anything about goblins, you know that I'm talking about explosives.\n\nWe've only run a few tests here at my camp, but I would appreciate your help in testing this method out in the field.\n\nI've marked a location on your map that has some particularly difficult digs.", objectives = "" }
WordHunterWoW_QuestEN[41179] = { title = "What Once Was Lost", description = "That reminds me, I found a map to a chamber that may or may not hold something of value.\n\nIt doesn't seem to have any power associated with it, which is why I'm handing it over to you.\n\nHere, take some more explosives. They may help speed up the process of finding it.", objectives = "" }
WordHunterWoW_QuestEN[41180] = { title = "Unspeakable Power", description = "{name}, I received an urgent message from the High Examiner requesting your presence.\n\nHe's finally found something powerful-- VERY powerful--and he wants your help in recovering it.\n\nBe careful down there, {name}. Tae'thelan can be a tad fanatical when it comes to artifacts that hold any sort of energy.", objectives = "" }
WordHunterWoW_QuestEN[41181] = { title = "Narrowing Down", description = "I was right about the nightborne here having objects of great power. I found an ancient text referring to such an object called the Orb of Sciallax.\n\nFrom what I recall in studying the War of the Ancients, Sciallax was a demon lord who came to Suramar and offered the elves at the time a powerful artifact in return for their servitude to the Legion.\n\nI haven't discovered the exact location yet as to the whereabouts, but perhaps some digging can yield us an answer.", objectives = "" }
WordHunterWoW_QuestEN[41182] = { title = "Uncovering the Orb of Sciallax", description = "We'll need to hurry before the nightborne realize what we're after.\n\nI'm bringing the goblins along in case we run into any obstacles along the way.\n\nI've marked the location of the entrance to the chamber the Orb resides in on your map.\n\nMeet me there as soon as you're ready and we'll claim this artifact for our own.", objectives = "" }
WordHunterWoW_QuestEN[41183] = { title = "Academic Exploration", description = "{name}, good to see you. What do you think of my shop so far? Not too bad for just one person, huh?\n\nBy the way, High Examiner Tae'thalan has been digging around Azsuna, and asked that I send you to see him.\n\nKnowing him, he probably thinks he's found yet another world-shatteringly powerful artifact.", objectives = "" }
WordHunterWoW_QuestEN[41184] = { title = "Tried and True", description = "I have realized through experience that the old methods are usually the best and for good reason. I'm done with alternate means of digging for now, and wish to focus on the right way to do things.\n\nThat being said, I believe I've found a new powerful artifact and I'll do literally anything to have it.\n\nI've uncovered a fragment that appears to be a mold for a key. I now simply need the other pieces.", objectives = "" }
WordHunterWoW_QuestEN[41185] = { title = "The Keys to Success", description = "I'd like you to take the mold to the blacksmith in Dalaran. Alard, I believe his name is.\n\nHave him help you forge a new set of keys.\n\nI found some writing on the back of the mold that may hold the answer to what these keys unlock. I'll stay here and try to translate the text.", objectives = "" }
WordHunterWoW_QuestEN[41186] = { title = "History of Highmountain", description = "Let's see, one... two... three... oh, hello {name}. Sorry I didn't see you come in.\n\nThings have been hectic around here. I could really use an assistant.\n\nI do have something for you though, a fellow archaeologist named Lessah has been asking for someone to help her in Highmountain.\n\nI thought you'd be the perfect person for the job.", objectives = "" }
WordHunterWoW_QuestEN[41187] = { title = "Surveying Student", description = "The reason I sent for someone was that I've been having trouble keeping up with my research and training my assistant.\n\nI was hoping you might be able to show him the ropes again. Get him reacquainted with surveying.\n\nJust speak with him when you're ready to go.", objectives = "" }
WordHunterWoW_QuestEN[41188] = { title = "Neltharion's Lair: Misdirected", description = "I've been looking into the history of Huln Highmountain, a legendary warrior from the War of the Ancients whom this very land is named after.\n\nAllegedly some of his personal effects were carried here after his death and have been lost in time.\n\nAfter some digging around I believe I have discovered the location of one of his artifacts to be in a place called Neltharion's Lair.\n\nI'm no fighter, {name}, but you are. Will you go and recover this artifact for me?", objectives = "" }
WordHunterWoW_QuestEN[41189] = { title = "A New Lead", description = "{name}, Lessah in Highmountain has been asking for you.\n\nApparently she's caught a lead on some ancient piece of armor that Huln Highmountain used to wear.\n\nWhen you can, make your way out to her.", objectives = "" }
WordHunterWoW_QuestEN[41190] = { title = "Crystal Eyes", description = "I've delved into the caves here and have discovered many ancient writings.\n\nThe most interesting I've found are resonating crystals, where the drogbar have resided. Unfortunately, they aren't on very good terms with the tauren here and this has hindered my research.\n\nI thought, should there be any trouble with the drogbar, that you'd be able to handle them.\n\nI'd like you to continue my research and discover what you can about Huln.", objectives = "" }
WordHunterWoW_QuestEN[41191] = { title = "Drogbar Deception", description = "According to my research and the information you gave me, I've isolated the location of the necklace.\n\nIt's deep in a drogbar cave, and I'm willing to bet they're not just going to hand it over to you, {name}.\n\nI need you to recover that necklace at any cost.", objectives = "" }
WordHunterWoW_QuestEN[41192] = { title = "The Right Path", description = "This new shop is shaping up quite nicely, I think. Still, there's so much left to organize.\n\n{name}, Lessah has requested your presence in Highmountain. Something about a moose?\n\nI'm not sure to what she's speaking of, but as soon as you have a chance, please go see her.", objectives = "" }
WordHunterWoW_QuestEN[41193] = { title = "Laying to Rest", description = "If I was able to find a bone fragment in what appeared to be a random location, then that means Eche'ro's bones must be scattered around Highmountain.\n\nWe must find his remains and give him the proper burial he deserved.\n\nOh, I'm sorry, in case you weren't aware, Eche'ro was Huln Highmountain's mount and companion.\n\nHe deserves to be honored as Huln once was.", objectives = "" }
WordHunterWoW_QuestEN[41197] = { title = "You've Got to Be Kitten Me Right Meow", description = "While you were dealing with the stray Owlkitten, I took a look around.\n\nIt seems these curious creatures have a habit of escaping their parents' watchful eyes - some are trapped across the road by a wandering Ettin. \n\nHe appears to have been... ahem... eating them.\n\nWe can earn Yowlon's blessing by bringing his children home.", objectives = "" }
WordHunterWoW_QuestEN[41214] = { title = "Parts Unknown", description = "Brambley... I still canna' believe it.\n\nI canna' leave the lad here... not in this place... not like this.\n\nHelp me find the rest of him, so I can take his remains back home where he belongs.\n\nWe'll give him a proper burial... it's what he deserves!", objectives = "" }
WordHunterWoW_QuestEN[41215] = { title = "They Become The Hunted", description = "The trapper you slew was but one of many.\n\nThe Nightborne are subjugating the local creatures, creating a sort of pleasurable exhibit. I think we can strike them in two places at once.\n\nDescend upon these trappers, {race}. Let us teach them a lesson in respecting their prey.", objectives = "" }
WordHunterWoW_QuestEN[41216] = { title = "Survival of the Fittest", description = "The collar you took from the trapper is simple, but effective. Affixing the collar to a target will make them complacent and obedient to their Nightborne masters. Lilryia was able to reverse the spell using the traps you found.\n\nThe magics in the collar can now be used to cancel out the other collars.\n\nHow about giving the Nightborne a reminder that nature always finds a way?", objectives = "" }
WordHunterWoW_QuestEN[41217] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nMuffinus Chromebrew will help oversee your training and adjustment to life on the surface. He's waiting for you on the stands across the road.", objectives = "" }
WordHunterWoW_QuestEN[41218] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[41220] = { title = "Down to Azsuna", description = "{name}, we must find a way to reseal the Tomb of Sargeras.\n\nI have uncovered information concerning an ancient relic, which might be the key to stopping the Legion.\n\nOur search begins on the ancient elven island of Azsuna. Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin.\n\nThe Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin.\n\nReady to take wing?", objectives = "" }
WordHunterWoW_QuestEN[41221] = { title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", objectives = "" }
WordHunterWoW_QuestEN[41222] = { title = "Into The Pit!", description = "The felstalker pits?!\n\nThere's no time to waste, {name}!\n\n I canna' tell ye what the Burnin' Legion has planned for ol' Brambley, but it canna' be good!\n\nHurry! We've got to find him before the Burnin' Legion has their way with him!", objectives = "" }
WordHunterWoW_QuestEN[41230] = { title = "Trapping Evolved", description = "The Nightborne are using magic for everything, even trapping.\n\nNighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. \n\nBring me their traps so that I may study their make.", objectives = "" }
WordHunterWoW_QuestEN[41231] = { title = "Apex Predator", description = "I have good news and bad news, {race}.\n\nThe bad news is that they somehow managed to capture and train a Devilsaur.\n\nThe good news is that it doesn't seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.", objectives = "" }
WordHunterWoW_QuestEN[41255] = { title = "Sowing The Seed", description = "Your weapon is ancient and powerful but it holds the potential to be so much more.\n\nTake this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root.\n\nWith its power both it and your weapon will be far more than they are alone.", objectives = "" }
WordHunterWoW_QuestEN[41256] = { title = "Blast of Spice Fish", description = "I have an ingredient that will make my fruit irresistible.\n\nNot many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel...\n\nThe toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.", objectives = "" }
WordHunterWoW_QuestEN[41258] = { title = "Fruit of the Doom", description = "Now is the time to strike.\n\nShadowbloom has... potent digestive qualities. Go sprinkle some on Daglir's fruit bowls and watch the show.\n\nMeanwhile, I will use the manatrout liquor to cement my position as the premier fruit vendor in the city.", objectives = "" }
WordHunterWoW_QuestEN[41307] = { title = "All That Glitters", description = "Now that the shield is down, the older settlements outside the city have been on my mind.\n\nDid you know that I helped create the filigree on the arcane lamps that are used throughout the city? A simple task, one of my first...\n\nNo matter. Nostalgia is the enemy of progress. The lamps are made of material better used in my new works.\n\nThose wretched harpies probably have several decorating their nests. Bring back any you find.", objectives = "" }
WordHunterWoW_QuestEN[41309] = { title = "Mangelrath", description = "The demonic beast that stands before ye, must be the one that devoured ol' Brambley...\n\nJust look at it, lying there with a full belly! I canna abide it any longer, {name}! We must slay the foul creature and avenge Brambley!\n\nWe've come this far already, {class}.\n\nAre ye with me?!", objectives = "" }
WordHunterWoW_QuestEN[41320] = { title = "Pry It From Their Cold, Feral Claws", description = "The shield being lowered presents a unique opportunity for new styles.\n\nFeathers, bone and other primitive materials are suddenly fashionable again. Who would have thought they could grow tired of my masterpieces?\n\nVenture out of the city and collect necklaces from the harpies on the southern cliffs. Etching my mark into them should net me a tidy profit.", objectives = "" }
WordHunterWoW_QuestEN[41332] = { title = "Ascending The Circle", description = "Now, you are more powerful than ever! Truly, you are a druid without equal, {name}.\n\nI sense that Malfurion has arrived. He will certainly want to know of your accomplishments, but first, please walk with me a moment.", objectives = "" }
WordHunterWoW_QuestEN[41335] = { title = "The Elements Call...", description = "Nobundo is right. Conventional tactics will not work against the Legion - the Broken Shore taught us that. We must scour the world for weapons to use against the Legion!\n\nThe Doomhammer is missing and must be recovered. Rehgar and Erunak have some other ideas, as well. Whatever our course, we must act immediately.\n\nSpeak with me to go over your options, but the final decision is yours!", objectives = "" }
WordHunterWoW_QuestEN[41367] = { title = "Priority Delivery", description = "An adventurer of another time has forgotten to loot something big... something that might cause them great emotional strain if not received quickly.\n\nYour destination is Icecrown Citadel, your target the Lich King's corpse. Retrieve the missing item post-haste and deliver it to the stalwart adventurer - he should be somewhere at the Steam Pools in Feralas.\n\nMy assistant will open a portal to deliver you there. Just a moment!", objectives = "" }
WordHunterWoW_QuestEN[41368] = { title = "Lost Mail", description = "TO: MADAM GOYA, DALARAN UNDERBELLY\n\nURGENT!\n\nTIME-SENSITIVE! \n\nDELIVER IMMEDIATELY!", objectives = "" }
WordHunterWoW_QuestEN[41394] = { title = "Service with a Smile", description = "Oh, simple {race}. Simple, simple {race}.\n\nI did not 'forget' to sweep up those reins from that foolish cakewalk of a knight they call the Lich King. I simply did not bother, as I already received the mighty steed during my raid last week.\n\n<Johnny motions to the horse on his left.>\n\nSince you're here and clearly intrigued by my sweltering greatness, won't you take that superfluous stallion to the assistant resort director in town? My coffers could use a bit of extra lining.", objectives = "" }
WordHunterWoW_QuestEN[41395] = { title = "Due Reward", description = "You have served me well these past few minutes we've spent together - minutes I shall not soon forget.\n\nI believe a reward befitting your unwavering loyalty is in order. You will have the distinct honor of placing Twinkles' favorite toy by his grave in honor of his memory.\n\nPlease, please - save your thanks for Twinkles; it is not every day that we may honor a horse made of STARS.", objectives = "" }
WordHunterWoW_QuestEN[41397] = { title = "A Huge Package", description = "Due to the incredible volume of complaints in recent months we have been barred from delivering s... s...\n\n<The Postmaster holds back tears, pain visible in his eyes.>\n\nSolid stone. We're positively swimming in it - if we can't deliver it then pretty soon we will be overwh-\n\n<The Postmaster's eyes light up suddenly.>\n\nThat's it!\n\nThere is an old Consortium portal not far from here that we could deposit it in with none the wiser!\n\nCan you help, {name}? The stone is extraordinarily heavy.", objectives = "" }
WordHunterWoW_QuestEN[41409] = { title = "Timing Is Everything", description = "Can you feel it, {name}? The waters churn with approaching Sashj'tar.\n\nYou must strike now...\n\nLeave me... Find a way to bombard the naga... with the kegs...\n\nProtect... Jandvik...", objectives = "" }
WordHunterWoW_QuestEN[41410] = { title = "Dry Powder", description = "{name}... I did not expect to see you down here.\n\nThe Sashj'tar are... rallying against Jandvik. I had a plan to... decimate them using these old powder kegs.\n\nThe naga proved more formidable to these old bones than I thought.\n\n<Fjolrik coughs out some blood.>\n\nWe haven't much time... to prepare.", objectives = "" }
WordHunterWoW_QuestEN[41411] = { title = "Lost Mail", description = "TO: MADAM GOYA, DALARAN UNDERBELLY\n\nURGENT!\n\nTIME-SENSITIVE! \n\nDELIVER IMMEDIATELY!", objectives = "" }
WordHunterWoW_QuestEN[41413] = { title = "What Could Go Wrong?", description = "", objectives = "" }
WordHunterWoW_QuestEN[41415] = { title = "The Hunter's Call", description = "I realize we have never met, but you will learn of my order soon enough. For now, pleasantries must wait.\n\nThe Legion has returned to Azeroth stronger than ever, and we need new weapons to fight them.\n\nI have met three individuals here in Dalaran who have leads on ancient artifacts which could prove vital in the battle to come. Acquiring these weapons demands the skills of a master hunter.\n\nSpeak to each of them and decide whom you will aid first.", objectives = "" }
WordHunterWoW_QuestEN[41422] = { title = "Necessary Preparations", description = "G'Hanir is... is...\n\n<Mylune wipes her eyes, sniffling.>\n\nCorrupted! The Nightmare has risen from the depths of the dream. It all happened so fast...\n\nI was able to secret the staff here through the dream before it fell fully. It rests for now... but I fear we don't have much time.\n\nYou must prepare to retrieve G'Hanir from the Dream. Draw water from the sacred moonwell on the northern edge of the grove and obtain an ancient's blessing.\n\nQuickly - every moment is precious!", objectives = "" }
WordHunterWoW_QuestEN[41425] = { title = "Sunken Foes", description = "The Tidemistress... is filling her ranks with hulking naga... and sea giants.\n\nJandvik cannot withstand... their combined might.\n\nSlaughter them... before they reach its shores...", objectives = "" }
WordHunterWoW_QuestEN[41426] = { title = "Against Their Will", description = "When the naga brought me down here, I saw many of my vrykul mining the sea floor. They had... squids... attached to their faces.\n\nWhatever those things are, they must be controlling my kin and forcing them to work for the naga.\n\nI do not know what will happen if you remove the squids, but I would rather my vrykul die than be slaves to the naga.\n\nSee me in Jandvik when the deed is done.", objectives = "" }
WordHunterWoW_QuestEN[41436] = { title = "In Deep Slumber", description = "This bed will be yours for the deep slumber that will usher you into the Dream.\n\nOnce you are comfortable, drink of the moonwater you brought. I will guide you from there.\n\nQuickly, now - with every passing moment G'Hanir slips further into darkness.", objectives = "" }
WordHunterWoW_QuestEN[41449] = { title = "Join the Dreamer", description = "I'm afraid I can't really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes.\n\nThat's ok, though - Naralex has offered to help!\n\nGo to the very bottom of the Tel'Andu Barrow Den. Naralex is already there setting things up for you.", objectives = "" }
WordHunterWoW_QuestEN[41452] = { title = "Feline Frantic", description = "Greetings, stranger.\n\n<Mayruna bows to you.>\n\nWe arrived from Val'Sharah a short time ago with hopes of settling here. Our journey was not easy and we are weary.\n\nThese owlcats have made a mess of our camp, as you can surely see. Would you be so kind as to assist us with cleaning up?\n\nThen perhaps you can help us establish a new moonwell!", objectives = "" }
WordHunterWoW_QuestEN[41453] = { title = "Homeward Bounding", description = "The first step to establishing a moonwell is to gain the blessings of the local wildlife. \n\nIt is their good will that enables us to  peacefully coexist, and a moonwell thrives on such energies. Combined with Elune's light, a moonwell can purify its surroundings for years.\n\nTo begin, we must find creatures willing to give their blessing. We can start with these owl-cat creatures.\n\nThey ran while you cleaned, but I saw one lingering just before the bridge. \n\nSee if you can find where it lives!", objectives = "" }
WordHunterWoW_QuestEN[41462] = { title = "Trouble Has Huge Feet", description = "The Ettin's hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time.\n\nMardranel Forestheart would be interested in this.", objectives = "" }
WordHunterWoW_QuestEN[41463] = { title = "Missing Along the Way", description = "As we retreated from Val'Sharah, our company was briefly separated by a conflict with some satyrs at the border.\n\nOne of our own did not make it here- Mythandros' brother, Kalendros. I would like you to try and find him if you could.\n\nSearch the woods just before the bridge back into Val'Sharah.", objectives = "" }
WordHunterWoW_QuestEN[41464] = { title = "Not Here, Not Now, Not Ever", description = "I cannot, will not, accept what is happening here. My body resists me, but I will stop this.\n\n<He looks at you.> You will stop this.\n\nHere is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar.\n\nStop them. Kill the satyrs, take their horns, drive their points through the totems.\n\nOnly then can we have any hope of reversing this.", objectives = "" }
WordHunterWoW_QuestEN[41465] = { title = "Estate Jewelry: A Braggart's Brooch", description = "Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers.\n\nNaltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city's elite.\n\nI sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station.\n\nMy pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.", objectives = "" }
WordHunterWoW_QuestEN[41466] = { title = "Estate Jewelry: Haute Claw-ture", description = "An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten.\n\nI was... vain, centuries ago. Desperate to prove myself, I took on a bold commission.\n\nFind him and bring... it... back. You will know what I am talking about when you see it.\n\nHe resides near the villa south of this courtyard.", objectives = "" }
